fn push_const_type_mismatch(
    constant: &Constant,
    declared_ty: &Ty,
    location: &str,
    errors: &mut Vec<ValidationError>,
) {
    errors.push(ValidationError::ConstTypeMismatch {
        location: location.to_string(),
        expected: format!("{declared_ty}"),
        actual: constant.shape_label(),
    });
}

/// Look up a function type and report a validation error when it is missing.
/// Render a list of types as `(t0, t1, ...)` for diagnostics.
fn format_ty_list(tys: &[Ty]) -> String {
    let inner = tys
        .iter()
        .map(|t| format!("{t}"))
        .collect::<Vec<_>>()
        .join(", ");
    format!("({inner})")
}

fn get_func_ty<'a>(
    module: &'a Module,
    func_name: &str,
    func_ty_id: trust_ir::value::FuncTyId,
    errors: &mut Vec<ValidationError>,
) -> Option<&'a FuncTy> {
    match module.func_types.get(func_ty_id.as_usize()) {
        Some(func_ty) => Some(func_ty),
        None => {
            errors.push(ValidationError::FuncTypeNotFound {
                func_name: func_name.to_string(),
                func_ty_id: func_ty_id.index(),
            });
            None
        }
    }
}

/// Validate an entire module, including per-function and cross-function checks.
use rayon::prelude::*;

/// Validate every function and every module-level invariant. This is the
/// authoritative full check; [`validate_changed`] is a sound optimization of it.
/// Trust (#171 Part A): the MODULE-AWARE zero-size test — [`ty_is_zero_sized`] plus the one case
/// spelling alone cannot decide: a `Ty::Struct(sid)` whose own `StructDef` records `size:
/// Some(0)`.
///
/// WHY THIS EXISTS. `ty_is_zero_sized`'s doc says nested structs are treated as non-zero-size
/// because "the check only needs to count the obvious non-ZST fields". That was true until the
/// producers began emitting real Rust layouts. `#[repr(transparent)] struct Unique<T> { pointer:
/// NonNull<T>, _marker: PhantomData<T> }` has TWO fields, of which `PhantomData<T>` is a
/// zero-sized STRUCT — so the spelling-only test counts 2 non-ZST fields and rejects a module
/// that is perfectly well-formed. Five such rejections were measured in the ui corpus, all in the
/// `Unique`/`NonNull`/`PhantomData` family.
///
/// The module HAS the answer already: both producers record the size from rustc's own layout
/// query — the THIR producer at `register_struct` and the MIR-side extractor at its struct
/// lowering — so `size == Some(0)` is rustc's authoritative verdict carried verbatim, not an
/// inference of ours.
///
/// FAIL-CLOSED BY CONSTRUCTION, and this is the load-bearing part. `size: None` returns FALSE,
/// exactly as today. `None` is what both producers record when the layout query declines — a
/// generic/param-bearing type, an unregistered id, a non-faithful lane — so an unproven ZST is
/// still counted as non-ZST and still rejected. The widening admits only defs that carry a
/// PROVEN zero size.
///
/// Deliberately NOT recursive into field types: `size == Some(0)` is the whole answer, and
/// re-deriving it from fields would be a second, weaker computation that could disagree with the
/// one rustc actually performed.
///
/// The definition is the FIRST with the id, found through the pass's layout
/// table (O(1) amortized) rather than by scanning the struct list per field.
fn ty_is_zero_sized_in(layouts: &trust_ir::LayoutTable<'_>, ty: &trust_ir::Ty) -> bool {
    if ty_is_zero_sized(ty) {
        return true;
    }
    match ty {
        trust_ir::Ty::Struct(sid) => layouts
            .struct_def(*sid)
            .is_some_and(|sd| sd.size == Some(0)),
        _ => false,
    }
}

/// Whether `ty` has the exact size-zero, alignment-one layout that rustc calls a
/// 1-ZST for `repr(transparent)`.
///
/// Size alone is deliberately insufficient: `#[repr(align(8))] struct Marker;`
/// is a ZST, but it is a non-trivial transparent field because the wrapper must
/// inherit its alignment. `ty_layout_shape` also makes unresolved layout count
/// as non-trivial, which is the fail-closed answer when two fields could both
/// become the representation-bearing field.
fn ty_is_one_zst_in(layouts: &trust_ir::LayoutTable<'_>, ty: &trust_ir::Ty) -> bool {
    layouts
        .ty_layout(ty)
        .is_ok_and(|layout| layout.size_bits == 0 && layout.align_bits == Some(8))
}

/// Conservative zero-size-type test: the unit type, the empty tuple, and a zero-length array are
/// zero-sized. Anything else — INCLUDING a nested struct that may itself be a ZST — is treated as
/// non-zero-size, because the spelling alone cannot prove it.
///
/// Prefer [`ty_is_zero_sized_in`] wherever the `Module` is in scope: it resolves exactly that
/// nested-struct case against the recorded layout. This spelling-only form remains for callers
/// with no module context, where treating an unresolvable type as non-ZST is the fail-closed
/// answer.
fn ty_is_zero_sized(ty: &trust_ir::Ty) -> bool {
    use trust_ir::Ty;
    match ty {
        Ty::Unit => true,
        Ty::Tuple(elems) => elems.is_empty(),
        Ty::Array(_, 0) => true,
        _ => false,
    }
}

// The one byte-range overlap predicate, shared with the layout authority (and
// with its sweeps `any_byte_ranges_overlap` / `overlapping_byte_range_pairs`).
use trust_ir::shape::byte_ranges_overlap;

/// The prefix of a [`ValidationError::TupleLayoutInconsistent`] reason that
/// reports a `Module.closure_layouts` row (wire v58) rather than a tuple row.
/// The rest of the reason is the layout authority's own message.
pub const CLOSURE_LAYOUT_TABLE_REASON_PREFIX: &str = "Module.closure_layouts: ";

/// The `StructLayoutInconsistent` reason for a declared struct layout that the
/// layout authority (`Module::ty_layout_shape`) refuses as
/// `LayoutError::StructLayoutIncoherent` while none of the precise rules of
/// `validate_struct_layout_rules` fired — a field whose EXTENT runs past the
/// declared size, a `repr(packed)` / `repr(transparent)` defect, a field
/// alignment above the struct's, or an inline struct cycle.
pub const STRUCT_LAYOUT_INCOHERENT_REASON: &str =
    "declared layout is incoherent (overlap / containment / alignment / packed / transparent rule)";

/// The `StructLayoutInconsistent` reason for two declared field byte ranges
/// that intersect (WS2.3 / F-031). The reason string is the machine-readable
/// name of the refusal and is unchanged since WS2.3.
pub const STRUCT_FIELDS_OVERLAP_REASON: &str = "fields overlap";

/// What the rendered [`ValidationError::StructLayoutInconsistent`] appends
/// after [`STRUCT_FIELDS_OVERLAP_REASON`] (roadmap WS3.18, F-050). A struct
/// whose fields share offset 0 is how a producer naturally spells a union, and
/// the format's union spelling is a different construct (G18-3), so the
/// refusal says where to go instead of only what is wrong. Only the overlap
/// reason carries it. Every other layout reason renders as before.
pub const STRUCT_FIELDS_OVERLAP_CARRIER_HINT: &str = " (a union is not a struct: spell it on the \
     byte-overlap carrier, an [u8; N] Alloca or global sized and aligned for the union, with \
     every field place at the carrier base and a typed Load/Store per access; \
     lowering-target-subset.md \"Unions\", G18-3)";

/// Every struct's EXPLICITLY-declared layout must be internally consistent —
/// with or without a pinned target (WS2.3 / F-031). Only fires on fields that
/// are actually set (`Some(..)`); `None` (deferred to the backend) is never
/// flagged. A target-free module is judged against the canonical reference
/// layout, which is what `Module::ty_layout_shape` (shape.rs,
/// `target_has_canonical_scalar_layout`) and the interpreter already use for
/// it; the only genuinely target-dependent clause,
/// `TargetScalarLayoutUnavailable`, can fire only under a pinned,
/// non-canonical target.
///
/// Invariants checked:
/// * `align`, when set, is a non-zero power of two;
/// * `size`, when both it and `align` are set, is a multiple of `align`
///   (C and Rust both round struct size up to a multiple of alignment);
/// * each field `offset`, when both it and `size` are set, is `< size`, except
///   that a conservatively recognized zero-sized field may sit at `size`;
/// * no two declared field byte ranges `[offset, offset + size)` intersect
///   (`"fields overlap"` — the same `byte_ranges_overlap` predicate the layout
///   authority and the interpreter use, so zero-sized fields never overlap);
/// * each field offset is a multiple of the field's effective alignment.
fn validate_struct_layout_rules(layouts: &trust_ir::LayoutTable<'_>) -> Vec<ValidationError> {
    // The module is the table's, so the two cannot disagree.
    let module = layouts.module();
    let mut errors = Vec::new();
    for sd in &module.structs {
        let sid = sd.id.index();
        let reported_before = errors.len();
        if let Some(align) = sd.align
            && (align == 0 || !align.is_power_of_two())
        {
            errors.push(ValidationError::StructLayoutInconsistent {
                struct_id: sid,
                reason: "align must be a non-zero power of two",
            });
        }
        if let (Some(size), Some(align)) = (sd.size, sd.align)
            && align != 0
            && align.is_power_of_two()
            && size % align != 0
        {
            errors.push(ValidationError::StructLayoutInconsistent {
                struct_id: sid,
                reason: "size must be a multiple of align",
            });
        }
        if let Some(size) = sd.size {
            for field in &sd.fields {
                // A trailing ZST may legally sit exactly at the struct size
                // (`#[repr(C)] struct { a: u32, b: () }` has `b` at offset 4
                // and size 4). Keep equality fail-closed for every type that
                // `ty_is_zero_sized` cannot prove is a ZST: accepting an
                // ordinary field there would place it outside the allocation.
                // Trust (#171 Part A): module-aware for the same reason — a trailing
                // zero-sized STRUCT legally sits at exactly the struct size.
                if let Some(offset) = field.offset
                    && (offset > size
                        || (offset == size && !ty_is_zero_sized_in(layouts, &field.ty)))
                {
                    errors.push(ValidationError::StructLayoutInconsistent {
                        struct_id: sid,
                        reason: "field offset is outside the declared struct size",
                    });
                    // One report per struct is enough to flag the inconsistency.
                    break;
                }
            }
        }
        // WS2.3 (F-031): THE PAIRWISE-OVERLAP RULE, which this pass never had
        // although enum descriptors always did. The layout authority
        // (`shape.rs`, `LayoutError::StructLayoutIncoherent`) and the
        // interpreter ("declared layout has overlapping fields") both refuse a
        // struct whose declared field byte ranges intersect, so a validator
        // that passed one called a module well-formed that no consumer could
        // lay out or run. Field ORDER is deliberately not a rule (`repr(Rust)`
        // reorders fields); only the byte ranges are compared. A byte-overlap
        // UNION is not spelled this way — the ratified model is an untyped byte
        // carrier with typed accesses at one address (`lowering-target-subset.md`,
        // "Unions"), which declares no overlapping fields. Runs only when the
        // rules above found this struct coherent, so one defect is one report.
        if errors.len() == reported_before {
            let mut ranges: Vec<(u64, u64)> = Vec::with_capacity(sd.fields.len());
            for field in &sd.fields {
                let Some(offset) = field.offset else { continue };
                // A field whose size the layout authority cannot give (an
                // unavailable target ABI, reported by the alignment rule below;
                // a shape with no layout) is not compared here — `shape`
                // refuses the whole struct in that case anyway.
                let Some(field_size) = layouts
                    .ty_layout(&field.ty)
                    .ok()
                    .and_then(|layout| layout.size_bytes())
                else {
                    continue;
                };
                ranges.push((offset, field_size));
            }
            // One report for the struct when SOME pair overlaps: the same
            // verdict as testing every pair, in O(f log f).
            if trust_ir::shape::any_byte_ranges_overlap(&ranges) {
                errors.push(ValidationError::StructLayoutInconsistent {
                    struct_id: sid,
                    reason: STRUCT_FIELDS_OVERLAP_REASON,
                });
            }
        }
        // Trust (wave-SG): THE FIELD-OFFSET ALIGNMENT RULE, which this pass never had.
        // The three checks above police `align`, `size % align` and `offset <= size` —
        // none of which notices a `u64` declared at byte 3. `interpret::struct_layout`
        // has re-validated exactly that since the declared layout became NORMATIVE, so
        // an offset this validator passes and the interpreter refuses is a module the
        // validator called well-formed and the executor cannot run. Same rule, same
        // clamp, stated here so `validate_module` and the interpreter agree on what a
        // coherent struct descriptor IS.
        //
        // Runs on its own loop because it is independent of `size`: a struct may
        // declare offsets and no size. `repr(packed(N))` clamps every field's
        // alignment to `min(natural, N)`; a `Packed(N)` whose `N` is not a power of two
        // is reported separately as `PackedReprInvalidAlign`, and here it DISABLES the
        // rule rather than being divided by, so one malformed repr produces one error
        // and not a cascade of derived ones.
        let clamp = match sd.repr {
            trust_ir::StructRepr::Packed(n) if n != 0 && n.is_power_of_two() => Some(u64::from(n)),
            trust_ir::StructRepr::Packed(_) => continue,
            _ => None,
        };
        if let (Some(clamp), Some(align)) = (clamp, sd.align)
            && align > clamp
        {
            errors.push(ValidationError::StructLayoutInconsistent {
                struct_id: sid,
                reason: "struct alignment exceeds the repr(packed) clamp",
            });
            // The field rule below remains meaningful, but one structural error
            // per struct is the existing reporting contract.
            continue;
        }
        for field in &sd.fields {
            let Some(offset) = field.offset else { continue };
            let natural = match layouts.ty_layout(&field.ty) {
                Ok(layout) => {
                    let Some(bits) = layout.align_bits else {
                        continue;
                    };
                    if bits == 0 || !bits.is_multiple_of(8) {
                        continue;
                    }
                    bits / 8
                }
                Err(trust_ir::LayoutError::TargetScalarLayoutUnavailable { triple }) => {
                    errors.push(ValidationError::TargetScalarLayoutUnavailable {
                        struct_id: sid,
                        triple,
                    });
                    // An unknown target ABI is not evidence that the offset is
                    // aligned. Refuse this declared layout instead of applying
                    // TrustIR's reference-target table to a different target.
                    break;
                }
                Err(_) => continue,
            };
            let effective = clamp.map_or(natural, |c| natural.min(c));
            if effective != 0 && offset % effective != 0 {
                errors.push(ValidationError::StructLayoutInconsistent {
                    struct_id: sid,
                    reason: "field offset is not a multiple of the field's effective alignment",
                });
                // One report per struct, matching the rule above.
                break;
            }
        }
    }
    errors
}

/// WS2.3 (F-031): ONE coherence rule for declared struct layouts, shared with
/// the layout authority and run with or without `target_info`.
///
/// First the precise rules of `validate_struct_layout_rules`; then, for
/// every `StructDef` that declares both `size` and `align` and drew no report
/// from them, `Module::ty_layout_shape(&Ty::Struct(id))` itself:
///
/// * `StructLayoutIncoherent(id)` for THIS struct becomes
///   `StructLayoutInconsistent { reason: STRUCT_LAYOUT_INCOHERENT_REASON }` —
///   whatever `shape` refuses (containment of a field's extent, packed or
///   transparent rule, field alignment above the struct's, an inline cycle)
///   the validator refuses too. An incoherence the walk found in a NESTED
///   struct names that struct and is reported on its own iteration;
/// * `TargetScalarLayoutUnavailable` stays `TargetScalarLayoutUnavailable`
///   (it can arise only under a pinned, non-canonical target);
/// * `MissingFieldOffset` is deliberately SKIPPED: refusing a partial layout
///   is a tightening F-031 does not ask for, and its blast radius over the
///   producer corpora is unmeasured. The layout stays refused at use time by
///   `shape` and the interpreter, so this is fail-closed either way;
/// * every other layout error (a missing referenced definition, a field
///   shape with no layout) is reported elsewhere or is not a declared-layout
///   defect, and is skipped.
///
/// One struct gets one error: the generic report fires only when no precise
/// rule already named the struct — neither a rule of this pass nor a struct
/// repr rule in `prior` (`PackedReprInvalidAlign` / `TransparentReprFieldCount`
/// describe the very defect `shape` then refuses; one malformed repr stays
/// one error, not a cascade).
fn validate_declared_struct_layouts(
    layouts: &trust_ir::LayoutTable<'_>,
    prior: &[ValidationError],
) -> Vec<ValidationError> {
    // The module is the table's, so the two cannot disagree.
    let module = layouts.module();
    fn struct_scoped(error: &ValidationError) -> Option<u32> {
        match error {
            ValidationError::StructLayoutInconsistent { struct_id, .. }
            | ValidationError::TargetScalarLayoutUnavailable { struct_id, .. }
            | ValidationError::PackedReprInvalidAlign { struct_id, .. }
            | ValidationError::TransparentReprFieldCount { struct_id, .. } => Some(*struct_id),
            _ => None,
        }
    }
    let mut errors = validate_struct_layout_rules(layouts);
    let already_reported: BTreeSet<u32> = prior
        .iter()
        .chain(errors.iter())
        .filter_map(struct_scoped)
        .collect();
    for sd in &module.structs {
        let sid = sd.id.index();
        if sd.size.is_none() || sd.align.is_none() || already_reported.contains(&sid) {
            continue;
        }
        match layouts.ty_layout(&trust_ir::Ty::Struct(sd.id)) {
            Err(trust_ir::LayoutError::StructLayoutIncoherent(id)) if id == sd.id => {
                errors.push(ValidationError::StructLayoutInconsistent {
                    struct_id: sid,
                    reason: STRUCT_LAYOUT_INCOHERENT_REASON,
                });
            }
            Err(trust_ir::LayoutError::TargetScalarLayoutUnavailable { triple }) => {
                errors.push(ValidationError::TargetScalarLayoutUnavailable {
                    struct_id: sid,
                    triple,
                });
            }
            _ => {}
        }
    }
    errors
}

/// ABI pinning: a bodyless `external` function is an FFI import declaration —
/// its ABI is the cross-object contract with an external definition. A by-value
/// `Ty::Struct` in its signature whose `StructRepr` is `Rust` (layout
/// unspecified) cannot be matched byte-for-byte by the other object, so the
/// boundary must use an explicit, stable repr. Reject each such parameter or
/// return position. This is the validator-side of the "Rust↔C struct-passing
/// disagreement is rejected" acceptance criterion.
fn validate_ffi_struct_repr(module: &Module) -> Vec<ValidationError> {
    use trust_ir::Ty;
    let mut errors = Vec::new();

    // repr per struct id, for quick lookup.
    let repr_of: BTreeMap<u32, trust_ir::StructRepr> = module
        .structs
        .iter()
        .map(|sd| (sd.id.index(), sd.repr))
        .collect();
    let unpinned = |ty: &Ty| -> Option<u32> {
        if let Ty::Struct(sid) = ty {
            let id = sid.index();
            // A struct missing from the table is a dangling reference flagged
            // elsewhere; only flag repr on structs that actually exist and are
            // declared `repr(Rust)` (the unspecified-layout case).
            if matches!(repr_of.get(&id), Some(trust_ir::StructRepr::Rust)) {
                return Some(id);
            }
        }
        None
    };

    for func in &module.functions {
        // Trust (#180): only a FOREIGN-ABI boundary. A `repr(Rust)` aggregate crossing a
        // Rust-ABI cross-crate call is not an ABI hazard — both sides are the same compiler and
        // agree on the layout by construction. Flagging those made this the second-largest
        // validation class (253 occurrences) entirely from Rust-to-Rust declarations.
        if !is_foreign_abi_boundary(func) {
            continue;
        }
        let Some(func_ty) = module.func_types.get(func.ty.as_usize()) else {
            continue;
        };
        for param in &func_ty.params {
            if let Some(sid) = unpinned(param) {
                errors.push(ValidationError::FfiStructReprUnpinned {
                    func_name: func.name.clone(),
                    struct_id: sid,
                    position: "parameter",
                });
            }
        }
        for ret in &func_ty.returns {
            if let Some(sid) = unpinned(ret) {
                errors.push(ValidationError::FfiStructReprUnpinned {
                    func_name: func.name.clone(),
                    struct_id: sid,
                    position: "return",
                });
            }
        }
    }
    errors
}

/// `docs/SPEC_RATIFICATIONS.md` §17: under `StructPassingPolicy::AlwaysMemory`
/// every aggregate crossing is PRE-LOWERED, so no `FuncTy` of the module may
/// have a by-value aggregate slot (`Module::is_by_value_aggregate_slot`, the
/// one predicate). The whole `func_types` table is scanned — a superset of the
/// call edges, which also holds a signature only a `CallIndirect` names. Under
/// `NativeC` / `Unclassified` (or with no `TargetInfo`) this decides nothing:
/// there the consumer classifies, or refuses.
fn validate_always_memory_struct_passing(module: &Module) -> Vec<ValidationError> {
    let always_memory = module
        .target_info
        .as_ref()
        .is_some_and(|t| t.struct_passing == trust_ir::StructPassingPolicy::AlwaysMemory);
    if !always_memory {
        return Vec::new();
    }
    let mut errors = Vec::new();
    for (index, func_ty) in module.func_types.iter().enumerate() {
        let slots = func_ty
            .params
            .iter()
            .enumerate()
            .map(|(i, ty)| (format!("parameter {i}"), ty))
            .chain(
                func_ty
                    .returns
                    .iter()
                    .enumerate()
                    .map(|(i, ty)| (format!("return {i}"), ty)),
            );
        for (slot, ty) in slots {
            if module.is_by_value_aggregate_slot(ty) {
                errors.push(ValidationError::AlwaysMemoryByValueAggregate {
                    func_ty: u32::try_from(index).unwrap_or(u32::MAX),
                    slot,
                    ty: ty.to_string(),
                });
            }
        }
    }
    errors
}

/// ABI pinning: `byval`/`sret` placement. Both classify how an aggregate
/// crosses a call edge through MEMORY, so they only make sense on
/// pointer-typed parameters inside the signature; `sret` marks THE single
/// caller-allocated return slot (and the value then cannot also be returned
/// by value). A function whose `FuncTyId` dangles is skipped here — the
/// dangling reference is flagged elsewhere.
fn validate_param_abi_attrs(module: &Module) -> Vec<ValidationError> {
    let mut errors = Vec::new();
    for func in &module.functions {
        let Some(func_ty) = module.func_types.get(func.ty.as_usize()) else {
            continue;
        };
        let mut sret_seen = false;
        for (i, pa) in func.attrs.params.iter().enumerate() {
            if !pa.byval && !pa.sret {
                continue;
            }
            let Some(param_ty) = func_ty.params.get(i) else {
                errors.push(ValidationError::ParamAbiAttrInvalid {
                    func_name: func.name.clone(),
                    param_index: i,
                    reason: "attribute is positioned past the signature's parameters",
                });
                continue;
            };
            if pa.byval && pa.sret {
                errors.push(ValidationError::ParamAbiAttrInvalid {
                    func_name: func.name.clone(),
                    param_index: i,
                    reason: "byval and sret are mutually exclusive on one parameter",
                });
            }
            if !matches!(
                param_ty,
                Ty::Ptr | Ty::PtrConst(_) | Ty::PtrMut(_) | Ty::Ref(_) | Ty::RefMut(_)
            ) {
                errors.push(ValidationError::ParamAbiAttrInvalid {
                    func_name: func.name.clone(),
                    param_index: i,
                    reason: "byval/sret require a pointer-typed parameter",
                });
            }
            if pa.sret {
                if sret_seen {
                    errors.push(ValidationError::ParamAbiAttrInvalid {
                        func_name: func.name.clone(),
                        param_index: i,
                        reason: "at most one parameter may be sret",
                    });
                }
                sret_seen = true;
                if !func_ty.returns.is_empty() {
                    errors.push(ValidationError::ParamAbiAttrInvalid {
                        func_name: func.name.clone(),
                        param_index: i,
                        reason: "sret marks the return slot, so the signature must return no values",
                    });
                }
            }
        }
    }
    errors
}

/// Which cross-crate faith floor a [`ValidationConfig`] selects when it is
/// run by [`validate_module_with_config`] (the linked walk always runs its own
/// authenticated policy and ignores this).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ConfigImportPolicy {
    /// No authority was supplied: the structural v41 faith floor of
    /// [`validate_module`].
    Structural,
    /// An authority was supplied: every proof-bearing import row is
    /// [`ValidationError::UnauthenticatedImport`], exactly as
    /// [`validate_module_report_with_authority`] reports it.
    Refuse,
}

/// The ONE set of knobs every composed validation entry point is a wrapper
/// over: the proof authority, the handle-runtime registry, the optional closed
/// dialect-schema registry, and whether the caller validates with CODEGEN
/// intent.
///
/// # Why one options struct
///
/// Before it existed each composition was its own hard-wired function:
/// [`validate_module_for_codegen`] and [`validate_module_report_with_authority`]
/// both pinned [`HandleRegistry::pinned`], the codegen lane could not take an
/// authority, and [`crate::validate_linked_module`] could take neither a
/// registry nor codegen intent. A consumer that needed two of them at once had
/// to re-compose the layers by hand. Every existing entry point is now a thin
/// wrapper over [`ValidationConfig::pinned`] plus at most one builder call, so
/// they cannot drift from the composed lane.
///
/// # Defaults, and what they refuse
///
/// [`ValidationConfig::pinned`] is exactly [`validate_module`]:
/// [`trust_ir::proof::RejectingModuleProofAuthority`], the pinned registry, no
/// dialect schemas, no codegen layers, and the structural import faith floor.
/// Nothing here admits anything the pinned registry refuses when the caller
/// keeps [`HandleRegistry::pinned`].
///
/// * [`Self::with_authority`] supplies a replay capability AND switches the
///   import policy to REFUSE every proof-bearing cross-crate row
///   ([`ValidationError::UnauthenticatedImport`]) — the contract of
///   [`validate_module_report_with_authority`], because a capability still
///   holds no dependency module. Passing the rejecting authority through it
///   is exactly [`validate_module_with_authority`] with that authority.
/// * [`Self::with_handle_registry`] substitutes the handle-runtime pin table.
///   **A registry other than the pinned one is a caller-owned TCB
///   extension**: every row it adds is an entry point the caller vouches for.
///   The report records which case applied
///   ([`ModuleValidationReport::handle_registry_is_pinned`]); a consumer that
///   COMPILES what it admits must check that bit (or re-read the pinned table
///   itself) before trusting a handle-bearing module. Must-refuse corpus row
///   `refuse/handle_runtime_unpinned`: a handle naming a runtime the pinned
///   table lacks, refused under the pinned registry as
///   `UntrustedHandleRuntime`.
/// * [`Self::with_codegen`] appends [`codegen_license_errors`],
///   [`codegen_lowerability_errors`] and [`codegen_global_asm_errors`] after
///   the structural errors — composition, not duplication, exactly as
///   [`validate_module_for_codegen`] always has.
///
/// # The linked walk
///
/// [`crate::validate_linked_module_with_config`] validates EVERY module in
/// the closure — root and dependencies alike — under the same config. There
/// is no per-dependency config, and the walk's per-digest memo is local to one
/// call, so a dependency verdict earned under a permissive registry is never
/// reused by a later walk under [`ValidationConfig::pinned`].
#[derive(Clone, Copy)]
pub struct ValidationConfig<'a> {
    authority: &'a dyn trust_ir::proof::ModuleProofAuthority,
    handle_registry: &'a HandleRegistry,
    dialect_schemas: Option<&'a trust_ir::dialect::schema::DialectSchemaRegistry>,
    codegen: bool,
    import_policy: ConfigImportPolicy,
    require_bound_certificates: bool,
    require_source_bound_certificates: bool,
    require_gate_evidence: bool,
}

impl std::fmt::Debug for ValidationConfig<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ValidationConfig")
            .field(
                "handle_registry_is_pinned",
                &self.handle_registry_is_pinned(),
            )
            .field("dialect_schemas", &self.dialect_schemas.is_some())
            .field("codegen", &self.codegen)
            .field("import_policy", &self.import_policy)
            .field(
                "require_bound_certificates",
                &self.require_bound_certificates,
            )
            .field(
                "require_source_bound_certificates",
                &self.require_source_bound_certificates,
            )
            .field("require_gate_evidence", &self.require_gate_evidence)
            .finish_non_exhaustive()
    }
}

impl<'a> ValidationConfig<'a> {
    /// The configuration of [`validate_module`]: the rejecting authority, the
    /// pinned handle registry, no dialect schemas, no codegen layers, and the
    /// structural import faith floor.
    #[must_use]
    pub fn pinned() -> Self {
        Self {
            authority: &trust_ir::proof::RejectingModuleProofAuthority,
            handle_registry: HandleRegistry::pinned(),
            dialect_schemas: None,
            codegen: false,
            import_policy: ConfigImportPolicy::Structural,
            require_bound_certificates: false,
            require_source_bound_certificates: false,
            require_gate_evidence: false,
        }
    }

    /// Require every `Certified` obligation's `CleanCic` certificate to carry
    /// a [`trust_ir::proof::CertificateBinding`] (roadmap WS1.12a): a
    /// directive-less certificate, or a directive whose `binding` is `None`,
    /// is then [`ValidationError::UnboundCertificate`]. Off by default —
    /// `None` is UNBOUND, the pre-binding meaning every existing certificate
    /// keeps — and a present binding is checked under every config, so this
    /// knob only decides whether an unbound one is admitted. A consumer whose
    /// trust argument needs every kernel certificate to name the environment
    /// and statement it was checked in turns it on.
    #[must_use]
    pub fn with_bound_certificates(mut self, required: bool) -> Self {
        self.require_bound_certificates = required;
        self
    }

    /// Whether unbound `CleanCic` certificates are refused
    /// ([`Self::with_bound_certificates`]).
    #[must_use]
    pub fn require_bound_certificates(&self) -> bool {
        self.require_bound_certificates
    }

    /// Require every `Certified` `clean_backend_tv` certificate to be
    /// SOURCE-BOUND (roadmap WS1.13, finding F-008): its binding must carry an
    /// island ([`trust_ir::proof::CertificateBinding::environment`]), in which
    /// the re-check proves the comparand is the value of `source.decl`. An
    /// island-free certificate — bound or not — is then
    /// [`ValidationError::CertificateBindingMismatch`] with field
    /// `"environment"`. Off by default: an island-free certificate keeps its
    /// MINT-TIME meaning ("the emitted function denotes the recorded
    /// comparand"; that the comparand is the source is the minter's word),
    /// and a present island is checked under every config. A consumer whose
    /// argument needs the emitted code to be an island's declared source — so
    /// that the island's theorems bridge to the code — turns this on. What the
    /// island declares is still the producer's word about the source text
    /// (`SourceDefinitionRef::closure_digest` is carried, never re-derived).
    #[must_use]
    pub fn with_source_bound_certificates(mut self, required: bool) -> Self {
        self.require_source_bound_certificates = required;
        self
    }

    /// Whether island-free `clean_backend_tv` certificates are refused
    /// ([`Self::with_source_bound_certificates`]).
    #[must_use]
    pub fn require_source_bound_certificates(&self) -> bool {
        self.require_source_bound_certificates
    }

    /// Require every body licensed by an EVIDENCE-BOUND authority
    /// (`EVIDENCE_BOUND_GATE_AUTHORITIES`) to record [`trust_ir::GateEvidence`]
    /// (binary v61, roadmap WS1.12(c)): an evidence-free license is then
    /// [`ValidationError::UnevidencedGate`]. Off by default — `None` is NO
    /// EVIDENCE RECORDED, the meaning of every pre-v61 license — and a
    /// PRESENT evidence is checked under every config, so this knob only
    /// decides whether an absent one is admitted.
    #[must_use]
    pub fn with_gate_evidence(mut self, required: bool) -> Self {
        self.require_gate_evidence = required;
        self
    }

    /// Whether evidence-free licenses by evidence-bound authorities are
    /// refused ([`Self::with_gate_evidence`]).
    #[must_use]
    pub fn require_gate_evidence(&self) -> bool {
        self.require_gate_evidence
    }

    /// Supply a proof-replay capability. This also REFUSES every proof-bearing
    /// cross-crate row on the single-module lane (see the type docs); the
    /// linked walk authenticates them instead.
    #[must_use]
    pub fn with_authority(
        mut self,
        authority: &'a dyn trust_ir::proof::ModuleProofAuthority,
    ) -> Self {
        self.authority = authority;
        self.import_policy = ConfigImportPolicy::Refuse;
        self
    }

    /// Substitute the handle-runtime registry — a caller-owned TCB extension
    /// unless it is the pinned one (see [`Self::handle_registry_is_pinned`]).
    #[must_use]
    pub fn with_handle_registry(mut self, registry: &'a HandleRegistry) -> Self {
        self.handle_registry = registry;
        self
    }

    /// Require every dialect instruction to belong to `schemas` (the
    /// [`validate_module_with_dialect_schemas`] layer).
    #[must_use]
    pub fn with_dialect_schemas(
        mut self,
        schemas: &'a trust_ir::dialect::schema::DialectSchemaRegistry,
    ) -> Self {
        self.dialect_schemas = Some(schemas);
        self
    }

    /// Validate with (or without) codegen intent: `true` appends the license,
    /// lowerability and `global_asm` refusals of [`validate_module_for_codegen`].
    #[must_use]
    pub fn with_codegen(mut self, codegen: bool) -> Self {
        self.codegen = codegen;
        self
    }

    /// The proof authority this config validates under.
    #[must_use]
    pub fn authority(&self) -> &'a dyn trust_ir::proof::ModuleProofAuthority {
        self.authority
    }

    /// The handle-runtime registry this config validates under.
    #[must_use]
    pub fn handle_registry(&self) -> &'a HandleRegistry {
        self.handle_registry
    }

    /// The closed dialect-schema registry, if one was supplied.
    #[must_use]
    pub fn dialect_schemas(&self) -> Option<&'a trust_ir::dialect::schema::DialectSchemaRegistry> {
        self.dialect_schemas
    }

    /// Whether the codegen layers run.
    #[must_use]
    pub fn codegen(&self) -> bool {
        self.codegen
    }

    /// Whether the handle registry is the pinned one: the very
    /// [`HandleRegistry::pinned`] instance, or a registry whose rows are
    /// exactly [`TRUSTED_HANDLE_RUNTIMES`] in the same order. Any other
    /// registry — a superset, a subset, a reordering, a changed signature —
    /// reports `false`: the bit is conservative, never a guess.
    #[must_use]
    pub fn handle_registry_is_pinned(&self) -> bool {
        let pinned = HandleRegistry::pinned();
        std::ptr::eq(self.handle_registry, pinned) || self.handle_registry.pins() == pinned.pins()
    }

    fn module_import_policy(&self) -> ImportPolicy<'static> {
        match self.import_policy {
            ConfigImportPolicy::Structural => ImportPolicy::Structural,
            ConfigImportPolicy::Refuse => ImportPolicy::Refuse,
        }
    }
}

/// The three codegen-intent layers, in the order
/// [`validate_module_for_codegen`] has always appended them.
///
/// The license layer is [`codegen_license_errors`]'s, read against `replayed`
/// — the kernel-tier set the structural pass over the SAME module just
/// replayed (roadmap WS1.5) — so the evidence rule never re-runs the kernel.
fn codegen_intent_errors(
    module: &Module,
    replayed: &BTreeSet<trust_ir::proof::ProofCertificateRef>,
) -> Vec<ValidationError> {
    let mut errors = license_errors_against(module, replayed, None, UnlicensedBodyPolicy::Refuse);
    errors.extend(codegen_lowerability_errors(module));
    errors.extend(codegen_global_asm_errors(module));
    errors
}

/// Append the codegen layers when `config` asks for them. Shared by the
/// single-module lane and every module the linked walk validates; `replayed`
/// is the kernel-tier set the caller's structural pass over `module`
/// returned.
pub(crate) fn extend_with_config_codegen_errors(
    errors: &mut Vec<ValidationError>,
    module: &Module,
    replayed: &BTreeSet<trust_ir::proof::ProofCertificateRef>,
    config: &ValidationConfig<'_>,
) {
    if config.codegen {
        errors.extend(codegen_intent_errors(module, replayed));
    }
}

/// Append [`ValidationError::UnboundCertificate`] for every `Certified`
/// obligation whose lineage-bound `CleanCic` certificate carries no binding,
/// when `config` requires bound certificates. Shared by the single-module
/// lane and every module the linked walk validates, so one config decides
/// for the whole closure.
pub(crate) fn extend_with_config_binding_errors(
    errors: &mut Vec<ValidationError>,
    module: &Module,
    config: &ValidationConfig<'_>,
) {
    if config.require_bound_certificates {
        errors.extend(unbound_certificate_errors(module));
    }
    if config.require_source_bound_certificates {
        errors.extend(source_unbound_certificate_errors(module));
    }
    if config.require_gate_evidence {
        errors.extend(unevidenced_gate_errors(module));
    }
}

/// The `Certified` obligations whose lineage-bound `clean_backend_tv`
/// certificate carries no island (roadmap WS1.13) — refused under
/// [`ValidationConfig::with_source_bound_certificates`]. As in
/// [`unbound_certificate_errors`], a row with no lineage-bound certificate is
/// left to `validate_certified_evidence`, which already names it.
fn source_unbound_certificate_errors(module: &Module) -> Vec<ValidationError> {
    use trust_ir::proof::{KERNEL_ANCHOR_CLEAN_BACKEND_TV, ProofEvidence, clean_cic_lineage_binds};
    let function_catalog = ModuleFunctionCatalog::new(module);
    let resolve = |id: FuncId| function_catalog.unique(id).map(|f| f.name.clone());
    module
        .proof_obligations
        .iter()
        .filter(|obligation| obligation.status.is_kernel_tier())
        .filter(|obligation| {
            module.proof_certificates.iter().any(|certificate| {
                certificate.obligation == obligation.id
                    && matches!(
                        &certificate.evidence,
                        ProofEvidence::CleanCic { term, kernel_recheck: Some(recheck), .. }
                            if !term.is_empty()
                                && (recheck.anchor == KERNEL_ANCHOR_CLEAN_BACKEND_TV
                                    || trust_ir::proof::is_clean_source_call_anchor(&recheck.anchor))
                                && recheck
                                    .binding
                                    .as_deref()
                                    .is_none_or(|binding| binding.environment.is_none())
                    )
                    && clean_cic_lineage_binds(obligation, &certificate.evidence, &resolve)
            })
        })
        .map(|obligation| ValidationError::CertificateBindingMismatch {
            obligation: obligation.id.index(),
            field: "environment".to_string(),
            detail: "the clean_backend_tv certificate carries no island, so its comparand is the \
                     minter's word, not a checked source declaration; \
                     with_source_bound_certificates requires every translation-validation \
                     certificate to be source-bound through one (WS1.13, F-008)"
                .to_string(),
        })
        .collect()
}

/// The bodies licensed by an evidence-bound authority whose license records
/// no [`trust_ir::GateEvidence`] ([`ValidationConfig::require_gate_evidence`]).
fn unevidenced_gate_errors(module: &Module) -> Vec<ValidationError> {
    module
        .functions
        .iter()
        .filter(|func| !func.is_declaration())
        .filter_map(|func| match &func.body_gate {
            Some(trust_ir::BodyGate::Gated {
                authority,
                evidence: None,
            }) if gate_evidence_rule(authority).is_some() => {
                Some(ValidationError::UnevidencedGate {
                    function: func.id.index(),
                    authority: authority.clone(),
                })
            }
            _ => None,
        })
        .collect()
}

/// A PRESENT [`trust_ir::GateEvidence`] must hold (roadmap WS1.12(c)): the
/// cited obligation is the one `Certified` `TranslationValidation` row scoped
/// to the licensed function, and the recorded body digest is the body's
/// digest now. Structural — no replay is needed to see either — so every lane
/// refuses a false one ([`ValidationError::GatedEvidenceMismatch`]). Whether
/// that row's certificate re-checks is the codegen layer's question (WS1.5).
fn gate_evidence_errors(module: &Module) -> Vec<ValidationError> {
    use trust_ir::proof::{ObligationKind, ProofStatus};
    let mut errors = Vec::new();
    for func in &module.functions {
        let Some(trust_ir::BodyGate::Gated {
            evidence: Some(evidence),
            ..
        }) = &func.body_gate
        else {
            continue;
        };
        let mismatch = |detail: String| ValidationError::GatedEvidenceMismatch {
            function: func.id.index(),
            detail,
        };
        let cited: Vec<&trust_ir::proof::ProofObligation> = module
            .proof_obligations
            .iter()
            .filter(|o| o.id == evidence.obligation)
            .collect();
        match cited.as_slice() {
            [row]
                if row.function == Some(func.id)
                    && row.kind == ObligationKind::TranslationValidation
                    && row.status == ProofStatus::Certified => {}
            [row] => errors.push(mismatch(format!(
                "cites obligation #{} ({:?}, `{}`, scoped to {:?}), which is not a Certified \
                 TranslationValidation row scoped to this function",
                evidence.obligation.index(),
                row.kind,
                row.status,
                row.function.map(FuncId::index)
            ))),
            [] => errors.push(mismatch(format!(
                "cites obligation #{}, which this module does not declare",
                evidence.obligation.index()
            ))),
            _ => errors.push(mismatch(format!(
                "cites obligation #{}, which this module declares more than once",
                evidence.obligation.index()
            ))),
        }
        // A body with no identity (a `Ty::Error` the binary writer would
        // panic on, an instruction ahead of its wire tag, an inlined scope
        // chain) is refused by `function_body_digest` itself, never a panic:
        // the evidence is reported as undigestable beside the construct's own
        // refusal in this same pass.
        match module.function_body_digest(func.id) {
            Ok(digest) if digest == evidence.body_digest => {}
            Ok(digest) => errors.push(mismatch(format!(
                "records body digest {}, the body as it stands digests to {digest} — the \
                 license was granted to another body",
                evidence.body_digest
            ))),
            Err(reason) => errors.push(mismatch(format!(
                "the body has no digest to compare ({reason})"
            ))),
        }
    }
    errors
}

/// The `Certified` obligations whose `CleanCic` certificate is UNBOUND — no
/// directive, or a directive with `binding: None`. Rows with no lineage-bound
/// certificate at all are not reported here: `validate_certified_evidence`
/// already names them (`CertifiedWithoutCleanCic` /
/// `CertifiedCleanCicLineageMismatch`), and two names for one defect would
/// double-count.
fn unbound_certificate_errors(module: &Module) -> Vec<ValidationError> {
    use trust_ir::proof::{ProofEvidence, clean_cic_lineage_binds};
    let function_catalog = ModuleFunctionCatalog::new(module);
    let resolve = |id: FuncId| function_catalog.unique(id).map(|f| f.name.clone());
    module
        .proof_obligations
        .iter()
        .filter(|obligation| obligation.status.is_kernel_tier())
        .filter(|obligation| {
            module.proof_certificates.iter().any(|certificate| {
                certificate.obligation == obligation.id
                    && matches!(
                        &certificate.evidence,
                        ProofEvidence::CleanCic { term, kernel_recheck, .. }
                            if !term.is_empty()
                                && kernel_recheck
                                    .as_ref()
                                    .is_none_or(|recheck| recheck.binding.is_none())
                    )
                    && clean_cic_lineage_binds(obligation, &certificate.evidence, &resolve)
            })
        })
        .map(|obligation| ValidationError::UnboundCertificate {
            obligation: obligation.id.index(),
        })
        .collect()
}

/// Validate `module` under `config`: the one composed lane every other
/// single-module entry point wraps. See [`ValidationConfig`] for each knob;
/// codegen errors (when requested) follow the structural ones.
pub fn validate_module_with_config<'a>(
    module: &'a Module,
    config: &ValidationConfig<'_>,
) -> ModuleValidationReport<'a> {
    validate_module_with_config_filtered(module, None, config)
}

fn validate_module_with_config_filtered<'a>(
    module: &'a Module,
    deep_filter: Option<&BTreeSet<u32>>,
    config: &ValidationConfig<'_>,
) -> ModuleValidationReport<'a> {
    let catalog = ModuleFunctionCatalog::new(module);
    validate_module_with_config_filtered_catalog(deep_filter, config, catalog)
}

fn validate_module_with_config_filtered_catalog<'a>(
    deep_filter: Option<&BTreeSet<u32>>,
    config: &ValidationConfig<'_>,
    catalog: ModuleFunctionCatalog<'a>,
) -> ModuleValidationReport<'a> {
    let module = catalog.source_module();
    let (mut errors, replayed_certificates) = validate_module_filtered_with_catalog(
        deep_filter,
        config.authority,
        config.dialect_schemas,
        config.module_import_policy(),
        config.handle_registry,
        catalog,
    );
    extend_with_config_codegen_errors(&mut errors, module, &replayed_certificates, config);
    extend_with_config_binding_errors(&mut errors, module, config);
    ModuleValidationReport {
        module,
        errors,
        replayed_certificates,
        handle_registry_is_pinned: config.handle_registry_is_pinned(),
    }
}

/// Result of validating one exact module, including the certificate authority
/// replayed during that same pass. Keeping the module borrowed prevents a
/// caller from applying authority established for one module to another.
pub struct ModuleValidationReport<'a> {
    module: &'a Module,
    errors: Vec<ValidationError>,
    replayed_certificates: BTreeSet<trust_ir::proof::ProofCertificateRef>,
    handle_registry_is_pinned: bool,
}

impl<'a> ModuleValidationReport<'a> {
    /// Whether this report was produced under the PINNED handle-runtime
    /// registry ([`ValidationConfig::handle_registry_is_pinned`]). Reported
    /// regardless of the verdict.
    ///
    /// `false` means a caller-supplied registry decided which handle entry
    /// points are trusted — a caller-owned TCB extension. A consumer that
    /// compiles what this report admits MUST check this bit (or re-read the
    /// pinned table itself) before trusting a handle-bearing module.
    #[must_use]
    pub fn handle_registry_is_pinned(&self) -> bool {
        self.handle_registry_is_pinned
    }

    pub fn errors(&self) -> &[ValidationError] {
        &self.errors
    }

    pub fn is_ok(&self) -> bool {
        self.errors.is_empty()
    }

    /// Return the exact module borrowed by this report, but only when the
    /// complete validation pass succeeded.
    ///
    /// The returned reference has the report's original module lifetime and
    /// points to the same module instance that was validated; this method does
    /// not clone, substitute, or revalidate it. `None` means at least one
    /// validation error was found, so no module is exposed as validated.
    pub fn validated_module(&self) -> Option<&'a Module> {
        self.errors.is_empty().then_some(self.module)
    }

    /// Return the exact kernel-tier certificate references replayed while
    /// validating this module, but only when the complete validation report is
    /// successful.
    ///
    /// `None` means the module has at least one validation error; replayed
    /// evidence from an otherwise-invalid module is deliberately not exposed
    /// as authority. `Some(empty)` distinguishes a valid module that carries no
    /// replayed certificates.
    ///
    /// A [`trust_ir::proof::ModuleProofAuthority`] supplied to
    /// [`validate_module_report_with_authority`] may admit a `Discharged` row,
    /// but that row is not kernel-tier authority and therefore is not included
    /// in this set.
    pub fn replayed_certificate_refs(
        &self,
    ) -> Option<&BTreeSet<trust_ir::proof::ProofCertificateRef>> {
        self.errors
            .is_empty()
            .then_some(&self.replayed_certificates)
    }

    pub fn into_errors(self) -> Vec<ValidationError> {
        self.errors
    }

    /// The imports this module's PROOF-BEARING rows cite: every `backed_by`
    /// naming an obligation on a `proved` summary, and every `external: Some`
    /// inheritance certificate. Reported regardless of the verdict, so a
    /// consumer holding only the structural report can see which dependency
    /// modules it must supply to `validate_linked_module` before acting on
    /// any of those rows. Empty means the module makes no cross-crate proof
    /// claim — not that its imports were authenticated.
    pub fn proof_bearing_imports(&self) -> BTreeSet<trust_ir::value::ImportId> {
        crate::linked::proof_bearing_imports(self.module)
    }

    /// The functions that carry an UNWIND SURFACE — at least one `Invoke`,
    /// `AssertInvoke` (amendment P), `DropInvoke` (amendment D),
    /// `InvokeIndirect` (amendment D, Part 2), `LandingPad`, `Resume`, or a
    /// typed non-propagating call boundary — in
    /// module storage order, each id once.
    ///
    /// A verdict computed under `PanicStrategy::Abort` (the default of both
    /// executable engines: the panic=abort projection, whose unwind edges are
    /// never taken) covers panic=abort only, so a consumer compiling the
    /// module with panic=unwind MUST NOT rely on such a verdict about one of
    /// these functions (`docs/ub-numerics-policy.md` §4, "Unwinding";
    /// `docs/SPEC_RATIFICATIONS.md` §21 rule 7). A verdict computed under
    /// `PanicStrategy::Unwind` covers both builds: up to its first raise the
    /// Abort run IS the Unwind run. This list is what a consumer applies that
    /// rule to; it needs no inference of its own.
    /// Reported regardless of the verdict, like
    /// [`Self::proof_bearing_imports`]. Empty means no function of the module
    /// carries a handler or explicit non-propagating boundary. The new call
    /// boundaries are refused by both executable engines, NOT evaluated under
    /// the ordinary-call projection and NOT evidence of panic freedom.
    pub fn unwind_surface(&self) -> Vec<FuncId> {
        let mut seen = BTreeSet::new();
        self.module
            .functions
            .iter()
            .filter(|function| {
                function
                    .blocks
                    .iter()
                    .flat_map(|block| &block.body)
                    .any(|node| {
                        matches!(
                            node.inst,
                            Inst::Invoke { .. }
                                | Inst::AssertInvoke { .. }
                                | Inst::DropInvoke { .. }
                                | Inst::InvokeIndirect { .. }
                                | Inst::LandingPad { .. }
                                | Inst::Resume { .. }
                                | Inst::CallCannotUnwind { .. }
                                | Inst::CallIndirectCannotUnwind { .. }
                        )
                    })
            })
            .map(|function| function.id)
            .filter(|id| seen.insert(*id))
            .collect()
    }

    /// Every UNRESOLVED drop of the module (amendment D, §20 rule 4): each
    /// `Drop` / `DropInvoke` whose type has no drop-glue row, as (function,
    /// block, dropped type), in storage order. Reported regardless of the
    /// verdict. Both engines refuse such a drop and the codegen gate refuses
    /// it by default (`refuse/drop_unresolved`); a consumer that verifies or
    /// lowers the module MUST refuse it, and this list is what it applies
    /// that rule to. Empty means every drop resolves (or there is none).
    pub fn unresolved_drops(&self) -> Vec<(FuncId, BlockId, Ty)> {
        let index = self.module.drop_glue_index();
        let mut out = Vec::new();
        for function in &self.module.functions {
            for block in &function.blocks {
                for node in &block.body {
                    if let Inst::Drop { ty, .. } | Inst::DropInvoke { ty, .. } = &node.inst
                        && !matches!(index.resolve(ty), trust_ir::DropResolution::Resolved(_))
                    {
                        out.push((function.id, block.id, ty.clone()));
                    }
                }
            }
        }
        out
    }

    /// Check lineage closure with only the exact certificate identities that
    /// this module-validation pass replayed, then independently rederive the
    /// source and target semantic endpoints carried by every lineage rung.
    /// An otherwise-invalid module gets no authority, even if one certificate
    /// happened to replay in isolation.
    pub fn lineage_is_closed(
        &self,
        manifest: &trust_ir::proof::ProofLineageManifest,
    ) -> Result<(), trust_ir::proof::LineageGap> {
        let empty = BTreeSet::new();
        let refs = if self.errors.is_empty() {
            &self.replayed_certificates
        } else {
            &empty
        };
        let authority = ReplayedCertificateRefs { refs };
        trust_ir::lineage_closed_with_authority(self.module, manifest, &authority)?;
        let function_catalog = ModuleFunctionCatalog::new(self.module);
        validate_lineage_semantic_bindings_with_catalog(
            self.module,
            &function_catalog,
            manifest,
            refs,
        )
    }
}

pub fn validate_module_report(module: &Module) -> ModuleValidationReport<'_> {
    validate_module_with_config(module, &ValidationConfig::pinned())
}

pub fn validate_module(module: &Module) -> Vec<ValidationError> {
    validate_module_report(module).into_errors()
}

/// The ONE sanctioned minter of a [`trust_ir::KernelCertifiedTheorems`]
/// witness (v46, roadmap WS4.14): the theorem names a
/// [`ProofKind::CleanTheorem`](trust_ir::ProofKind::CleanTheorem) spec
/// binding may resolve against.
///
/// Runs the full module validator and, ONLY when it passes, collects the
/// `kernel_recheck.theorems` of exactly the kernel-tier certificates the
/// validator REPLAYED ([`ModuleValidationReport::replayed_certificate_refs`]).
/// Those are the `Certified` rows whose CleanCic re-check actually ran in the
/// in-process kernel, so the witness carries no theorem the kernel did not
/// establish, and an invalid module yields no witness at all — `Certified` is
/// earned by the Clean kernel re-check alone, and this only projects it.
///
/// Returns the validation errors on refusal; `Ok(empty)` is a valid module
/// that established no theorem.
pub fn kernel_certified_theorems(
    module: &Module,
) -> Result<trust_ir::KernelCertifiedTheorems, Vec<ValidationError>> {
    let report = validate_module_report(module);
    let Some(replayed) = report.replayed_certificate_refs() else {
        return Err(report.into_errors());
    };
    let names = module
        .proof_certificates
        .iter()
        .filter(|certificate| replayed.contains(&certificate.lineage_ref()))
        .filter_map(|certificate| certificate.evidence.clean_cic_kernel_recheck())
        .flat_map(|recheck| recheck.theorems.iter().cloned());
    Ok(trust_ir::KernelCertifiedTheorems::from_rechecked(names))
}

/// Validate `module` **with codegen intent**: everything [`validate_module`]
/// checks, plus the v41 codegen-license (`Function::body_gate`) check that
/// turns the license from decoration into a refusal hook.
///
/// # Composition, not duplication
///
/// This runs [`validate_module`] verbatim and appends the license errors. It
/// re-implements none of the structural, type, proof, or ABI checks, so a
/// change to those is inherited here for free. Structural errors come first in
/// the returned vector, license errors last.
///
/// # The license rule, per function WITH A BODY
///
/// * `Some(BodyGate::Gated { authority })` — may proceed, subject to the
///   evidence and revocation rules of [`codegen_license_errors`]: an authority
///   in [`EVIDENCE_BOUND_GATE_AUTHORITIES`] must be backed by the evidence its
///   row names ([`ValidationError::GatedWithoutEvidence`]), and any `Gated`
///   body refuted in-module ([`ValidationError::GatedFunctionRefuted`]) or
///   carrying two `TranslationValidation` rows is refused. Whether `authority`
///   is one this consumer RECOGNIZES is deliberately not decided here: the
///   format has no recognition registry and must not pretend to. A consumer
///   names its recognized set through [`validate_module_for_codegen_with`]
///   ([`CodegenAdmission::with_recognized`]), and [`trust_ir::BodyGate`]'s doc
///   states that an unrecognized authority is a refusal, never a pass.
/// * `Some(BodyGate::Ungated)` — refused, as
///   [`ValidationError::UngatedBodyForCodegen`]. This is an affirmative "no
///   gate was applied".
/// * `None` — refused, as [`ValidationError::UnlicensedBodyForCodegen`], a
///   SEPARATE and separately-matchable variant. See below.
///
/// A body-LESS function ([`trust_ir::Function::is_declaration`]) is never a
/// codegen subject — an import or a contract-only declaration produces no
/// machine code — so it is not refused for lacking a license, whatever its
/// linkage. Only the definition site can license a body, and by construction
/// that site is in some other module.
///
/// # Why `None` is refused HERE, and why it is nonetheless a distinct error
///
/// The argument for permitting `None` is real: it is the pre-v41 grandfather
/// state, every v38-and-older blob decodes to it, and a validator that refuses
/// it refuses every module written before the license existed.
///
/// The argument against is decisive for a function whose name ends in
/// `_for_codegen`. The license is a SAFETY interlock, and the pre-v41 world is
/// exactly the world in which no gate ran — "we did not record whether the
/// body was gated" is not evidence that it was. Defaulting an absent interlock
/// to *permit* is how an interlock stops being one: a producer that simply
/// never sets the field would silently obtain the permission that
/// `BodyGate::Ungated` is refused, and the cheapest way to launder an ungated
/// body would be to drop the field (which is precisely what
/// `Function::body_gate`'s doc forbids transforms from doing). A refusal beats
/// a guess.
///
/// Both arguments are honored by making the two refusals DIFFERENT VALUES
/// rather than one. This function states the fail-closed default; the caller
/// owns the policy. A consumer that has decided to grandfather legacy input
/// filters out `UnlicensedBodyForCodegen` and keeps `UngatedBodyForCodegen`:
///
/// ```
/// # use trust_ir::inst::Inst;
/// # use trust_ir::node::InstrNode;
/// # use trust_ir::ty::FuncTy;
/// # use trust_ir::value::{BlockId, FuncId};
/// # use trust_ir::{Block, Function, Module};
/// // Re-exported at the crate root beside `validate_module`: the stricter
/// // gate must never be harder to reach than the check it supersedes.
/// use trust_ir_build::{ValidationError, validate_module_for_codegen};
///
/// # let mut module = Module::new("legacy");
/// # let ft = module.add_func_type(FuncTy {
/// #     params: vec![],
/// #     returns: vec![],
/// #     abi: None,
/// #     is_vararg: false,
/// # }).unwrap();
/// # let mut block = Block::new(BlockId::new(0));
/// # block.body.push(InstrNode::new(Inst::Return { values: vec![] }));
/// # let mut func = Function::new(FuncId::new(0), "f", ft, BlockId::new(0));
/// # func.blocks.push(block);
/// # module.try_add_function(func).unwrap();
/// // `module` holds one pre-v41 body: well-formed, but making no licensing claim.
/// let errors = validate_module_for_codegen(&module);
/// assert!(matches!(
///     errors.as_slice(),
///     [ValidationError::UnlicensedBodyForCodegen { .. }]
/// ));
///
/// // A consumer that has decided to grandfather legacy artifacts drops exactly
/// // that variant — and still refuses every affirmatively-`ungated` body.
/// let refusals: Vec<_> = errors
///     .into_iter()
///     .filter(|e| !matches!(e, ValidationError::UnlicensedBodyForCodegen { .. }))
///     .collect();
/// assert!(refusals.is_empty());
/// ```
///
/// That filter is only expressible because the two never share a variant — which
/// is the same reason [`trust_ir::BodyGate`]'s wire tag is three-valued instead
/// of a presence byte over two states.
///
/// This is [`validate_module_with_config`] under
/// `ValidationConfig::pinned().with_codegen(true)` — and, identically,
/// [`validate_module_for_codegen_with`] under [`CodegenAdmission::pinned`]. A
/// consumer that also holds a replay capability or an extended handle registry
/// uses the config lane; one that also names a recognized-authority set or a
/// grandfathering policy uses the admission lane.
#[must_use]
pub fn validate_module_for_codegen(module: &Module) -> Vec<ValidationError> {
    validate_module_with_config(module, &ValidationConfig::pinned().with_codegen(true))
        .into_errors()
}

/// Validate `module` AS DECODED from a binary blob whose header declared
/// `wire_version`: everything [`validate_module`] checks, plus the v41
/// producer conformance rule of [`trust_ir::BodyGate`] —
/// [`decoded_provenance_errors`] — which only a decoded module can be held to.
///
/// The rule: at v41 or later (`wire_version.claims_contract_surface()`) a
/// function WITH A BODY whose `body_gate` is `None` is
/// [`ValidationError::ProducerOmittedBodyGate`]; below v41 the same `None` is
/// the grandfather state every pre-v41 function decodes to and is accepted;
/// a bodyless declaration is accepted at any version. Nothing else changes:
/// this is `validate_module`'s verdict with one refusal appended, so a
/// module this accepts is one `validate_module` accepts.
///
/// # Why a separate entry point, and why the argument is a `WireVersion`
///
/// The rule is phrased over the PRODUCING version, and a [`Module`] does not
/// carry one — deliberately, since decode provenance is not content identity.
/// So the version arrives beside the module, from
/// [`trust_ir::binary::deserialize_module_with_wire_version`], as a
/// [`trust_ir::binary::WireVersion`] the decoder alone can mint: a caller
/// cannot claim a provenance it does not have. Plain [`validate_module`]
/// keeps accepting a hand-built module, a text / JSON / MessagePack parse, or
/// a plain `deserialize_module` result with a bodied `None`, because none of
/// those has a wire version to read, and refusing them would refuse every
/// module that never went through the binary codec. That residual is the
/// whole distance between this function and the rule being format-enforced
/// everywhere; it is stated on the types, not assumed away.
///
/// Available with the `binary` feature only: without the codec nothing can
/// mint a `WireVersion`, so there would be nothing to call this with.
#[cfg(feature = "binary")]
#[must_use]
pub fn validate_module_as_decoded(
    module: &Module,
    wire_version: trust_ir::binary::WireVersion,
) -> Vec<ValidationError> {
    let mut errors = validate_module(module);
    errors.extend(decoded_provenance_errors(module, wire_version));
    errors
}

/// The v41 producer-conformance layer ALONE, read against the header version
/// a binary blob DECLARED: one [`ValidationError::ProducerOmittedBodyGate`]
/// per function WITH A BODY whose `body_gate` is `None`, iff
/// `wire_version.claims_contract_surface()` (v41 or later). Below v41 it
/// reports nothing, and a bodyless declaration reports nothing at any version
/// — the same `is_declaration()` cut [`codegen_license_errors`] makes, for
/// the same reason: a declaration produces no code and needs no license.
///
/// No structural validation here; [`validate_module_as_decoded`] is
/// [`validate_module`] + this. It is public separately for a caller that
/// already holds a [`ModuleValidationReport`] and wants the one extra refusal
/// without a second structural pass (the `trust-ir validate` CLI).
#[cfg(feature = "binary")]
#[must_use]
pub fn decoded_provenance_errors(
    module: &Module,
    wire_version: trust_ir::binary::WireVersion,
) -> Vec<ValidationError> {
    if !wire_version.claims_contract_surface() {
        return Vec::new();
    }
    module
        .functions
        .iter()
        .filter(|func| !func.is_declaration() && func.body_gate.is_none())
        .map(|func| ValidationError::ProducerOmittedBodyGate {
            function: func.id.index(),
            name: func.name.clone(),
            wire_version: wire_version.get(),
        })
        .collect()
}

/// What a body claiming a gate authority must carry in-module
/// ([`EVIDENCE_BOUND_GATE_AUTHORITIES`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum GateEvidenceRule {
    /// Exactly one `TranslationValidation` obligation scoped to the function
    /// (`function == Some(F)`), at `Certified`, whose `CleanCic` certificate
    /// cites [`trust_ir::proof::KERNEL_ANCHOR_CLEAN_BACKEND_TV`] and is in the
    /// kernel-tier set this validation pass REPLAYED. The `clean_backend_tv`
    /// recheck re-derives the emitted side from the CURRENT body (and, since
    /// WS1.4, binds every call edge to the callee called), so a body rewritten
    /// after minting keeps its `body_gate` but loses its license.
    ///
    /// What it does not establish: the certificate proves the emitted body
    /// equal to the RECORDED comparand, not to the Clean source (F-008). The
    /// license is therefore bound to a TV certificate, not yet to the source.
    KernelTranslationValidation,
}

/// The gate authorities whose license is BOUND TO EVIDENCE (roadmap WS1.5,
/// finding F-006).
///
/// This is not a recognition registry — the format still has none, and an
/// authority missing from this table keeps its pre-WS1.5 behavior on the
/// policy-free entry points (a `Gated` body may proceed; recognizing it is the
/// consumer's decision, [`CodegenAdmission::with_recognized`]). The table says
/// only that a body CLAIMING one of these authorities must carry the evidence
/// its [`GateEvidenceRule`] names, so the authority string can no longer be
/// worn without the certificate it stands for. Membership is byte-exact, on
/// the [`ADMITTED_OBLIGATION_NAMESPACES`] pattern: a case or padding variant
/// of `clean-kernel-tv` is simply a different, unbound authority, which no
/// consumer recognizing the exact string admits.
pub const EVIDENCE_BOUND_GATE_AUTHORITIES: &[(&str, GateEvidenceRule)] = &[(
    "clean-kernel-tv",
    GateEvidenceRule::KernelTranslationValidation,
)];

/// The [`GateEvidenceRule`] `authority` is bound to, if any (byte-exact).
#[must_use]
pub fn gate_evidence_rule(authority: &str) -> Option<GateEvidenceRule> {
    EVIDENCE_BOUND_GATE_AUTHORITIES
        .iter()
        .find(|(name, _)| *name == authority)
        .map(|(_, rule)| *rule)
}

/// What codegen admission does with a body that makes NO licensing claim
/// (`body_gate: None`, the pre-v41 grandfather state).
///
/// Defined in `trust-ir-laws` beside the admission table it parameterizes
/// ([`license_admits_body`]), whose laws are PROVED Trust contracts; re-exported
/// here at its historical path. Note it carries no `Debug` (render it with
/// `name()`): see the definition for why.
pub use trust_ir_laws::UnlicensedBodyPolicy;

/// The codegen-admission POLICY on top of a [`ValidationConfig`] (roadmap
/// WS1.5; F-009, F-017): the config's proof authority, handle-runtime
/// registry and dialect schemas, plus the consumer's recognized gate
/// authorities and its policy for unlicensed bodies.
/// [`validate_module_for_codegen_with`] is the composed lane, and
/// [`validate_module_for_codegen`] is it under [`Self::pinned`].
///
/// The structural knobs live in [`ValidationConfig`] alone (one options
/// struct, so the lanes cannot drift); this type adds only the two license
/// knobs a config does not carry. The codegen layers always run under an
/// admission — the config's own `codegen` flag is ignored.
///
/// # Defaults, and what they refuse
///
/// [`Self::pinned`] is exactly [`validate_module_for_codegen`]:
/// [`ValidationConfig::pinned`], no recognized-authority set (every `Gated`
/// authority is left to the consumer, subject to the evidence table), and
/// [`UnlicensedBodyPolicy::Refuse`].
///
/// * [`Self::with_authority`] / [`Self::with_handle_registry`] are the
///   [`ValidationConfig`] builders of the same name (the first also REFUSES
///   every proof-bearing cross-crate row; a registry other than the pinned
///   one is a caller-owned TCB extension). [`Self::from_config`] takes a
///   whole config, dialect schemas included.
/// * [`Self::with_recognized`] names the consumer's recognized authorities:
///   any other `Gated` authority is [`ValidationError::UnrecognizedGateAuthority`].
///   `trust-direct-lane-structural` is an explicit, disclosed intermediate
///   policy (roadmap WS1.5 DECIDE 1): a consumer admits it only by naming it
///   here, and it is never in a default set.
/// * [`Self::with_unlicensed`] selects the [`UnlicensedBodyPolicy`].
///
/// None of these knobs relaxes the evidence table or the revocation rules of
/// [`codegen_license_errors`]: they apply under every admission.
#[derive(Clone, Copy)]
pub struct CodegenAdmission<'a> {
    config: ValidationConfig<'a>,
    recognized: Option<&'a BTreeSet<String>>,
    unlicensed: UnlicensedBodyPolicy,
    refuse_unbacked_claims_on_checks: bool,
    require_assert_panic_kinds: bool,
    require_assert_panic_sites: bool,
}

impl std::fmt::Debug for CodegenAdmission<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CodegenAdmission")
            .field("config", &self.config)
            .field("recognized", &self.recognized)
            .field("unlicensed", &format_args!("{}", self.unlicensed.name()))
            .field(
                "refuse_unbacked_claims_on_checks",
                &self.refuse_unbacked_claims_on_checks,
            )
            .field(
                "require_assert_panic_kinds",
                &self.require_assert_panic_kinds,
            )
            .field(
                "require_assert_panic_sites",
                &self.require_assert_panic_sites,
            )
            .finish()
    }
}

impl Default for CodegenAdmission<'_> {
    fn default() -> Self {
        Self::pinned()
    }
}

impl<'a> CodegenAdmission<'a> {
    /// The admission of [`validate_module_for_codegen`] (see the type docs).
    #[must_use]
    pub fn pinned() -> Self {
        Self::from_config(ValidationConfig::pinned())
    }

    /// An admission over `config` (its authority, registry, dialect schemas
    /// and import policy), with no recognized set and unlicensed bodies
    /// refused.
    #[must_use]
    pub fn from_config(config: ValidationConfig<'a>) -> Self {
        Self {
            config,
            recognized: None,
            unlicensed: UnlicensedBodyPolicy::Refuse,
            refuse_unbacked_claims_on_checks: false,
            require_assert_panic_kinds: false,
            require_assert_panic_sites: false,
        }
    }

    /// [`ValidationConfig::with_authority`]: supply a proof-replay capability;
    /// this also REFUSES every proof-bearing cross-crate row.
    #[must_use]
    pub fn with_authority(
        mut self,
        authority: &'a dyn trust_ir::proof::ModuleProofAuthority,
    ) -> Self {
        self.config = self.config.with_authority(authority);
        self
    }

    /// [`ValidationConfig::with_handle_registry`]: substitute the
    /// handle-runtime registry (a caller-owned TCB extension unless it is
    /// [`HandleRegistry::pinned`]).
    #[must_use]
    pub fn with_handle_registry(mut self, registry: &'a HandleRegistry) -> Self {
        self.config = self.config.with_handle_registry(registry);
        self
    }

    /// Recognize exactly `recognized`: every other `Gated` authority is
    /// [`ValidationError::UnrecognizedGateAuthority`]. Membership is
    /// byte-exact.
    #[must_use]
    pub fn with_recognized(mut self, recognized: &'a BTreeSet<String>) -> Self {
        self.recognized = Some(recognized);
        self
    }

    /// Select the policy for bodies that make no licensing claim.
    #[must_use]
    pub fn with_unlicensed(mut self, unlicensed: UnlicensedBodyPolicy) -> Self {
        self.unlicensed = unlicensed;
        self
    }

    /// WS1.8 rule (f), finding F-022: refuse a `NoOverflow` / `NoWrap` /
    /// `DivNonZero` / `ShiftInRange` / `InBounds` claim on an `Assert` or
    /// `CondBr` node that carries no `ProofRef` naming a kind-matched row
    /// sited on that node ([`ValidationError::UnbackedClaimOnCheck`]).
    ///
    /// The node that IS the runtime check is exactly where a bare claim is
    /// most dangerous: measured on both producers (A.uf12), every `Assert`
    /// backing a `Pending` "RECORDED, NOT PROVED" arithmetic obligation wears
    /// `NoOverflow`, so a consumer that elided claim-annotated checks would
    /// elide every unproved one. A claim on the check never licenses eliding
    /// the check; only a resolving `ProofRef` does. OFF by default (the
    /// structural tier and [`validate_module_for_codegen`] keep accepting the
    /// shape while the producer fix, WS5, lands); a consumer that elides
    /// checks on claims turns it on. Must-refuse corpus row
    /// `refuse/unbacked_claim_on_check`: accepted by the default gate, refused
    /// under this knob, both pinned.
    #[must_use]
    pub fn with_refuse_unbacked_claims_on_checks(mut self, refuse: bool) -> Self {
        self.refuse_unbacked_claims_on_checks = refuse;
        self
    }

    /// Plan item P (wire v52): refuse every `Inst::Assert` whose kind is
    /// `AssertKind::Unspecified` ([`ValidationError::AssertPanicKindUnspecified`]).
    ///
    /// A consumer that lowers a failed check to Rust's panic entry point
    /// (`AssertKind::rust_panic_lang_item`) must know WHICH panic it is; an
    /// `Unspecified` assert — every assert decoded from a pre-v52 blob, and
    /// any producer that does not record the kind — has none, and lowering it
    /// as a bare trap is exactly the unfaithful panic item P removes. OFF by
    /// default (the structural tier and [`validate_module_for_codegen`] keep
    /// accepting older blobs); a faithful-panic consumer turns it on.
    /// Must-refuse corpus row `refuse/assert_panic_kind_unspecified`:
    /// accepted by the default gate, refused under this knob, both pinned.
    #[must_use]
    pub fn with_require_assert_panic_kinds(mut self, require: bool) -> Self {
        self.require_assert_panic_kinds = require;
        self
    }

    /// Amendment P (wire v54, `docs/SPEC_RATIFICATIONS.md` §19.1 rule 7):
    /// refuse every `Inst::Assert` without a panic site, whatever its kind
    /// ([`ValidationError::AssertPanicSiteMissing`]).
    ///
    /// A FAITHFUL consumer turns this on: it MUST lower a sited check as
    /// `brif cond, cont, fail; fail: call entry(operands.., location); trap`
    /// with the entry's calling convention and no other effect on the
    /// failing path, and refuse a function whose check it cannot lower so —
    /// never trap in place of the call. A siteless assert names no entry and
    /// no location, so such a consumer refuses it rather than inventing a
    /// symbol or trapping (must-refuse corpus row
    /// `refuse/assert_panic_site_missing`: accepted by the default gate,
    /// refused under this knob, both pinned). This is the FAITHFULNESS knob;
    /// [`Self::with_require_assert_panic_kinds`] stays the IDENTITY knob (it
    /// refuses every `Unspecified` assert, sited or not), which a consumer
    /// that elides checks also turns on. OFF by default.
    #[must_use]
    pub fn with_require_assert_panic_sites(mut self, require: bool) -> Self {
        self.require_assert_panic_sites = require;
        self
    }

    /// The structural configuration this admission validates under.
    #[must_use]
    pub fn config(&self) -> &ValidationConfig<'a> {
        &self.config
    }

    /// The proof authority this admission validates under.
    #[must_use]
    pub fn authority(&self) -> &'a dyn trust_ir::proof::ModuleProofAuthority {
        self.config.authority()
    }

    /// The handle-runtime registry this admission validates under.
    #[must_use]
    pub fn handle_registry(&self) -> &'a HandleRegistry {
        self.config.handle_registry()
    }

    /// The consumer's recognized gate authorities, if it named any.
    #[must_use]
    pub fn recognized(&self) -> Option<&'a BTreeSet<String>> {
        self.recognized
    }

    /// The policy for bodies that make no licensing claim.
    #[must_use]
    pub fn unlicensed(&self) -> UnlicensedBodyPolicy {
        self.unlicensed
    }

    /// Whether [`Self::with_refuse_unbacked_claims_on_checks`] is on.
    #[must_use]
    pub fn refuse_unbacked_claims_on_checks(&self) -> bool {
        self.refuse_unbacked_claims_on_checks
    }

    /// Whether [`Self::with_require_assert_panic_kinds`] is on.
    #[must_use]
    pub fn require_assert_panic_kinds(&self) -> bool {
        self.require_assert_panic_kinds
    }

    /// Whether [`Self::with_require_assert_panic_sites`] is on.
    #[must_use]
    pub fn require_assert_panic_sites(&self) -> bool {
        self.require_assert_panic_sites
    }
}

/// Validate `module` with codegen intent under `admission`: the structural
/// pass under the admission's [`ValidationConfig`], then the license layer
/// (evidence table, revocation, recognized set, unlicensed policy) against
/// the kernel tier THAT pass replayed — no module is kernel-rechecked twice —
/// then the lowerability and `global_asm` layers. Structural errors first,
/// license errors after, exactly as [`validate_module_for_codegen`].
#[must_use]
pub fn validate_module_for_codegen_with(
    module: &Module,
    admission: &CodegenAdmission<'_>,
) -> Vec<ValidationError> {
    let report = validate_module_with_config(module, &admission.config.with_codegen(false));
    let mut errors = license_errors_against(
        module,
        &report.replayed_certificates,
        admission.recognized,
        admission.unlicensed,
    );
    errors.extend(codegen_lowerability_errors(module));
    errors.extend(codegen_global_asm_errors(module));
    if admission.refuse_unbacked_claims_on_checks {
        errors.extend(unbacked_claim_on_check_errors(module));
    }
    if admission.require_assert_panic_kinds {
        errors.extend(unspecified_assert_kind_errors(module));
    }
    if admission.require_assert_panic_sites {
        errors.extend(missing_panic_site_errors(module));
    }
    let mut all = report.into_errors();
    all.extend(errors);
    all
}

/// The plan-item-P layer ALONE (wire v52): one
/// [`ValidationError::AssertPanicKindUnspecified`] per `Inst::Assert` whose
/// kind is `AssertKind::Unspecified`, in function / block / instruction
/// order. Run by [`validate_module_for_codegen_with`] under
/// [`CodegenAdmission::with_require_assert_panic_kinds`].
#[must_use]
pub fn unspecified_assert_kind_errors(module: &Module) -> Vec<ValidationError> {
    let mut errors = Vec::new();
    for func in &module.functions {
        for block in &func.blocks {
            for (inst_index, node) in block.body.iter().enumerate() {
                if let Inst::Assert { kind, .. } = &node.inst
                    && kind.is_unspecified()
                {
                    errors.push(ValidationError::AssertPanicKindUnspecified {
                        function: func.name.clone(),
                        block: block.id.index(),
                        inst_index: inst_index as u32,
                    });
                }
            }
        }
    }
    errors
}

/// The amendment-P layer ALONE (wire v54): one
/// [`ValidationError::AssertPanicSiteMissing`] per `Inst::Assert` with no
/// panic site, in function / block / instruction order. `AssertInvoke`
/// always carries one. Run by [`validate_module_for_codegen_with`] under
/// [`CodegenAdmission::with_require_assert_panic_sites`].
#[must_use]
pub fn missing_panic_site_errors(module: &Module) -> Vec<ValidationError> {
    let mut errors = Vec::new();
    for func in &module.functions {
        for block in &func.blocks {
            for (inst_index, node) in block.body.iter().enumerate() {
                if let Inst::Assert { site: None, .. } = &node.inst {
                    errors.push(ValidationError::AssertPanicSiteMissing {
                        function: func.name.clone(),
                        block: block.id.index(),
                        inst_index: inst_index as u32,
                    });
                }
            }
        }
    }
    errors
}

/// The WS1.8 rule (f) layer ALONE (F-022): every `Assert` / `CondBr` node
/// carrying a safety-class claim (`NoOverflow`, `NoWrap`, `DivNonZero`,
/// `ShiftInRange`, `InBounds`) must also carry a `ProofRef` that names a row
/// of an admissible kind (`ArithmeticSafety`, `BoundsCheck`, `PanicFreedom`,
/// or `MemorySafety` for `InBounds`) sited on that very node. Whether that
/// `ProofRef` RESOLVES (kernel tier) is the structural pass's
/// `validate_proof_refs_with_authority`, which the composed lane runs first;
/// this layer checks only that the claim is BOUND to a row about this check,
/// so an unbound claim is refused by name rather than silently permitted as
/// an elision license. Run by [`validate_module_for_codegen_with`] under
/// [`CodegenAdmission::with_refuse_unbacked_claims_on_checks`].
#[must_use]
pub fn unbacked_claim_on_check_errors(module: &Module) -> Vec<ValidationError> {
    use trust_ir::proof::{ObligationKind, ProofAnnotation};
    let rows = ObligationRows::new(module);
    let mut errors = Vec::new();
    for func in &module.functions {
        for block in &func.blocks {
            for (inst_index, node) in block.body.iter().enumerate() {
                // Amendment P: an `AssertInvoke` IS a runtime check too.
                if !matches!(
                    node.inst,
                    Inst::Assert { .. } | Inst::AssertInvoke { .. } | Inst::CondBr { .. }
                ) {
                    continue;
                }
                let claims: Vec<&ProofAnnotation> = node
                    .proofs
                    .iter()
                    .filter(|a| a.is_arithmetic_safety() || matches!(a, ProofAnnotation::InBounds))
                    .collect();
                if claims.is_empty() {
                    continue;
                }
                let inst_index = inst_index as u32;
                for claim in claims {
                    let backed = node.proofs.iter().any(|a| {
                        let Some(id) = a.backing_obligation() else {
                            return false;
                        };
                        let Some(row) = rows.unique(id) else {
                            return false;
                        };
                        let sited_here = row.site.is_some_and(|site| {
                            site.function == func.id
                                && site.block == block.id
                                && site.inst_index == inst_index
                        });
                        let kind_ok = match row.kind {
                            ObligationKind::ArithmeticSafety
                            | ObligationKind::BoundsCheck
                            | ObligationKind::PanicFreedom => true,
                            ObligationKind::MemorySafety => {
                                matches!(claim, ProofAnnotation::InBounds)
                            }
                            _ => false,
                        };
                        sited_here && kind_ok
                    });
                    if !backed {
                        errors.push(ValidationError::UnbackedClaimOnCheck {
                            function: func.name.clone(),
                            block: block.id.index(),
                            inst_index,
                            claim: claim.kind_name(),
                        });
                    }
                }
            }
        }
    }
    errors
}

/// The v41 [`Module::global_asm`] refusal ALONE, with no structural
/// validation, no license check and no lowerability check.
///
/// # The rule
///
/// `global_asm` carries module-level `global_asm!` blocks as OPAQUE TEXT. The
/// format records the bytes and nothing else: not the symbols a block defines,
/// not the symbols it references, not its effects, not its target
/// requirements. So a consumer cannot lower it, cannot check it, and cannot
/// prove anything about the module that contains it.
///
/// The normative consequence, stated when the field landed, is that a consumer
/// must **refuse** such a module rather than silently DROP the block. Dropping
/// is the dangerous outcome and the reason this is a refusal rather than a
/// warning: the resulting object still links and still runs, while missing a
/// definition the source demanded — a silently different program, not a failed
/// build.
///
/// # Why codegen intent only
///
/// Exactly the `body_gate` composition
/// ([`codegen_license_errors`]): a module that merely CARRIES `global_asm` is
/// WELL-FORMED, and `validate_module` accepts it — that is what an artifact
/// under inspection, a round-trip fixture, or a module being diffed looks
/// like. Only CONSUMING one for codegen is refused, and only by the
/// codegen-facing entry point. The block is identity-bearing
/// (`executable_content_digest`) and round-trips losslessly through the
/// binary, JSON and MessagePack formats. The TEXT format cannot carry it:
/// `trust_ir::format::text_losses` reports `GlobalAsm`, `canonical_checked`
/// refuses, and the `Display` dump carries a `; #lossy:` marker the parser
/// refuses — so a text round trip can no longer launder this refusal away
/// (roadmap WS4.2, finding F-065; carrying the blocks is WS4.5).
///
/// One error for the module, naming the block COUNT rather than one error per
/// block: the refusal is about the module carrying assembly at all, and a
/// consumer that must refuse gains nothing from N copies of the same verdict.
#[must_use]
pub fn codegen_global_asm_errors(module: &Module) -> Vec<ValidationError> {
    if module.global_asm.is_empty() {
        return Vec::new();
    }
    vec![ValidationError::GlobalAsmNotConsumable {
        blocks: module.global_asm.len(),
    }]
}

/// What re-deriving a module's [`trust_ir::proof::CoverageAssurance`] rows
/// against a [`trust_ir::request::NativeVerificationBundle`] found — INCLUDING
/// the case where there was no bundle to re-derive against.
///
/// The distinction is the whole point of the type. `CoverageAssurance`'s own
/// rustdoc states the contract the row was shipped to have: *"a consumer
/// holding the bundle re-derives the bound and refuses on mismatch, while a
/// consumer SEPARATED from its bundle still reads an honest 'depth-1 BMC'
/// instead of nothing at all."* A caller must be able to tell those two
/// consumers apart, because an empty error list means "the projection agrees
/// with its bundle" in the first and "nothing was checked" in the second — and
/// reading the second as the first is exactly the omission the `None`-is-not-a-
/// wildcard rule forbids ([`trust_ir::proof::CoverageBound::Unrecorded`]:
/// *"an import must not gain unbounded standing by omission"*).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CoverageAssuranceReport {
    checked: bool,
    recorded: usize,
    agreed: usize,
    undetermined: usize,
    errors: Vec<ValidationError>,
}

impl CoverageAssuranceReport {
    /// Did the re-derivation actually RUN?
    ///
    /// `false` means no bundle was supplied (or the bundle was not this
    /// module's, which stops the walk): every recorded row is UNCHECKED and
    /// none of them may be read as agreeing with anything.
    #[must_use]
    pub fn is_checked(&self) -> bool {
        self.checked
    }

    /// How many certificates carry an `assurance` row at all.
    #[must_use]
    pub fn recorded(&self) -> usize {
        self.recorded
    }

    /// How many recorded rows had their bound RE-DERIVED from the bundle and
    /// found EQUAL. Always 0 when [`Self::is_checked`] is `false` — never "all
    /// of them by default".
    ///
    /// A row the bundle does not determine a bound for is NOT counted here; it
    /// is counted by [`Self::undetermined`]. Conflating the two would
    /// reproduce, at row granularity, the very absence-read-as-agreement
    /// omission [`Self::is_checked`] exists to prevent at table granularity.
    #[must_use]
    pub fn agreed(&self) -> usize {
        self.agreed
    }

    /// How many recorded rows passed every check the bundle CAN make — the
    /// citation resolves and the cited request is about this obligation — but
    /// whose BOUND the bundle does not determine, so the bound itself was
    /// never re-derived.
    ///
    /// This is the honest reading of [`bound_determined_by_request`]'s
    /// deliberate narrowness. A TrustMc bounded-model-check states a bound as
    /// data, and a handful of request shapes name an UNBOUNDED procedure
    /// (TrustMc CHC / PDR, TrustWp weakest-precondition under a whole-heap
    /// frame); every other shape — TrustVc in all its modes, TrustWp
    /// strongest-postcondition and abduction, and TrustWp WP under a frame that
    /// may assume a written location unchanged — records a METHOD whose
    /// coverage is not a request field. Leaving such a row unchecked is right — but
    /// leaving it INVISIBLE is not, because then an admission gate written as
    /// `errors().is_empty()` (or as `agreed() == recorded()`, before this
    /// counter existed) accepts an `Unbounded` claim whose bundle records a
    /// depth-1 bounded check for the same obligation. And because the PRODUCER
    /// chooses which `request_digest` to record, an over-claim can always be
    /// moved into this set by citing a sibling request that lists the same
    /// obligation: the count is what makes that move visible instead of
    /// silent.
    ///
    /// That includes a sibling that DOES determine a bound: a row whose cited
    /// request agrees with it, but where another request for the same
    /// obligation fixes a bound that does not reach the claim (an `Unbounded`
    /// row citing PDR beside a depth-1 BMC request), is counted here too —
    /// check 4 of [`coverage_assurance_report`] — because the bundle records no
    /// verdict saying which of the two runs discharged the obligation.
    ///
    /// A caller that needs the bound ESTABLISHED, not merely unrefuted, admits
    /// only on `is_checked() && errors().is_empty() && undetermined() == 0`.
    #[must_use]
    pub fn undetermined(&self) -> usize {
        self.undetermined
    }

    /// The named refusals, in module order.
    #[must_use]
    pub fn errors(&self) -> &[ValidationError] {
        &self.errors
    }

    /// Consume the report for its refusals — the REFUSALS ONLY.
    ///
    /// Everything the report says that is not a refusal is dropped here, so an
    /// empty `Vec` means "no row was refused", NEVER "every row agrees". Two
    /// facts survive that reduction only because they are structural:
    ///
    /// * a report built from `Some(bundle)` is either
    ///   [`Self::is_checked`] or carries a
    ///   [`ValidationError::NativeBundleNotForThisModule`], so a caller that
    ///   supplied a bundle cannot be handed a silently-unchecked empty list
    ///   (pinned by test);
    /// * a report built from `None` reduces to an EMPTY list, which is correct
    ///   — nothing was refused — and is why
    ///   [`coverage_assurance_report`] returns this type rather than a bare
    ///   `Vec`.
    ///
    /// [`Self::undetermined`] does not survive, by design: an undetermined
    /// bound is not a violation. A caller that must not admit one reads the
    /// report itself.
    #[must_use]
    pub fn into_errors(self) -> Vec<ValidationError> {
        self.errors
    }

    /// One line a report or CLI can print. It says UNCHECKED out loud when
    /// nothing was re-derived, so absence cannot be rendered as agreement —
    /// and it names [`Self::undetermined`] alongside [`Self::agreed`], so a
    /// row whose bound the bundle never established is not printed as one that
    /// re-derived. The first number is the only one that means agreement.
    #[must_use]
    pub fn summary(&self) -> String {
        if !self.checked {
            return format!(
                "coverage assurance: UNCHECKED — no NativeVerificationBundle supplied; {} \
                 recorded assurance row{} NOT re-derived, and must not be read as agreement",
                self.recorded,
                if self.recorded == 1 { " was" } else { "s were" }
            );
        }
        format!(
            "coverage assurance: {} of {} recorded row{} re-derived against the bundle, {} \
             left UNDETERMINED by it (citation checked, bound not established — not agreement), \
             {} refusal{}",
            self.agreed,
            self.recorded,
            if self.recorded == 1 { "" } else { "s" },
            self.undetermined,
            self.errors.len(),
            if self.errors.len() == 1 { "" } else { "s" }
        )
    }
}

/// The coverage bound a bundle's OWN REQUEST FIELDS establish, or `None` when
/// the bundle establishes none.
///
/// Deliberately narrow, and the narrowness is the honesty of the rule. The
/// question it answers is: IF this request's discharge succeeded, what input
/// coverage does the procedure the request names establish? An assurance row
/// states that its certificate's discharge came from the cited request, so
/// that conditional is exactly the bound the row must project. (Whether the
/// discharge itself is sound is the certificate's business, not this rule's:
/// this rule checks that the PROJECTION is faithful.) Every arm is
/// named and tested individually (WS1.11), because mislabelling a bounded
/// procedure `Unbounded` is the unsound direction:
///
/// * **TrustMc [`BoundedModelCheck`](trust_ir::request::TrustMcVerificationMode::BoundedModelCheck)
///   → `UnwindBounded { depth: options.bmc.unwind_limit }`.** It explores up
///   to that many unwindings, which is literally what
///   [`trust_ir::proof::CoverageBound::UnwindBounded`] spells.
/// * **TrustMc [`Chc`](trust_ir::request::TrustMcVerificationMode::Chc) /
///   [`Pdr`](trust_ir::request::TrustMcVerificationMode::Pdr) → `Unbounded`.**
///   A CHC "valid" verdict is a model of the Horn clauses and a PDR/IC3
///   "safe" verdict is an inductive invariant, each proving the query
///   unreachable from EVERY state, at every depth (trust-mc's
///   `NativeTypedProofStrength::{ChcValidity, PdrInvariant}`). This holds
///   whatever `options.chc.pdr.max_frames` says: the frame cap bounds the
///   SEARCH, not the verdict — a run that hits it without a fixpoint returns
///   unknown (ay-chc `PdrResult::Unknown`, "solve_max_frames_exceeded"), which
///   discharges nothing and so carries no assurance row to check.
/// * **TrustWp [`WeakestPrecondition`](trust_ir::request::TrustWpVerificationMode::WeakestPrecondition)
///   under frame policy [`FullHeap`](trust_ir::request::TrustWpFramePolicy::FullHeap)
///   → `Unbounded`, for every loop strategy.** `RequireInvariants` and
///   `InferInvariants` close each loop with an inductive invariant, and
///   `Havoc` over-approximates the loop by forgetting everything it may
///   write, so a proof under any of them covers all inputs. That argument
///   holds only when the frame over-approximates every location a loop can
///   write — which a whole-heap frame does by construction.
/// * **TrustWp WP under [`Minimal`](trust_ir::request::TrustWpFramePolicy::Minimal)
///   or [`BorrowRegions`](trust_ir::request::TrustWpFramePolicy::BorrowRegions)
///   → `None`.** These frames may assume a location the loop writes is
///   unchanged, which makes the WP proof partial; labelling it `Unbounded`
///   would be the unsound direction. They stay undetermined until trust-wp's
///   documentation states that those frames over-approximate every written
///   location.
/// * **TrustWp `StrongestPostcondition` / `Abduction` → `None`**: neither is a
///   discharge of the obligation for all inputs by construction.
/// * **Every TrustVc mode → `None`.** TrustVc imports, merges or discharges
///   certificates somebody else scoped; its coverage is whatever the imported
///   certificate claims, not a field of the request.
///
/// Where this returns `None` the recorded bound is left UNCHECKED rather than
/// guessed at, and the row is counted by
/// [`CoverageAssuranceReport::undetermined`]. The match below is exhaustive
/// over every request/mode/strategy/frame enum on purpose: a new variant must
/// pick its arm here rather than inherit one through a wildcard.
fn bound_determined_by_request(
    request: &trust_ir::request::NativeVerificationRequest,
) -> Option<trust_ir::proof::CoverageBound> {
    use trust_ir::proof::CoverageBound;
    use trust_ir::request::{
        NativeVerificationRequest, TrustMcVerificationMode, TrustVcVerificationMode,
        TrustWpFramePolicy, TrustWpLoopStrategy, TrustWpVerificationMode,
    };
    match request {
        NativeVerificationRequest::TrustMc(request) => match request.mode {
            TrustMcVerificationMode::BoundedModelCheck => Some(CoverageBound::UnwindBounded {
                depth: u64::from(request.options.bmc.unwind_limit),
            }),
            TrustMcVerificationMode::Chc | TrustMcVerificationMode::Pdr => {
                Some(CoverageBound::Unbounded)
            }
        },
        NativeVerificationRequest::TrustWp(request) => match request.mode {
            TrustWpVerificationMode::WeakestPrecondition => match request.options.frame_policy {
                TrustWpFramePolicy::FullHeap => match request.options.loop_strategy {
                    TrustWpLoopStrategy::RequireInvariants
                    | TrustWpLoopStrategy::InferInvariants
                    | TrustWpLoopStrategy::Havoc => Some(CoverageBound::Unbounded),
                },
                TrustWpFramePolicy::Minimal | TrustWpFramePolicy::BorrowRegions => None,
            },
            TrustWpVerificationMode::StrongestPostcondition
            | TrustWpVerificationMode::Abduction => None,
        },
        NativeVerificationRequest::TrustVc(request) => match request.mode {
            TrustVcVerificationMode::ImportProofCertificates
            | TrustVcVerificationMode::MergeProofCertificates
            | TrustVcVerificationMode::DischargeProofObligations => None,
        },
    }
}

/// WS5.3b: a [`trust_ir::ModuleCompleteness::Partial`] claim's rows are
/// checked against the module. Each row must name a bodyless function or no
/// function ([`ValidationError::UnloweredRowNamesDefinition`]), symbols are
/// unique ([`ValidationError::DuplicateUnloweredRow`]), and the row list is
/// non-empty ([`ValidationError::EmptyPartialClaim`]). `None` and `Complete`
/// have nothing to check here: whether `Complete` is TRUE is a producer rule
/// the format cannot decide (`docs/SPEC_RATIFICATIONS.md` §15).
fn validate_completeness_claim(module: &Module) -> Vec<ValidationError> {
    let mut errors = Vec::new();
    let Some(trust_ir::ModuleCompleteness::Partial(rows)) = &module.completeness else {
        return errors;
    };
    if rows.is_empty() {
        errors.push(ValidationError::EmptyPartialClaim);
    }
    let mut seen: BTreeSet<&str> = BTreeSet::new();
    for row in rows {
        if !seen.insert(row.symbol.as_str()) {
            errors.push(ValidationError::DuplicateUnloweredRow {
                symbol: row.symbol.clone(),
            });
            continue;
        }
        // Every DEFINITION with the symbol contradicts the row; a
        // `DuplicateFunctionSymbol` module reports each, in id order.
        for func in &module.functions {
            if func.name == row.symbol && !func.blocks.is_empty() {
                errors.push(ValidationError::UnloweredRowNamesDefinition {
                    symbol: row.symbol.clone(),
                    function: func.id.index(),
                });
            }
        }
    }
    errors
}

/// Why a module is not known to be complete (WS5.3b, F-090): the verdict of
/// [`validate_module_complete`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CompletenessError {
    /// [`trust_ir::Module::completeness`] is `None`: the producer made NO
    /// claim. Never a wildcard — every pre-carrier blob and every hand-built
    /// module reads as this, and a consumer that needs a complete module
    /// refuses it exactly as it refuses a partial one. Must-refuse corpus row
    /// `refuse/completeness_unclaimed`.
    IncompletenessUnclaimed,
    /// The producer claims the module is partial: these rows were not
    /// lowered.
    ModuleIncomplete { rows: Vec<trust_ir::UnloweredRow> },
}

impl core::fmt::Display for CompletenessError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::IncompletenessUnclaimed => f.write_str(
                "the module makes no completeness claim (Module.completeness is None); a \
                 consumer that needs a complete module refuses it, never assumes it",
            ),
            Self::ModuleIncomplete { rows } => {
                write!(
                    f,
                    "the module claims to be partial: {} unlowered item(s)",
                    rows.len()
                )?;
                for row in rows {
                    write!(f, "; {:?}", row.symbol)?;
                    if let Some(path) = &row.display_path {
                        write!(f, " ({path})")?;
                    }
                    write!(f, ": {}", row.reason)?;
                }
                Ok(())
            }
        }
    }
}

impl std::error::Error for CompletenessError {}

/// Is `module` affirmatively COMPLETE (WS5.3b, F-090)?
///
/// `Ok(())` only for `Some(Complete)`. `None` is
/// [`CompletenessError::IncompletenessUnclaimed`] and `Partial` is
/// [`CompletenessError::ModuleIncomplete`] with its rows. This does not run
/// [`validate_module`]; a `Partial` claim's rows are checked against the
/// module there (`UnloweredRowNamesDefinition`, `DuplicateUnloweredRow`,
/// `EmptyPartialClaim`). Whether a `Complete` claim is TRUE is a producer
/// rule the format cannot decide (`docs/SPEC_RATIFICATIONS.md` §15).
pub fn validate_module_complete(module: &Module) -> Result<(), CompletenessError> {
    match &module.completeness {
        None => Err(CompletenessError::IncompletenessUnclaimed),
        Some(trust_ir::ModuleCompleteness::Complete) => Ok(()),
        Some(trust_ir::ModuleCompleteness::Partial(rows)) => {
            Err(CompletenessError::ModuleIncomplete { rows: rows.clone() })
        }
    }
}

/// The reason `module` has NO WIRE IDENTITY, if any: the first construct (or
/// count) the canonical binary writer refuses, as the
/// [`ValidationError::ModuleHasNoWireIdentity`] a digest-keyed entry point
/// reports instead of letting [`trust_ir::Module::stable_digest`] panic.
///
/// An ADAPTER, not a list (D1a): the verdict is
/// [`trust_ir::Module::wire_image_refusal`], the writer itself run over a
/// check sink, so this cannot omit a construct the writer refuses. Its
/// hand-written predecessor probed the instruction gap list, the scope
/// inlining chain, the completeness claim, the certificate binding and the
/// typed signature ABI's encoding limits, and omitted the producer-internal
/// `Ty::Error` — which JSON and MessagePack spell — so `trust-ir validate
/// --link` and every other digest-keyed path below panicked on a one-line
/// edit of an input file. The precedence and the `location` / `construct`
/// strings of the carriers it already named are unchanged: an instruction
/// ahead of its wire tag (the ONE list is [`Inst::binary_wire_gap`], empty
/// since wire v51), a lexical scope's inlining chain link
/// (`ScopeData.inlined_at`, WS4.19), a module completeness claim (WS5.3b), a
/// typed signature ABI past its encoding limits (wire v60; unused signature
/// rows included); then `Ty::Error`, then a count past the format's `u32`.
/// When a wire part lands, the writer's arm stops refusing it and this
/// answers `None` with no edit here: the certificate binding
/// (`CleanCicKernelRecheck.binding`, WS1.12a) was such a part, carried since
/// wire v61.
///
/// Every digest-keyed entry point of this crate consults it before hashing:
/// [`coverage_assurance_report`] with a bundle (the root), and the linked
/// import walk (the root at its entry, each resolved candidate at L2 — a
/// candidate without an identity cannot be authenticated, and is refused as
/// `UnauthenticatedImport` with this reason in its detail).
#[must_use]
pub fn wire_identity_blocker(module: &Module) -> Option<ValidationError> {
    use trust_ir::BinaryProjectionError as Refusal;
    let refusal = module.wire_image_refusal()?;
    let function_name = |function: u32| {
        module
            .function_by_id(trust_ir::FuncId::new(function))
            .map_or("?", |f| f.name.as_str())
            .to_owned()
    };
    let (location, construct) = match &refusal {
        Refusal::ConstructAheadOfWireTag {
            construct,
            site: Some(site),
        } => (
            format!(
                "function '{}' bb{} #{}",
                function_name(site.function),
                site.block,
                site.index
            ),
            (*construct).to_owned(),
        ),
        Refusal::ConstructAheadOfWireTag {
            construct,
            site: None,
        } => (
            "module".to_owned(),
            format!("{construct}, a variant ahead of its binary wire tag"),
        ),
        Refusal::InlinedScopeChainUnencodable { function, scope } => (
            format!(
                "function '{}' lexical scope #{scope}",
                function_name(*function)
            ),
            "a ScopeData.inlined_at inlining chain link ahead of its binary carrier (the WS4.19 \
             wire part, a member of the next open wire batch, docs/wire-allocation.md)"
                .to_owned(),
        ),
        Refusal::CompletenessClaimUnencodable => (
            "module".to_owned(),
            "a Module.completeness claim ahead of its binary carrier (the WS5.3b wire part, a \
             member of the next open wire batch, docs/wire-allocation.md)"
                .to_owned(),
        ),
        // A CertificateBinding (CleanCicKernelRecheck.binding) is no longer a
        // refusal since wire v61 (CERTIFICATE_BINDING_FORMAT_VERSION): the
        // writer carries it.
        Refusal::SignatureAbiUnencodable { signature, detail } => (
            format!("signature #{signature}"),
            format!("typed signature ABI exceeds encoding limits: {detail}"),
        ),
        Refusal::ProducerInternalType => (
            "module".to_owned(),
            "the producer-internal Ty::Error (a fail-closed typing placeholder with no wire \
             spelling at any version; validate_module refuses it)"
                .to_owned(),
        ),
        Refusal::CountExceedsFormat { what, count } => (
            (*what).to_owned(),
            format!("a count of {count}, past the binary format's u32 limit"),
        ),
        // The projection-only refusals (a v38 spelling, an omission) are
        // never a writer refusal; named by their own text if one ever were.
        other => ("module".to_owned(), other.to_string()),
    };
    Some(ValidationError::ModuleHasNoWireIdentity {
        location,
        construct,
    })
}

/// Re-derive every recorded [`trust_ir::proof::CoverageAssurance`] against the
/// bundle it cites.
///
/// # DEPRECATED — false provenance
///
/// Superseded by [`crate::coverage_establishment_report`]. This rule derives a
/// bound from the cited request's MODE alone ([`bound_determined_by_request`]
/// holds only "IF this request's discharge succeeded"), so a pending CHC
/// request with no evidence at all "agrees" with an `Unbounded` row: a request
/// is a question, not an answer. And a row that cites a request whose replay
/// transcript binds the module digest can never resolve, because the module
/// digest covers the row. The replacement reads no producer-written row as a
/// source of coverage. This function stays only because downstream consumers
/// (trust-vc, Trust) still call it; it is deleted once their pins move past
/// the replacement.
///
/// # The gap this closes
///
/// `ProofCertificate::assurance` projects a [`trust_ir::proof::CoverageBound`]
/// and the `request_digest` of the evidence bundle it was projected FROM. The
/// digest exists so the projection is checkable rather than a second source of
/// truth — and until this rule landed nothing in the repo re-derived it, so a
/// `UnwindBounded { depth: 1 }` certificate and an `Unbounded` one were
/// operationally indistinguishable.
///
/// # The three checks, in order, per assurance row
///
/// 0. **The bundle must be this module's.** `bundle.trust_ir_module_digest`
///    must equal `module.stable_digest()`, or the walk stops with
///    [`ValidationError::NativeBundleNotForThisModule`] and the report reads
///    UNCHECKED. A bundle about a different module can neither confirm nor
///    refute a projection.
/// 1. **The citation must resolve.** `assurance.request_digest` must equal
///    `request.stable_digest()` for some request in the bundle, else
///    [`ValidationError::CoverageAssuranceRequestUnknown`]. RECOMPUTED from
///    the request, deliberately, rather than compared against
///    `NativeEvidenceBundle::request_digest` — that field is a COPY of the same
///    number, so trusting it would re-derive nothing; and a request-only
///    handoff (`evidence_bundles` empty, which producers are allowed to ship)
///    would then be uncheckable. (Request-table well-formedness — duplicate
///    ids included — is `NativeVerificationBundle::validate`'s job, so the
///    first match is taken.)
/// 2. **The citation must be about THIS obligation.** That request's
///    `obligations` must contain the certificate's obligation, else
///    [`ValidationError::CoverageAssuranceObligationNotRequested`]. Without
///    this a certificate could borrow the coverage of a sibling discharge in
///    the same bundle — the digest alone does not catch it.
/// 3. **The bound must be the re-derived one**, where the bundle determines
///    one at all (see [`bound_determined_by_request`]), else
///    [`ValidationError::CoverageAssuranceBoundMismatch`]. Equality, not a
///    partial order: a row whose entire purpose is to project the bundle's
///    bound may not record `Unrecorded` against a request that states a depth,
///    nor `UnwindBounded` against a request that names an unbounded procedure.
///    Where the bundle determines NO bound, the row is counted by
///    [`CoverageAssuranceReport::undetermined`] and NOT by
///    [`CoverageAssuranceReport::agreed`] — the third outcome is reported as
///    itself, because a row whose bound was never looked at has not agreed
///    with anything.
/// 4. **No sibling may fix a shorter bound for the same obligation.** If
///    another request in the bundle lists this obligation and
///    [`bound_determined_by_request`] fixes a bound for it that does not
///    [`crate::linked::coverage_supports`] the claimed one, the row is counted
///    by [`CoverageAssuranceReport::undetermined`], not agreed. The bundle
///    records no per-obligation verdict, so beside a depth-1 BMC request for
///    the same obligation it cannot establish that the cited PDR request, and
///    not the BMC one, is what discharged it — and the producer chooses the
///    citation. An UNDER-claim (a depth-1 row citing the BMC request beside a
///    PDR sibling) holds under either attribution and still agrees. Without
///    this check, deriving `Unbounded` from CHC / PDR / whole-heap WP (WS1.11)
///    would let an over-claim move from `undetermined` to `agreed` just by
///    citing the unbounded sibling.
///
/// `recorded() == agreed() + undetermined() + errors().len()` on every checked
/// report.
///
/// # No bundle
///
/// `bundle: None` produces NO errors and a report whose
/// [`CoverageAssuranceReport::is_checked`] is `false`. That is not agreement,
/// and [`CoverageAssuranceReport::summary`] says so in words. A module
/// separated from its bundle is the normal case, and refusing it would make
/// every single-artifact validation fail; reading its silence as confirmation
/// would be the unsound half of the same choice.
///
/// # Admitting on this report
///
/// An empty error list means "no row was REFUSED". A caller that needs each
/// recorded bound to have been ESTABLISHED admits only on
///
/// ```text
/// report.is_checked() && report.errors().is_empty() && report.undetermined() == 0
/// ```
///
/// Dropping the third conjunct admits an `Unbounded` row whose bundle records
/// a depth-1 bounded model check for that same obligation, because the
/// producer picks which request the row cites: a sibling that determines no
/// bound, or an unbounded sibling beside the BMC request (check 4), leaves the
/// row undetermined rather than refused.
///
/// # The other half, and where it lives
///
/// The companion rule — refusing an IMPORT whose cited discharge is
/// `Unrecorded`-or-bounded where the importer's own claim needs unbounded — is
/// about a different table (`Module::imports` plus the FAR module's
/// certificates) and therefore a different entry point: it landed as linked
/// rule L9 in [`crate::validate_linked_module`], with the per-pair ordering in
/// [`crate::linked::coverage_supports`] and the refusal
/// [`ValidationError::ImportCoverageBelowClaim`]. `validate_module` and this
/// report hold no dependency module, so they cannot check it and do not claim
/// to; the two rules are complementary, not alternatives — one asks whether a
/// recorded bound is FAITHFUL to its bundle, the other whether it is SUFFICIENT
/// for what an importer built on it.
///
/// A module with NO WIRE IDENTITY (see
/// [`ValidationError::ModuleHasNoWireIdentity`]) cannot be bound to any
/// bundle: with a bundle supplied the report is `checked: false` with that
/// one error, never a panic out of `stable_digest`.
#[must_use]
#[deprecated(
    since = "0.14.0",
    note = "false provenance: derives coverage from a request's mode, not a verified result; \
            use `coverage_establishment_report`"
)]
pub fn coverage_assurance_report(
    module: &Module,
    bundle: Option<&trust_ir::request::NativeVerificationBundle>,
) -> CoverageAssuranceReport {
    let recorded = module
        .proof_certificates
        .iter()
        .filter(|certificate| certificate.assurance.is_some())
        .count();
    let Some(bundle) = bundle else {
        return CoverageAssuranceReport {
            checked: false,
            recorded,
            agreed: 0,
            undetermined: 0,
            errors: Vec::new(),
        };
    };
    if let Some(error) = wire_identity_blocker(module) {
        return CoverageAssuranceReport {
            checked: false,
            recorded,
            agreed: 0,
            undetermined: 0,
            errors: vec![error],
        };
    }
    let expected = module.stable_digest();
    if bundle.trust_ir_module_digest != expected {
        return CoverageAssuranceReport {
            checked: false,
            recorded,
            agreed: 0,
            undetermined: 0,
            errors: vec![ValidationError::NativeBundleNotForThisModule {
                expected,
                actual: bundle.trust_ir_module_digest,
            }],
        };
    }
    let mut errors = Vec::new();
    let mut agreed = 0usize;
    let mut undetermined = 0usize;
    for certificate in &module.proof_certificates {
        let Some(assurance) = certificate.assurance else {
            continue;
        };
        let obligation = certificate.obligation;
        let cited = bundle
            .requests
            .iter()
            .find(|request| request.stable_digest() == assurance.request_digest);
        let Some(cited) = cited else {
            errors.push(ValidationError::CoverageAssuranceRequestUnknown {
                obligation: obligation.index(),
                recorded: assurance.request_digest,
                bundle_requests: bundle.requests.len(),
            });
            continue;
        };
        let requested = cited.obligations();
        if !requested.contains(&obligation) {
            errors.push(ValidationError::CoverageAssuranceObligationNotRequested {
                obligation: obligation.index(),
                request: cited.id().index(),
                request_obligations: requested.iter().map(|id| id.index()).collect(),
            });
            continue;
        }
        // The bound is the one thing the bundle establishes only SOMETIMES,
        // so its three outcomes stay three: re-derived and equal (agreement),
        // re-derived and different (a refusal), and not determined at all
        // (neither). Folding the third into the first is the bug this shape
        // exists to prevent — see `CoverageAssuranceReport::undetermined`.
        let Some(derived) = bound_determined_by_request(cited) else {
            undetermined += 1;
            continue;
        };
        if derived != assurance.bound {
            errors.push(ValidationError::CoverageAssuranceBoundMismatch {
                obligation: obligation.index(),
                recorded: format!("{:?}", assurance.bound),
                derived: format!("{derived:?}"),
            });
            continue;
        }
        // Check 4: the bundle must not ALSO record, for this obligation, a
        // request whose own fields fix a bound short of the claim. The bundle
        // carries no per-obligation verdict, so it cannot say which of the two
        // runs discharged the obligation; the stronger claim is therefore not
        // established by it (an under-claim is, and passes). The cited request
        // supports itself, so it needs no exclusion.
        let contested = bundle.requests.iter().any(|sibling| {
            sibling.obligations().contains(&obligation)
                && bound_determined_by_request(sibling)
                    .is_some_and(|fixed| !crate::linked::coverage_supports(fixed, derived))
        });
        if contested {
            undetermined += 1;
            continue;
        }
        agreed += 1;
    }
    debug_assert_eq!(
        recorded,
        agreed + undetermined + errors.len(),
        "every recorded row takes exactly one of the four per-row exits"
    );
    CoverageAssuranceReport {
        checked: true,
        recorded,
        agreed,
        undetermined,
        errors,
    }
}

/// Validate `module` **together with the bundle it cites**: everything
/// [`validate_module`] checks, plus the coverage-assurance re-derivation of
/// [`coverage_assurance_report`].
///
/// This is the composition point for a consumer that actually HOLDS the
/// bundle — the only position from which `ProofCertificate::assurance` is
/// checkable at all. Structural errors come first, assurance refusals last, on
/// the [`validate_module_for_codegen`] pattern.
///
/// It is a REFUSAL list, not a bound-establishment claim: an empty result
/// means no assurance row was refused, and rows whose bound the bundle does
/// not determine pass through it silently and legitimately (they are not
/// violations). A consumer whose admission decision turns on the bound having
/// been re-derived must call [`coverage_assurance_report`] directly and read
/// [`CoverageAssuranceReport::undetermined`].
///
/// It does not re-run [`trust_ir::request::NativeVerificationBundle::validate`]:
/// that is the bundle's own well-formedness (schema version, digest algebra,
/// duplicate request ids, lineage), it is owned by the format crate, and a
/// consumer must run it too. This entry point answers one question the bundle
/// cannot answer about itself — whether the MODULE's recorded projections are
/// the ones the bundle establishes.
#[must_use]
pub fn validate_module_with_bundle(
    module: &Module,
    bundle: &trust_ir::request::NativeVerificationBundle,
) -> Vec<ValidationError> {
    let mut errors = validate_module(module);
    #[allow(deprecated)]
    errors.extend(coverage_assurance_report(module, Some(bundle)).into_errors());
    errors
}

/// [`validate_module_with_bundle`] under a proof-replay capability (roadmap
/// WS1.5, F-009): [`validate_module_with_authority`] plus the same
/// coverage-assurance re-derivation, so a consumer that holds both a replay
/// capability and the bundle need not re-compose the layers by hand.
/// Structural/authority errors first, assurance refusals last.
///
/// Like [`validate_module_with_authority`] it REFUSES every proof-bearing
/// cross-crate row ([`ValidationError::UnauthenticatedImport`]); authenticate
/// those with [`crate::validate_linked_module`].
#[must_use]
pub fn validate_module_with_bundle_with_authority(
    module: &Module,
    bundle: &trust_ir::request::NativeVerificationBundle,
    authority: &dyn trust_ir::proof::ModuleProofAuthority,
) -> Vec<ValidationError> {
    let mut errors = validate_module_with_authority(module, authority);
    #[allow(deprecated)]
    errors.extend(coverage_assurance_report(module, Some(bundle)).into_errors());
    errors
}

/// Whether a DECLARED closure frame may lift the closure-application codegen
/// refusal, as far as the application's APPARENT signature is concerned — the
/// edge's declared `sig` and the closure type's `func`. G18-2 requires the two
/// to be equal (their disagreement is `CallIndirectClosureSigMismatch`,
/// reported separately); both are read here, so a claim cannot be moved off
/// the edge to escape this check.
///
/// The lift reads an apparent signature as saying nothing about the lowered
/// call beyond the caller's own argument list, because the application
/// spreads the captured environment IN FRONT of those arguments. A `FuncTy`
/// field that records a fact about the signature's OWN parameter list — a
/// typed callable ABI binding `Parameter(i)`, a hidden parameter, a calling
/// convention — would describe a call the backend does not make, and admitting
/// the application would hand the backend that wrong description.
///
/// The destructuring below is EXHAUSTIVE on purpose (a compile-time tripwire):
/// a new `FuncTy` field does not compile here until its author decides whether
/// a declared frame still lifts the refusal while the field records a claim.
/// The fail-closed answer is that it does not — for an `Option` claim, lift
/// only while it is `None` — and the refusal on that ground must then name the
/// apparent signature rather than the missing layout row (split the `detail`
/// at the call site in [`codegen_lowerability_errors`]), with a structurally
/// valid module and its unclaimed twin as the pinning tests.
fn closure_lift_admits_apparent_signature(
    module: &Module,
    closure: trust_ir::value::ClosureTyId,
    sig: trust_ir::value::FuncTyId,
) -> bool {
    [Some(sig), module.closure_type(closure).map(|ty| ty.func)]
        .into_iter()
        .flatten()
        .filter_map(|id| module.func_type(id))
        .all(|apparent| {
            let FuncTy {
                params: _,
                returns: _,
                is_vararg: _,
                abi,
            } = apparent;
            abi.is_none()
        })
}

/// The G18-1 codegen-LOWERABILITY layer alone, with no structural validation
/// and no license check.
///
/// # What this is, and what it deliberately is not
///
/// It is not a well-formedness pass and not a subset checker. It reports the
/// short, closed list of constructs that are **valid TrustIr** — they
/// round-trip through all four codecs and the reference interpreter executes
/// them — but that the FORMAT does not describe well enough for any conforming
/// backend to lower. Each entry names the missing information, not a missing
/// backend feature; adding the information is a format change, which is why the
/// list cannot be closed by a backend author.
///
/// # The population, and why each member is here
///
/// * **`Inst::Dealloc`** — one field (`ptr`) against `HeapAlloc`'s four. It
///   names neither the `AllocOrigin` that owns the region nor the layout being
///   released, and a correct free needs both: Rust's `GlobalAlloc::dealloc`
///   requires the SAME `Layout` used to allocate, Clean/Swift release goes
///   through the reference-counted runtime rather than a raw free, and only C
///   `free` takes a bare pointer. A backend that guessed `free(ptr)` would be
///   wrong for three of the four origins — and a backend that RECOVERS the
///   origin and the layout from dataflow is not a conforming lowering either
///   (re-decided 2026-09-27, `docs/SPEC_RATIFICATIONS.md` "Deallocation is
///   refused for codegen, whatever its provenance"): every `Dealloc` is refused
///   here whatever its pointer's provenance (in every body, whatever the
///   license policy), and a conforming codegen consumer MUST refuse it
///   (`refuse/dealloc_instruction`). trust-cg conforms since trust-cg main
///   c1b7c2c54 (2026-09-27, pin 7b0947ee): its provenance lowering
///   (`translate_dealloc`) is deleted, it refuses every `Dealloc` as
///   `[TCG-DEALLOC]`, and its strict entry reads THIS function's verdict
///   over every body, a skipped one included
///   (`refuse_dealloc_by_trust_ir_verdict`). `docs/SPEC_RATIFICATIONS.md`,
///   the ruling's `(external)` entry, names the trust-cg tests that hold it.
/// * **`Inst::CallIndirect` (and its twins `CallIndirectCannotUnwind` and
///   `InvokeIndirect`) over a `Ty::Closure` callee** — G18-2 made
///   `Ty::Closure` eliminable (the reference interpreter applies it, spreading
///   the captured environment as leading arguments), but no backend implements
///   that ABI, and a backend that treats the callee operand as a code address
///   the way it treats a `Ty::Func` value does not fail — it MISCOMPILES. This
///   is the sharper of the two: an opaque late error is recoverable, a
///   plausible-and-wrong lowering is not. Since the 2026-09-19 ratification
///   (`lowering-target-subset.md`, "Closure application") application is
///   `FnOnce`-shaped — captures are arguments, and a by-reference capture is a
///   pointer-TYPED capture slot — so the missing information is not the
///   capture MODE but the environment's LAYOUT: rustc reorders `repr(Rust)`
///   upvars, and a backend laying the captures out in declaration order
///   miscompiles. Lifting this refusal therefore needs a DECLARED closure
///   layout, and it is lifted for nothing else. Closure INTRODUCTION
///   (`Const` + `InsertField`) and capture PROJECTION (`ExtractField`) are not
///   refused; only APPLICATION is.
/// * **`Inst::ExtractElement` / `Inst::InsertElement` over a `Ty::Sequence`**
///   (WS3.17, F-051) — the element ops this increment admits. The read and the
///   write are executable in both engines and now checked by the validator
///   (element type against the module's `TyId`, unsigned index), but
///   `Ty::Sequence` has NO machine layout: `shape.rs` answers
///   `UnsupportedTyShape` for it, so there is no size, no alignment and no
///   element stride for a backend to address with. The refusal is named here
///   rather than left to the backend's layout query, which is a late error in
///   a different repo. Scope note: the sequence ops that do not read an
///   element (`SeqMapAddK` / `SeqMapNot` / `SeqMap`) are not listed, because
///   they are structural maps of a value whose materialization already hits
///   the same layout refusal; this entry names the ops whose RESULT is an
///   ordinary lowerable scalar, where nothing else in the node says the
///   operand cannot be addressed.
/// * **`Inst::DialectOp` in an unknown namespace** (WS2.20, F-046) — any
///   namespace other than the in-tree decoded dialects (`vector` / `gpu` /
///   `avx512` / `ane` / `trust_rust`). The op round-trips opaquely and the
///   structural validator deliberately leaves it unchecked (a downstream
///   registry may own it), so nothing about it — operand contract, effects,
///   result semantics — is stated in a form any backend can lower. trust-cg
///   already fails closed on it; this names the refusal at the format boundary.
/// * **`Inst::TensorContract`** (the tensor region, PKG-U13a) — a contraction
///   is executable in the reference interpreter and in SemR, and its static
///   rules are checked by the validator, but `Ty::Tensor` has no machine
///   layout (`shape.rs` answers `UnsupportedTyShape`, as for `Ty::Sequence`:
///   its extents are run-time values, so there is no size and no stride) and
///   no backend lowers the contraction; the tensor region is outside the
///   lowering-target subset. The refusal is named here rather than left to a
///   backend's layout query. A tensor-typed parameter or block parameter is
///   not listed: it relies on the backend's layout refusal, as a
///   `Ty::Sequence` one does.
/// * **`Inst::TensorMap` / `Inst::TensorReduce` / `Inst::TensorView`** (the
///   tensor region's map, reduce and view, PKG-U13c) — for the contraction's
///   reason: executable in both engines and checked by the validator, but
///   over a type with no machine layout, and no backend lowers them.
/// * **`Inst::TensorGather` / `Inst::TensorScatter`** (the tensor region's
///   gather and scatter, PKG-U13d) — for the same reason.
/// * **An `Inst::Const` of a `Constant::TensorBlob`** (the tensor region's
///   content-addressed weights, PKG-U13e) — for the same reason.
///
/// Each of these is a must-refuse corpus row a consumer runs
/// (`refuse/dealloc_instruction`, `refuse/sequence_element_op`,
/// `refuse/dialect_op_foreign_namespace`, `refuse/tensor_contract_codegen`,
/// `refuse/tensor_map_reduce_view_codegen`,
/// `refuse/tensor_gather_scatter_codegen`, `refuse/tensor_blob_codegen`):
/// well-formed for `validate_module`, refused here.
///
/// # Why a refusal rather than a widening
///
/// The other resolution for `Dealloc` was to widen it to mirror `HeapAlloc`
/// (`ty` / `count` / `align` / `origin`) on a new wire version. That was
/// measured and rejected: no producer emits `Dealloc` at all — Clean lowers
/// `dec x` to `Release`, the Rust producers spell every free as a call (drop
/// glue's `__rust_dealloc`), and the only constructions anywhere in the
/// constellation are this repo's own tests and CLI demos — so widening would
/// mint wire surface nothing writes, and it
/// would not even restore the construct to the proven subset, because the Lean
/// model's `semDealloc` is a pointer-only dead-marking rule with no allocator
/// identity and no layout check. See `lowering-target-subset.md`.
#[must_use]
pub fn codegen_lowerability_errors(module: &Module) -> Vec<ValidationError> {
    codegen_lowerability_errors_in(&module.layout_table())
}

/// [`codegen_lowerability_errors`] over the module of `layouts`, asking that
/// table every layout question of the pass.
///
/// Every indirect call over a closure asks whether the closure's frame lays
/// out; one table answers them all, laying each struct, enum and capture
/// once, so the pass costs O(the module) however many calls share a closure
/// type. (It asked a fresh table per call before: N calls over a closure
/// capturing an N-deep struct chain did O(N^2) work, 19 s at N = 8000.) A
/// caller that already holds a table for the module passes it here and the
/// pass reuses what it laid out; the table's [`trust_ir::LayoutTableStats`]
/// count the pass's work.
#[must_use]
pub fn codegen_lowerability_errors_in(layouts: &trust_ir::LayoutTable<'_>) -> Vec<ValidationError> {
    let module = layouts.module();
    let mut errors = Vec::new();
    let drop_glue = module.drop_glue_index();
    for func in &module.functions {
        if func.is_declaration() {
            continue;
        }
        // Only computed when a `CallIndirect` is actually present, so the
        // common function pays nothing.
        let mut val_ty: Option<BTreeMap<u32, Ty>> = None;
        for block in &func.blocks {
            for node in &block.body {
                match &node.inst {
                    Inst::Dealloc { .. } => {
                        errors.push(ValidationError::UnlowerableForCodegen {
                            function: func.id.index(),
                            name: func.name.clone(),
                            block: block.id.index(),
                            inst: "Dealloc",
                            detail: "the instruction names only a pointer: it states neither the \
                                 AllocOrigin whose runtime owns the region nor the layout \
                                 being released, and Rust's GlobalAlloc contract requires \
                                 the exact Layout the allocation was made with. Spell the \
                                 release the way its runtime pins it: Release for a \
                                 reference-counted cell, the pinned drop entry for a handle, \
                                 and for RustHeap/CMalloc a call the producer pairs with its \
                                 own allocation (Rust drop glue's __rust_dealloc)"
                                .to_string(),
                        });
                    }
                    // Amendment D, Part 2: `InvokeIndirect` applies its
                    // callee exactly as `CallIndirect` does, so a closure
                    // callee is refused on it too.
                    Inst::CallIndirect { callee, sig, .. }
                    | Inst::CallIndirectCannotUnwind { callee, sig, .. }
                    | Inst::InvokeIndirect { callee, sig, .. } => {
                        let types =
                            val_ty.get_or_insert_with(|| build_module_value_types(func, module));
                        // v58 (WS3.13): the refusal is lifted for a closure
                        // type whose environment frame the producer DECLARED,
                        // and only then. Without a layout row the closure
                        // value has no byte image at all, so a backend has
                        // nothing to lay the environment out with — which is
                        // the state every closure was in before v58, and the
                        // refusal text is unchanged for it. FAIL CLOSED on
                        // an INCOHERENT row too: overlapping or misaligned
                        // captures, a frame too short, two rows for one
                        // closure type, a row naming no closure type, or no
                        // target to size the captures against — none of
                        // these is a declared frame, so the refusal stays
                        // (and the structural validator names the row's
                        // defect as `TupleLayoutInconsistent` beside it, its
                        // reason naming the closure table).
                        //
                        // The lift also consults the application's APPARENT
                        // signature (`closure_lift_admits_apparent_signature`,
                        // an exhaustive compile-time tripwire on `FuncTy`).
                        if let Some(Ty::Closure(id)) = types.get(&callee.index())
                            && (layouts.ty_layout(&Ty::Closure(*id)).is_err()
                                || !closure_lift_admits_apparent_signature(module, *id, *sig))
                        {
                            errors.push(ValidationError::UnlowerableForCodegen {
                                function: func.id.index(),
                                name: func.name.clone(),
                                block: block.id.index(),
                                inst: if matches!(node.inst, Inst::InvokeIndirect { .. }) {
                                    "InvokeIndirect"
                                } else {
                                    "CallIndirect"
                                },
                                // The pre-v58 text, VERBATIM (WS3.13 rule 3: "without
                                // a row the refusal text is unchanged"; the gate-9
                                // `closure_application_by_value` test pins its two
                                // clauses), followed by the one thing v58 adds.
                                detail: if layouts.ty_layout(&Ty::Closure(*id)).is_ok() {
                                    format!(
                                        "the callee is a Ty::Closure value with a declared frame, but the application signature functy.{} or the closure's apparent signature carries typed ABI placement for its own parameters. Spreading the captured environment changes that physical call. Lower the closure with an explicit environment and an entry signature whose ABI describes the complete lowered call",
                                        sig.index()
                                    )
                                } else {
                                    "the callee is a Ty::Closure value. The closure \
                                     application ABI (captured environment spread as \
                                     leading arguments) is executable in the reference \
                                     interpreter and checked by the validator, but no \
                                     backend implements it, and a backend that treats \
                                     the callee operand as a code address (the way it \
                                     treats a Ty::Func value) miscompiles rather than \
                                     failing. Lower the closure explicitly: an \
                                     environment aggregate plus a Ty::Func pointer. \
                                     Since wire v58 the refusal is lifted for a closure \
                                     type whose environment frame is DECLARED and \
                                     coherent (`Module.closure_layouts`); this closure \
                                     type has no such row"
                                    .to_string()
                                },
                            });
                        }
                    }
                    // WS3.17 (F-051): an element op over a `Ty::Sequence`.
                    Inst::ExtractElement { array, .. } | Inst::InsertElement { array, .. } => {
                        let types =
                            val_ty.get_or_insert_with(|| build_module_value_types(func, module));
                        if let Some(Ty::Sequence(_)) = types.get(&array.index()) {
                            errors.push(ValidationError::UnlowerableForCodegen {
                                function: func.id.index(),
                                name: func.name.clone(),
                                block: block.id.index(),
                                inst: match &node.inst {
                                    Inst::InsertElement { .. } => "InsertElement",
                                    _ => "ExtractElement",
                                },
                                detail: "the operand is a Ty::Sequence value. WS3.17 admits the \
                                     element read and write at the VERIFICATION level — the \
                                     reference interpreter and the Lean model both execute \
                                     them — but Ty::Sequence has no machine layout at all \
                                     (shape.rs answers UnsupportedTyShape: no size, no \
                                     alignment, no element stride), so no conforming backend \
                                     can address an element of one. Lower the carrier first: \
                                     a fixed-size Ty::Array, or a pointer plus a length"
                                    .to_string(),
                            });
                        }
                    }
                    // Amendment D (§20 rule 4): an UNRESOLVED drop states no
                    // destructor, and a drop is never lowered as nothing
                    // (`refuse/drop_unresolved`). A resolved one is admitted
                    // here; a backend that does not lower it yet refuses it
                    // by name.
                    Inst::Drop { ty, .. } | Inst::DropInvoke { ty, .. }
                        if !matches!(
                            drop_glue.resolve(ty),
                            trust_ir::DropResolution::Resolved(_)
                        ) =>
                    {
                        errors.push(ValidationError::UnlowerableForCodegen {
                            function: func.id.index(),
                            name: func.name.clone(),
                            block: block.id.index(),
                            inst: instruction_shape_name(&node.inst),
                            detail: format!(
                                "no drop_glue row for {ty}: the destructor is not stated, and a \
                                 drop is never lowered as nothing"
                            ),
                        });
                    }
                    Inst::DialectOp(op) if !is_in_tree_dialect_namespace(&op.dialect) => {
                        errors.push(ValidationError::UnlowerableForCodegen {
                            function: func.id.index(),
                            name: func.name.clone(),
                            block: block.id.index(),
                            inst: "DialectOp",
                            detail: format!(
                                "unknown dialect namespace {}: no registered lowering",
                                op.dialect
                            ),
                        });
                    }
                    // The tensor region (PKG-U13a): no machine lowering yet
                    // (`refuse/tensor_contract_codegen`).
                    Inst::TensorContract { .. } => {
                        errors.push(ValidationError::UnlowerableForCodegen {
                            function: func.id.index(),
                            name: func.name.clone(),
                            block: block.id.index(),
                            inst: "TensorContract",
                            detail: "a tensor contraction has no machine lowering yet (PKG-U13: \
                                     outside the lowering-target subset)"
                                .to_string(),
                        });
                    }
                    // Its map, reduce and view (PKG-U13c): no machine
                    // lowering either (`refuse/tensor_map_reduce_view_codegen`).
                    Inst::TensorMap { .. }
                    | Inst::TensorReduce { .. }
                    | Inst::TensorView { .. } => {
                        let (inst, what) = match &node.inst {
                            Inst::TensorMap { .. } => ("TensorMap", "a tensor map"),
                            Inst::TensorReduce { .. } => ("TensorReduce", "a tensor reduction"),
                            _ => ("TensorView", "a tensor view"),
                        };
                        errors.push(ValidationError::UnlowerableForCodegen {
                            function: func.id.index(),
                            name: func.name.clone(),
                            block: block.id.index(),
                            inst,
                            detail: format!(
                                "{what} has no machine lowering yet (PKG-U13: outside the \
                                 lowering-target subset)"
                            ),
                        });
                    }
                    // Its gather and scatter (PKG-U13d): no machine lowering
                    // either (`refuse/tensor_gather_scatter_codegen`).
                    Inst::TensorGather { .. } | Inst::TensorScatter { .. } => {
                        let (inst, what) = match &node.inst {
                            Inst::TensorGather { .. } => ("TensorGather", "a tensor gather"),
                            _ => ("TensorScatter", "a tensor scatter"),
                        };
                        errors.push(ValidationError::UnlowerableForCodegen {
                            function: func.id.index(),
                            name: func.name.clone(),
                            block: block.id.index(),
                            inst,
                            detail: format!(
                                "{what} has no machine lowering yet (PKG-U13: outside the \
                                 lowering-target subset)"
                            ),
                        });
                    }
                    // Its content-addressed weights (PKG-U13e): no machine
                    // lowering either (`refuse/tensor_blob_codegen`).
                    Inst::Const { value, .. } if constant_names_a_tensor_blob(value) => {
                        errors.push(ValidationError::UnlowerableForCodegen {
                            function: func.id.index(),
                            name: func.name.clone(),
                            block: block.id.index(),
                            inst: "Const",
                            detail: "a content-addressed weight blob (`tensor_blob`) has no \
                                     machine lowering yet (PKG-U13: outside the lowering-target \
                                     subset)"
                                .to_string(),
                        });
                    }
                    _ => {}
                }
            }
        }
    }
    errors
}

/// `"Drop"` / `"DropInvoke"`: the `UnlowerableForCodegen.inst` spelling of a
/// drop site (the variant name, as for the other codegen refusals).
fn instruction_shape_name(inst: &Inst) -> &'static str {
    inst.shape().name()
}

/// The dialect namespaces this format decodes in-tree
/// ([`validate_dialect_op`] routes each to its own `decode`). WS2.20: a
/// `DialectOp` outside this closed list round-trips opaquely and is WELL-FORMED
/// (`validate_module` accepts it — Clean's Dialect debug mode emits such
/// namespaces), but it has no registered lowering, so the codegen entry point
/// refuses it by name rather than leaving a backend to fail late.
fn is_in_tree_dialect_namespace(namespace: &str) -> bool {
    use trust_ir::dialect::{ane, avx512, gpu, trust_rust, vector};
    [
        vector::DIALECT,
        gpu::DIALECT,
        avx512::DIALECT,
        ane::DIALECT,
        trust_rust::DIALECT,
    ]
    .contains(&namespace)
}

/// The v41 codegen-license layer ALONE, with no structural validation.
///
/// [`validate_module_for_codegen`] is `validate_module` + this. It is public
/// separately so a consumer that already validated through a different entry
/// point — [`validate_module_with_authority`], say, which is the one that can
/// admit a `Discharged` obligation — can add the license refusal without
/// running the whole module pass twice. Never use it as the only check: an
/// unlicensed body is a refusal, but a licensed body is not thereby well-formed.
///
/// Concretely, one case it deliberately leaves to the structural pass: a
/// `Gated` whose `authority` is blank names no gate at all. That is
/// [`ValidationError::InvalidBodyGate`], reported by `validate_module` — this
/// layer would let it through, and re-reporting it here would put two errors on
/// one defect. `validate_module_for_codegen` catches it because it runs both.
///
/// # The admission table is a proved contract
///
/// Whether a body is admitted at all (a `Gated` body to the rules below, an
/// unlicensed one to codegen under [`UnlicensedBodyPolicy::Permit`]) is
/// `trust_ir_laws::license_admits_body`, every cell of whose table is a Trust
/// contract re-checked by the Clean kernel under the `verified-contracts`
/// gate. What that lane does NOT prove — an enum-valued table is unprovable
/// there — is that the two refusals are DIFFERENT error values; that stays a
/// tested claim (the doctest on [`validate_module_for_codegen`]).
///
/// # The license is bound to evidence (roadmap WS1.5, F-006)
///
/// Per function WITH A BODY and a `Gated { authority }` license:
///
/// 1. **Revocation, for every `Gated` body.** A `Failed`
///    `TranslationValidation`, `Postcondition` or `Precondition` obligation
///    scoped to the function is [`ValidationError::GatedFunctionRefuted`] (one
///    per refuting row). A body with no refutation but two or more
///    `TranslationValidation` rows scoped to it is
///    [`ValidationError::GatedWithoutEvidence`] (`ambiguous: …`). "Scoped to
///    the function" means the obligation's `function` scope or, for a row
///    with no scope, the function its `site` names — a site-only row is a
///    claim about that body too.
/// 2. **Evidence.** If `authority` is in [`EVIDENCE_BOUND_GATE_AUTHORITIES`],
///    the module must carry what its [`GateEvidenceRule`] names, or the body
///    is [`ValidationError::GatedWithoutEvidence`]. An authority outside the
///    table keeps its pre-WS1.5 standing here: recognition is the consumer's
///    decision ([`validate_module_for_codegen_with`]).
///
/// Rule 2 needs the kernel-tier certificates THIS module's validation pass
/// replayed, so this bare form re-runs the certified-evidence pass when (and
/// only when) some body claims an evidence-bound authority. A caller that
/// already holds a [`ModuleValidationReport`] for the module uses
/// [`codegen_license_errors_with`] instead, which reuses that pass's set.
#[must_use]
pub fn codegen_license_errors(module: &Module) -> Vec<ValidationError> {
    let needs_replay = module.functions.iter().any(|func| {
        !func.is_declaration()
            && matches!(
                &func.body_gate,
                Some(trust_ir::BodyGate::Gated { authority, .. })
                    if gate_evidence_rule(authority).is_some()
            )
    });
    let replayed = if needs_replay {
        let function_catalog = ModuleFunctionCatalog::new(module);
        let certified_errors = validate_certified_evidence_with_catalog(module, &function_catalog);
        // Kernel tier only (`.0`): a capability-replayed `Discharged` row is
        // never license evidence.
        validated_authority_refs(
            module,
            &certified_errors,
            &trust_ir::proof::RejectingModuleProofAuthority,
        )
        .0
    } else {
        BTreeSet::new()
    };
    license_errors_against(module, &replayed, None, UnlicensedBodyPolicy::Refuse)
}

/// [`codegen_license_errors`] for the module `report` validated, against the
/// kernel-tier certificate set THAT pass replayed — so a module is never
/// kernel-rechecked twice. The set is read whatever the report's verdict: a
/// report with other errors is a refusal anyway, and the all-or-nothing rule
/// already empties the set when any `Certified` evidence failed its recheck.
///
/// Policy-free, exactly like [`codegen_license_errors`]: no recognized set,
/// unlicensed bodies refused.
#[must_use]
pub fn codegen_license_errors_with(report: &ModuleValidationReport<'_>) -> Vec<ValidationError> {
    license_errors_against(
        report.module,
        &report.replayed_certificates,
        None,
        UnlicensedBodyPolicy::Refuse,
    )
}

/// The license layer against an explicit kernel-tier replayed set and a
/// consumer policy. See [`codegen_license_errors`] for the rules.
fn license_errors_against(
    module: &Module,
    replayed: &BTreeSet<trust_ir::proof::ProofCertificateRef>,
    recognized: Option<&BTreeSet<String>>,
    unlicensed: UnlicensedBodyPolicy,
) -> Vec<ValidationError> {
    let mut errors = Vec::new();
    for func in &module.functions {
        // A declaration produces no code, so it needs no license. Note this is
        // `is_declaration()` (blocks empty, linkage-agnostic), NOT
        // `is_bodyless_external_declaration` — a contract-only declaration with
        // Internal linkage is equally not a codegen subject.
        if func.is_declaration() {
            continue;
        }
        // Admission is the PROVED table `trust_ir_laws::license_admits_body`
        // (kernel-rechecked laws, gate `verified-contracts`); this layer only
        // maps a refusal to its error variant — the two refusals are different
        // VALUES, which is the tested half (the doctest on
        // `validate_module_for_codegen`, `g3_codegen_license.rs`).
        let shape = GateShape::of(func.body_gate.as_ref());
        if !license_admits_body(shape, unlicensed) {
            errors.push(match shape {
                GateShape::Ungated => ValidationError::UngatedBodyForCodegen {
                    function: func.id.index(),
                    name: func.name.clone(),
                },
                GateShape::Absent => ValidationError::UnlicensedBodyForCodegen {
                    function: func.id.index(),
                    name: func.name.clone(),
                },
                // `laws::license_gated_admitted_under_any_policy` — proved for
                // every policy value, so this arm has no input.
                GateShape::Gated => {
                    unreachable!("license_admits_body(Gated, _) is a proved law (trust-ir-laws)")
                }
            });
            continue;
        }
        if let Some(trust_ir::BodyGate::Gated { authority, .. }) = &func.body_gate {
            errors.extend(gated_body_license_errors(module, func, authority, replayed));
            if recognized.is_some_and(|set| !set.contains(authority)) {
                errors.push(ValidationError::UnrecognizedGateAuthority {
                    function: func.id.index(),
                    authority: authority.clone(),
                });
            }
        }
    }
    errors
}

/// Revocation (every `Gated` body) and evidence (evidence-bound authorities)
/// for one bodied, `Gated` function.
fn gated_body_license_errors(
    module: &Module,
    func: &trust_ir::Function,
    authority: &str,
    replayed: &BTreeSet<trust_ir::proof::ProofCertificateRef>,
) -> Vec<ValidationError> {
    use trust_ir::proof::{ObligationKind, ProofStatus};
    let function = func.id.index();
    // "Scoped to F" = the obligation's function scope, or — for a row with no
    // scope — the function its v34 `site` names. `validate_module` accepts a
    // site-only row (it refuses only a scope that CONTRADICTS the site), and
    // such a row is a claim about `F`'s body all the same: reading `function`
    // alone let a site-only `Failed` refutation, or a site-only second TV
    // row, sit beside a license without revoking it.
    let scoped = || {
        module.proof_obligations.iter().filter(move |obligation| {
            obligation
                .function
                .or(obligation.site.as_ref().map(|site| site.function))
                == Some(func.id)
        })
    };

    // Rule 3a: an in-module refutation revokes the license, whatever the
    // authority. It is the reason; the evidence check below is not reached.
    let refutations: Vec<ValidationError> = scoped()
        .filter(|obligation| obligation.status == ProofStatus::Failed)
        .filter(|obligation| {
            matches!(
                obligation.kind,
                ObligationKind::TranslationValidation
                    | ObligationKind::Postcondition
                    | ObligationKind::Precondition
            )
        })
        .map(|obligation| ValidationError::GatedFunctionRefuted {
            function,
            obligation: obligation.id.index(),
        })
        .collect();
    if !refutations.is_empty() {
        return refutations;
    }

    let without_evidence = |detail: String| ValidationError::GatedWithoutEvidence {
        function,
        authority: authority.to_string(),
        detail,
    };

    // Rule 3b: two TranslationValidation rows say two things about one body.
    let tv_rows: Vec<&trust_ir::proof::ProofObligation> = scoped()
        .filter(|obligation| obligation.kind == ObligationKind::TranslationValidation)
        .collect();
    if tv_rows.len() > 1 {
        let ids: Vec<u32> = tv_rows.iter().map(|o| o.id.index()).collect();
        return vec![without_evidence(format!(
            "ambiguous: {} TranslationValidation rows are scoped to this function \
             (obligations {ids:?}); a license cites exactly one",
            tv_rows.len()
        ))];
    }

    // Rule 2: the evidence an evidence-bound authority names.
    match gate_evidence_rule(authority) {
        None => Vec::new(),
        Some(GateEvidenceRule::KernelTranslationValidation) => {
            match kernel_tv_license_evidence(module, tv_rows.first().copied(), replayed) {
                Ok(()) => Vec::new(),
                Err(detail) => vec![without_evidence(detail)],
            }
        }
    }
}

/// [`GateEvidenceRule::KernelTranslationValidation`] for one function, given
/// its (at most one) scoped `TranslationValidation` row.
fn kernel_tv_license_evidence(
    module: &Module,
    row: Option<&trust_ir::proof::ProofObligation>,
    replayed: &BTreeSet<trust_ir::proof::ProofCertificateRef>,
) -> Result<(), String> {
    use trust_ir::proof::KERNEL_ANCHOR_CLEAN_BACKEND_TV;
    let Some(obligation) = row else {
        return Err(
            "no TranslationValidation obligation is scoped to this function; the \
             `clean-kernel-tv` license names a kernel-rechecked clean_backend_tv \
             certificate and the module carries none for this body"
                .to_string(),
        );
    };
    let id = obligation.id.index();
    if !obligation.status.is_kernel_tier() {
        return Err(format!(
            "its TranslationValidation obligation {id} is `{}`, not `certified`",
            obligation.status
        ));
    }
    let mut anchored = false;
    for certificate in &module.proof_certificates {
        if certificate.obligation != obligation.id {
            continue;
        }
        let cites_tv_anchor =
            certificate
                .evidence
                .clean_cic_kernel_recheck()
                .is_some_and(|recheck| {
                    recheck.anchor == KERNEL_ANCHOR_CLEAN_BACKEND_TV
                        || trust_ir::proof::is_clean_source_call_anchor(&recheck.anchor)
                });
        if !cites_tv_anchor {
            continue;
        }
        anchored = true;
        if replayed.contains(&certificate.lineage_ref()) {
            return Ok(());
        }
    }
    if anchored {
        Err(format!(
            "the clean_backend_tv certificate of TranslationValidation obligation {id} \
             was not kernel-replayed in this validation pass (its recheck against the \
             current body failed, or another Certified row failed and emptied the kernel \
             tier)"
        ))
    } else {
        Err(format!(
            "TranslationValidation obligation {id} carries no CleanCic certificate under \
             the clean_backend_tv kernel anchor"
        ))
    }
}

/// Full structural validation plus exact closed dialect schemas. Operand
/// checks reuse the validator's actual per-function SSA type map, including
/// call results and block parameters; no producer type lookup is trusted and
/// no second module walk/type index is introduced.
///
/// Unlike ordinary opaque dialect round-tripping, every dialect instruction
/// must belong to this registry. This establishes well-formedness only, not
/// source semantics, effect contracts, or legalization correctness. Proof
/// admission uses the same rejecting capability as [`validate_module`].
pub fn validate_module_with_dialect_schemas(
    module: &Module,
    schemas: &trust_ir::dialect::schema::DialectSchemaRegistry,
) -> Vec<ValidationError> {
    validate_module_with_config(
        module,
        &ValidationConfig::pinned().with_dialect_schemas(schemas),
    )
    .into_errors()
}

/// Validate `module`, supplying a capability that may turn a `Discharged` row's
/// certificate into proof authority by re-establishing its claim in this
/// process.
///
/// # Why a separate entry point
///
/// [`validate_module`] and [`validate_module_report`] are structural: they
/// supply [`trust_ir::proof::RejectingModuleProofAuthority`], so a `Discharged`
/// obligation with no kernel-`Certified` backing is reported as
/// [`ValidationError::DischargedWithoutCertificate`] — the format build cannot
/// run a solver or a kernel and must not pretend otherwise. A consumer that CAN
/// replay (the ay adapter's `BvBlastAuthority`, a Clean-kernel-backed host)
/// passes it here.
///
/// # Authority is one currency
///
/// The refs this widens do not only unlock the `Discharged` admission check.
/// They are the SAME set consulted by `validate_proof_contexts` (a
/// `ProofContext::assumes` entry), `validate_inherited_proofs_with_authority`
/// (grounding an `InheritedFromCallee` chain), `validate_proof_refs_with_authority`
/// (a `ProofAnnotation::ProofRef` backing an on-node claim), and lineage
/// closure. A capability that admits a certificate admits it everywhere, which
/// is why the ay-side kind allowlist is deliberately narrow.
///
/// The all-or-nothing rule is preserved verbatim: if any `Certified` evidence in
/// the module fails its own recheck, the authority set is empty and this
/// capability is never consulted.
///
/// # Cross-crate rows are REFUSED here (v41 imports)
///
/// A capability that replays certificates still holds no dependency module,
/// so this entry point runs under the crate-private `ImportPolicy::Refuse`: every
/// proof-bearing import row — a `backed_by` naming an obligation on a `proved`
/// summary, and every `InheritedFromCallee { external: Some }` certificate —
/// is reported as [`ValidationError::UnauthenticatedImport`] rather than taken
/// on faith. This is a deliberate difference from [`validate_module`] (the
/// structural faith floor) and is the documented contract, not a regression:
/// a consumer holding the dependency modules authenticates them with
/// [`crate::validate_linked_module`], and
/// [`ModuleValidationReport::proof_bearing_imports`] lists what it must
/// supply. Import-free modules are unaffected.
///
/// This is [`validate_module_report_with_authority_and_registry`] under the
/// pinned handle-runtime registry.
pub fn validate_module_report_with_authority<'a>(
    module: &'a Module,
    authority: &dyn trust_ir::proof::ModuleProofAuthority,
) -> ModuleValidationReport<'a> {
    validate_module_report_with_authority_and_registry(module, authority, HandleRegistry::pinned())
}

/// [`validate_module_report_with_authority`] under an explicit handle-runtime
/// `registry` (roadmap WS1.5, the registry half of F-009). Everything else —
/// the `Refuse` import policy included — is that entry point verbatim.
///
/// A registry other than [`HandleRegistry::pinned`] is a caller-owned TCB
/// extension: every row it adds is an entry point the caller vouches for.
pub fn validate_module_report_with_authority_and_registry<'a>(
    module: &'a Module,
    authority: &dyn trust_ir::proof::ModuleProofAuthority,
    registry: &HandleRegistry,
) -> ModuleValidationReport<'a> {
    // `Refuse`: a capability that replays certificates still holds no
    // dependency module, so every proof-bearing cross-crate row is reported
    // as `UnauthenticatedImport` rather than taken on faith. Measured
    // 2026-09-15: no in-tree or sibling caller of this entry point passes a
    // module carrying such a row (trust-ir-ay bvblast, g3_codegen_license,
    // ty's `family_entry` all validate import-free modules).
    // `with_authority` selects exactly that `Refuse` policy.
    validate_module_with_config(
        module,
        &ValidationConfig::pinned()
            .with_authority(authority)
            .with_handle_registry(registry),
    )
}

/// [`validate_module_report_with_authority`], returning only the errors —
/// including its [`ValidationError::UnauthenticatedImport`] refusal of every
/// proof-bearing cross-crate row (see there; use
/// [`crate::validate_linked_module`] to authenticate them).
pub fn validate_module_with_authority(
    module: &Module,
    authority: &dyn trust_ir::proof::ModuleProofAuthority,
) -> Vec<ValidationError> {
    validate_module_report_with_authority(module, authority).into_errors()
}

// ───────────── T-SILICON COMPOSITION (P3 AUTHORITY NOT YET WIRED) ──────────
//
// Compose the two independently-landed, ck0-rechecked certificate families
// into ONE end-to-end source→silicon claim under a SINGLE kernel TCB:
//
//   * P2 (source → trust-ir): an `ObligationKind::TranslationValidation`
//     obligation on function `f`, `ProofEvidence::CleanCic` under
//     `KERNEL_ANCHOR_CLEAN_BACKEND_TV` — the emitted trust-ir fn is
//     kernel-proven to denote the source Clean decl (`mod clean_backend_tv`).
//   * P3 candidate (trust-ir → machine): one
//     `ObligationKind::TranslationValidation` obligation per lowering rule,
//     carrying CNF-refutation assurance under
//     `KERNEL_ANCHOR_TRUSTCG_LOWERING_RESOLUTION`.
//
// The intended composition theorem is:
//
//   source ≐ trust-ir   (P2, ck0)
//     ∧  trust-ir ≐ machine  for EVERY lowering rule f's compilation uses (P3, ck0)
//     ⇒ source ≐ machine,   all rechecked under the ONE ck0 kernel.
//
// It is intentionally UNAVAILABLE today: P3 replays a producer-selected CNF
// but does not independently derive that CNF from the exact lowering rule and
// Trust-IR machine semantics. `verify_source_to_silicon` therefore reports
// `LoweringSemanticBindingUnavailable` for those Pending assurance artifacts;
// it cannot construct `SourceToSiliconClaim` from them.
//
// ── Composition vehicle: DEDICATED check, REUSING lineage-closure for the
//    structural spine ────────────────────────────────────────────────────────
//
// Lineage-closure (`ProofLineageManifest::lineage_is_closed`) is NECESSARY but
// NOT SUFFICIENT here. It verifies the 2-rung chain is present, connected,
// acyclic, digest-matched at the handoff (rung1.source == rung0.target, via
// `validate_shape`'s `DependencyDigestMismatch`), and that NO rung is
// faith-stamped (`Trusted`) — a genuine half of the theorem. But a
// `ProofLineageNode` lists the certificates it HAS; it can never DECLARE the
// certs it MUST have. So the decisive gap — f's compilation uses `isub_i8` yet
// only the `iadd_i8` cert is present (a SILENT miscompile hole) — is invisible
// to lineage closure: the chain would still be "closed" over whatever certs it
// references. Detecting it requires deriving f's REQUIRED lowering-rule set from
// f's own body (domain knowledge), which is exactly what this dedicated check
// adds. Lineage-closure is reused underneath as the corroborating structural
// spine; the rule-coverage closure is the load-bearing core.

/// The end-to-end **source → silicon** claim intended to be certified under one
/// `ck0` kernel by [`verify_source_to_silicon`]. Its existence would witness:
/// (1) both cert
/// families kernel-re-checked to `Certified` under the single kernel, (2) the
/// P2 cert's function is the one whose lowering the P3 certs cover, (3) EVERY
/// lowering rule f's compilation uses has a covering P3 cert (chain closed — no
/// silent gap), and (4) the 2-rung composed lineage is closed (connected,
/// digest-matched handoff, no faith-stamped rung).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SourceToSiliconClaim {
    /// The function `f` the composed claim is about.
    pub function: FuncId,
    /// `f`'s name (auditable label).
    pub function_name: String,
    /// The P2 source→trust-ir translation-validation obligation on `f`.
    pub source_to_trust_ir: u32,
    /// The lowering rules `f`'s compilation uses, each paired with the P3
    /// trust-ir→machine obligation that certifies it. Covers `f` completely
    /// (`required-rules ⊆ covered-rules` — the chain-closure guarantee).
    pub lowering_certs: Vec<(String, u32)>,
    /// The 2-rung composed lineage (source→trust-ir ▸ trust-ir→machine), proven
    /// closed. Serializable as the composition artifact's sidecar manifest.
    pub lineage: trust_ir::proof::ProofLineageManifest,
}

struct ReplayedCertificateRefs<'a> {
    refs: &'a BTreeSet<trust_ir::proof::ProofCertificateRef>,
}

impl trust_ir::proof::ProofAuthorityRechecker for ReplayedCertificateRefs<'_> {
    fn replays_authority(
        &self,
        obligation: &trust_ir::proof::ProofObligation,
        certificate: &trust_ir::proof::ProofCertificate,
    ) -> bool {
        certificate.obligation == obligation.id && self.refs.contains(&certificate.lineage_ref())
    }
}

/// Check proof-lineage closure using only certificate identities whose exact
/// evidence this validator replayed successfully in-process.
///
/// The format-level [`trust_ir::lineage_closed`] entry point is deliberately
/// structural and therefore supplies a rejecting authority capability.  A
/// kernel-capable consumer must use this entry point (after
/// [`ProofLineageManifest::validate_against`](trust_ir::proof::ProofLineageManifest::validate_against))
/// to turn genuine, obligation-bound `CleanCic` certificates into lineage
/// authority. Opaque SMT/Lean/Kani payloads and public status labels never
/// enter the replayed set.
///
/// If any `Certified` evidence in the module fails its in-process recheck, the
/// authority set is empty. This intentionally prevents one malformed
/// certificate from being hidden behind a different apparently valid rung.
pub fn lineage_closed_with_validated_authority(
    module: &Module,
    manifest: &trust_ir::proof::ProofLineageManifest,
) -> Result<(), trust_ir::proof::LineageGap> {
    // This is one composite module operation: build the duplicate-aware
    // function index once, then share it across certificate replay and exact
    // semantic-endpoint reconstruction.
    let function_catalog = ModuleFunctionCatalog::new(module);
    let certified_errors = validate_certified_evidence_with_catalog(module, &function_catalog);
    // Lineage closure is a KERNEL-tier question: a rung must bottom out in a
    // kernel-rechecked certificate, never in a capability-replayed Discharged
    // row. Take `.0` only.
    let (refs, _discharged) = validated_authority_refs(
        module,
        &certified_errors,
        &trust_ir::proof::RejectingModuleProofAuthority,
    );
    let authority = ReplayedCertificateRefs { refs: &refs };
    manifest.lineage_is_closed_with_authority(
        &module.proof_obligations,
        &module.proof_certificates,
        &authority,
    )?;
    validate_lineage_semantic_bindings_with_catalog(module, &function_catalog, manifest, &refs)
}

/// Read only by the `clean-tv-anchor` lineage lanes.
#[cfg(feature = "clean-tv-anchor")]
fn lineage_bundle_digest(
    entries: &mut [(u32, String, Vec<u8>)],
) -> Result<trust_ir::proof::ProofDigest, String> {
    entries.sort_by(|left, right| (&left.0, &left.1).cmp(&(&right.0, &right.1)));
    let mut bytes = Vec::new();
    let entry_count = u64::try_from(entries.len())
        .map_err(|_| "lineage bundle has more than u64::MAX entries".to_string())?;
    bytes.extend_from_slice(&entry_count.to_le_bytes());
    for (function, name, semantics) in entries {
        bytes.extend_from_slice(&function.to_le_bytes());
        let name_len = u64::try_from(name.len())
            .map_err(|_| "lineage function name exceeds u64::MAX bytes".to_string())?;
        bytes.extend_from_slice(&name_len.to_le_bytes());
        bytes.extend_from_slice(name.as_bytes());
        let semantics_len = u64::try_from(semantics.len())
            .map_err(|_| "lineage semantics exceed u64::MAX bytes".to_string())?;
        bytes.extend_from_slice(&semantics_len.to_le_bytes());
        bytes.extend_from_slice(semantics);
    }
    Ok(trust_ir::proof::ProofDigest::sha256_domain(
        "trust_ir.proof.lineage.semantic_bundle.v1",
        &bytes,
    ))
}

fn lineage_gap(
    node: trust_ir::proof::ProofLineageId,
    reason: impl Into<String>,
) -> trust_ir::proof::LineageGap {
    trust_ir::proof::LineageGap::TrustedRung {
        node,
        justification: reason.into(),
    }
}

#[cfg(feature = "clean-tv-anchor")]
fn validate_lineage_semantic_bindings_with_catalog(
    module: &Module,
    function_catalog: &ModuleFunctionCatalog<'_>,
    manifest: &trust_ir::proof::ProofLineageManifest,
    authority: &BTreeSet<trust_ir::proof::ProofCertificateRef>,
) -> Result<(), trust_ir::proof::LineageGap> {
    use trust_ir::proof::{CleanCicKernelRecheck, KERNEL_ANCHOR_CLEAN_BACKEND_TV, ProofEvidence};

    let source_calls = source_bound_calls::lineage_semantic_carriers(module, function_catalog);
    for node in &manifest.nodes {
        let mut source_entries = Vec::new();
        let mut target_entries = Vec::new();
        let mut seen_functions = BTreeSet::new();
        for obligation_id in &node.obligations {
            let obligation = module
                .proof_obligations
                .iter()
                .find(|obligation| obligation.id == *obligation_id)
                .ok_or_else(|| {
                    lineage_gap(node.id, format!("missing obligation {obligation_id}"))
                })?;
            let matching: Vec<_> = node
                .certificates
                .iter()
                .filter(|certificate| certificate.obligation == *obligation_id)
                .collect();
            let [certificate_ref] = matching.as_slice() else {
                return Err(lineage_gap(
                    node.id,
                    format!(
                        "obligation {obligation_id} must have exactly one lineage certificate, got {}",
                        matching.len()
                    ),
                ));
            };
            if !authority.contains(*certificate_ref) {
                return Err(lineage_gap(
                    node.id,
                    format!("certificate for obligation {obligation_id} was not kernel-replayed"),
                ));
            }
            let certificate = module
                .proof_certificates
                .iter()
                .find(|certificate| certificate.lineage_ref() == **certificate_ref)
                .ok_or_else(|| {
                    lineage_gap(
                        node.id,
                        format!("missing exact certificate for obligation {obligation_id}"),
                    )
                })?;
            let ProofEvidence::CleanCic {
                kernel_recheck: Some(CleanCicKernelRecheck { anchor, .. }),
                ..
            } = &certificate.evidence
            else {
                return Err(lineage_gap(
                    node.id,
                    "lineage authority is not a payload-bound CleanCic translation validation",
                ));
            };
            if anchor != KERNEL_ANCHOR_CLEAN_BACKEND_TV
                && !trust_ir::proof::is_clean_source_call_anchor(anchor)
            {
                return Err(lineage_gap(
                    node.id,
                    format!(
                        "kernel anchor `{anchor}` has no exact lineage semantic-endpoint binding"
                    ),
                ));
            }
            let (function_name, source_bytes, target_bytes) =
                if trust_ir::proof::is_clean_source_call_anchor(anchor) {
                    match &source_calls {
                        Ok(carriers) => carriers
                            .get(&obligation.function.ok_or_else(|| {
                                lineage_gap(node.id, "source family lineage row has no function")
                            })?)
                            .cloned()
                            .ok_or_else(|| "source family lineage carrier missing".to_string()),
                        Err(reason) => Err(reason.clone()),
                    }
                } else {
                    clean_backend_tv::lineage_semantic_carriers(
                        module,
                        function_catalog,
                        obligation,
                        &certificate.evidence,
                    )
                    .and_then(|(name, source, target)| {
                        Ok((
                            name,
                            trust_ir::proof::encode_clean_expr_v1(&source)?,
                            trust_ir::proof::encode_clean_expr_v1(&target)?,
                        ))
                    })
                }
                .map_err(|reason| lineage_gap(node.id, reason))?;
            let function = obligation
                .function
                .expect("lineage_semantic_carriers requires an owning function")
                .index();
            if !seen_functions.insert(function) {
                return Err(lineage_gap(
                    node.id,
                    format!("multiple lineage obligations bind function #{function}"),
                ));
            }
            source_entries.push((function, function_name.clone(), source_bytes));
            target_entries.push((function, function_name, target_bytes));
        }
        let source = lineage_bundle_digest(&mut source_entries)
            .map_err(|reason| lineage_gap(node.id, reason))?;
        let target = lineage_bundle_digest(&mut target_entries)
            .map_err(|reason| lineage_gap(node.id, reason))?;
        if node.source_module != source {
            return Err(lineage_gap(
                node.id,
                format!(
                    "source semantics digest mismatch: node records {}, validator derived {source}",
                    node.source_module
                ),
            ));
        }
        if node.target_module != target {
            return Err(lineage_gap(
                node.id,
                format!(
                    "target semantics digest mismatch: node records {}, validator derived {target}",
                    node.target_module
                ),
            ));
        }
    }
    Ok(())
}

#[cfg(not(feature = "clean-tv-anchor"))]
fn validate_lineage_semantic_bindings_with_catalog(
    _module: &Module,
    _function_catalog: &ModuleFunctionCatalog<'_>,
    manifest: &trust_ir::proof::ProofLineageManifest,
    _authority: &BTreeSet<trust_ir::proof::ProofCertificateRef>,
) -> Result<(), trust_ir::proof::LineageGap> {
    let node = manifest
        .nodes
        .first()
        .map_or(trust_ir::proof::ProofLineageId::new(0), |node| node.id);
    Err(lineage_gap(
        node,
        "this build cannot rederive lineage semantic endpoints (clean-tv-anchor disabled)",
    ))
}

/// Mint a kernel-replayable identity rung for one in-fragment Trust-IR
/// function. This is the honest no-op/replay case: the source and target
/// semantic carriers are identical, their canonical bundle digests become the
/// node endpoints, and the Clean kernel checks `Eq.refl` for the exact
/// translation-validation obligation bound to `transform`.
#[cfg(feature = "clean-tv-anchor")]
pub fn certify_identity_lineage_rung(
    module: &Module,
    node_id: trust_ir::proof::ProofLineageId,
    obligation_id: trust_ir::value::ProofId,
    transform: trust_ir::proof::ProofTransform,
    function: FuncId,
) -> Result<
    (
        trust_ir::proof::ProofLineageNode,
        trust_ir::proof::ProofObligation,
        trust_ir::proof::ProofCertificate,
    ),
    String,
> {
    use trust_ir::proof::{
        CleanCicKernelRecheck, KERNEL_ANCHOR_CLEAN_BACKEND_TV, ObligationKind, ProofEvidence,
        ProofStatus, clean_cic_lineage_digest,
    };

    if transform.stage == trust_ir::proof::ProofTransformStage::Replay {
        return Err("identity rung helper does not accept Replay without a replay identity".into());
    }
    let function_catalog = ModuleFunctionCatalog::new(module);
    let function_ir = function_catalog
        .unique(function)
        .ok_or_else(|| format!("identity lineage function {function:?} is missing"))?;
    let denotation =
        clean_backend_tv::denote_function_with_catalog(module, &function_catalog, function_ir)?;
    clean_backend_tv::alloc_release_balance(function_ir)?;
    let closed = clean_backend_tv::closed_denotation(&denotation);
    let semantics = trust_ir::proof::encode_clean_expr_v1(&closed)
        .map_err(|reason| format!("encode identity lineage semantics: {reason}"))?;
    let mut entries = vec![(function.index(), function_ir.name.clone(), semantics)];
    let digest = lineage_bundle_digest(&mut entries)?;
    let mut node = trust_ir::proof::ProofLineageNode::new(node_id, transform, digest, digest);
    let obligation = trust_ir::proof::ProofObligation::new(
        obligation_id,
        ObligationKind::TranslationValidation,
        ProofStatus::Certified,
        "kernel-certified identity lineage transform",
    )
    .with_function(function)
    .with_formula(node.transform_binding_formula());
    let proof = clean_backend_tv::tv_proof_term(&denotation);
    let certificate = trust_ir::proof::ProofCertificate {
        obligation: obligation_id,
        prover: "trust-ir-build.identity-lineage".to_string(),
        evidence: ProofEvidence::CleanCic {
            term: trust_ir::proof::encode_clean_expr_v1(&proof)
                .map_err(|reason| format!("encode identity lineage proof: {reason}"))?,
            context: trust_ir::proof::encode_clean_expr_v1(&closed)
                .map_err(|reason| format!("encode identity lineage comparand: {reason}"))?,
            lineage: clean_cic_lineage_digest(&obligation),
            kernel_recheck: Some(CleanCicKernelRecheck {
                module: "CleanCompiler.BackendTV".to_string(),
                theorems: vec![clean_backend_tv::tv_theorem_name(&function_ir.name)],
                anchor: KERNEL_ANCHOR_CLEAN_BACKEND_TV.to_string(),
                allowed_axioms: vec![],
                binding: None,
            }),
        },

        assurance: None,
    };
    node.obligations.push(obligation_id);
    node.certificates.push(certificate.lineage_ref());
    Ok((node, obligation, certificate))
}

/// [`certify_identity_lineage_rung`], BOUND (roadmap WS1.12a): the same
/// kernel-replayable identity rung, whose certificate additionally carries a
/// [`trust_ir::proof::CertificateBinding`] and a symbol-keyed v8 lineage.
///
/// This is the reference for how a `clean_backend_tv` producer computes the
/// binding, spelled once beside the re-check that compares it:
///
/// * `environment_digest` — [`trust_ir::proof::kernel_environment_digest`]
///   of `clean_backend_tv::anchor_environment()`: the ground prelude WITH the
///   Fragment-4 heap vocabulary and the S3 signed carrier aliases installed
///   and BEFORE the theorem is declared (exactly what the re-check builds,
///   because it is the same function);
/// * `statement_digest` — [`trust_ir::proof::clean_cic_statement_digest`]
///   of `tv_statement(den, rhs)` over the re-derived SORTED telescope, so the
///   digest binds the carrier of every param, callee and result and not just
///   their arities;
/// * `callees` — the re-derived callee link symbols in canonical
///   (name-sorted) order;
/// * `origin_module = None`, `source = None`.
///
/// A module carrying this certificate is written at binary v61 or later
/// (`trust_ir::binary::CERTIFICATE_BINDING_FORMAT_VERSION`), which carries
/// the binding.
#[cfg(feature = "clean-tv-anchor")]
pub fn certify_identity_lineage_rung_bound(
    module: &Module,
    node_id: trust_ir::proof::ProofLineageId,
    obligation_id: trust_ir::value::ProofId,
    transform: trust_ir::proof::ProofTransform,
    function: FuncId,
) -> Result<
    (
        trust_ir::proof::ProofLineageNode,
        trust_ir::proof::ProofObligation,
        trust_ir::proof::ProofCertificate,
    ),
    String,
> {
    use trust_ir::proof::{
        CertificateBinding, ProofEvidence, clean_cic_lineage_digest_v8, clean_cic_statement_digest,
        kernel_environment_digest,
    };
    let (node, obligation, mut certificate) =
        certify_identity_lineage_rung(module, node_id, obligation_id, transform, function)?;
    let function_catalog = ModuleFunctionCatalog::new(module);
    let function_ir = function_catalog
        .unique(function)
        .ok_or_else(|| format!("identity lineage function {function:?} is missing"))?;
    let denotation =
        clean_backend_tv::denote_function_with_catalog(module, &function_catalog, function_ir)?;
    // The identity rung's comparand IS its own denotation, so the statement
    // the re-check will derive is `tv_statement(den, den.body)` — over the
    // WS1.15 SORTED telescope, which is what makes the digest carrier-aware.
    let statement = clean_backend_tv::tv_statement(&denotation, &denotation.body);
    let environment = clean_backend_tv::anchor_environment()?;
    let mut binding = CertificateBinding::new(
        kernel_environment_digest(&environment)?,
        clean_cic_statement_digest(&statement)?,
    );
    binding.callees = denotation
        .callees
        .iter()
        .map(|(name, _)| name.clone())
        .collect();
    let resolve = |id: FuncId| function_catalog.unique(id).map(|f| f.name.clone());
    let lineage = clean_cic_lineage_digest_v8(&obligation, &resolve, Some(&binding))
        .ok_or_else(|| "identity lineage obligation cannot be keyed by symbol".to_string())?;
    let ProofEvidence::CleanCic {
        lineage: slot,
        kernel_recheck: Some(recheck),
        ..
    } = &mut certificate.evidence
    else {
        return Err("identity rung minted non-CleanCic evidence".to_string());
    };
    *slot = lineage;
    recheck.binding = Some(Box::new(binding));
    Ok((node, obligation, certificate))
}

/// [`certify_identity_lineage_rung_bound`], SOURCE-BOUND (roadmap WS1.13,
/// the check half of finding F-008): the bound identity rung whose binding
/// also carries `island` and names `source.decl` as the island declaration
/// the comparand IS. The re-check installs the island into the anchor
/// environment (every declaration kernel-checked) and requires the comparand
/// to be definitionally equal to the value of `source.decl` there.
///
/// This is the reference for a source-binding producer (Clean's
/// `emit_trust_ir_tv`, roadmap WS6.7): the environment digest is taken AFTER
/// the island is installed (the environment the equation is judged in), and
/// the same source check the validator runs is run here first, so a function
/// whose emitted denotation is not the declaration's value is refused at
/// mint time rather than minted and refused later. This API keeps its slice-1
/// contract: `function` must have no callees. A complete acyclic family of
/// defined callees uses the distinct [`certify_source_bound_call_family`].
#[cfg(feature = "clean-tv-anchor")]
pub fn certify_identity_lineage_rung_island_bound(
    module: &Module,
    node_id: trust_ir::proof::ProofLineageId,
    obligation_id: trust_ir::value::ProofId,
    transform: trust_ir::proof::ProofTransform,
    function: FuncId,
    island: &trust_ir::proof::IslandEnvironment,
    source: trust_ir::proof::SourceDefinitionRef,
) -> Result<
    (
        trust_ir::proof::ProofLineageNode,
        trust_ir::proof::ProofObligation,
        trust_ir::proof::ProofCertificate,
    ),
    String,
> {
    use trust_ir::proof::{
        CertificateBinding, ProofEvidence, clean_cic_lineage_digest_v8, clean_cic_statement_digest,
        kernel_environment_digest,
    };
    let (node, obligation, mut certificate) =
        certify_identity_lineage_rung(module, node_id, obligation_id, transform, function)?;
    let function_catalog = ModuleFunctionCatalog::new(module);
    let function_ir = function_catalog
        .unique(function)
        .ok_or_else(|| format!("identity lineage function {function:?} is missing"))?;
    let denotation =
        clean_backend_tv::denote_function_with_catalog(module, &function_catalog, function_ir)?;
    if !denotation.callees.is_empty() {
        return Err(format!(
            "an island-bound TV certificate over a function with callees is slice 2: `{}` calls \
             {:?}",
            function_ir.name,
            denotation
                .callees
                .iter()
                .map(|(name, _)| name)
                .collect::<Vec<_>>()
        ));
    }
    let statement = clean_backend_tv::tv_statement(&denotation, &denotation.body);
    let mut environment = clean_backend_tv::anchor_environment()?;
    let names = clean_island::install(&mut environment, island)?;
    clean_island::refuse_island_name(
        &names,
        &clean_backend_tv::tv_theorem_name(&function_ir.name),
    )?;
    let comparand = clean_backend_tv::closed_denotation(&denotation);
    clean_island::check_comparand_is_source(&environment, &names, &source.decl, &comparand)?;
    let mut binding = CertificateBinding::new(
        kernel_environment_digest(&environment)?,
        clean_cic_statement_digest(&statement)?,
    );
    binding.source = Some(source);
    binding.environment = Some(island.clone());
    let resolve = |id: FuncId| function_catalog.unique(id).map(|f| f.name.clone());
    let lineage = clean_cic_lineage_digest_v8(&obligation, &resolve, Some(&binding))
        .ok_or_else(|| "identity lineage obligation cannot be keyed by symbol".to_string())?;
    let ProofEvidence::CleanCic {
        lineage: slot,
        kernel_recheck: Some(recheck),
        ..
    } = &mut certificate.evidence
    else {
        return Err("identity rung minted non-CleanCic evidence".to_string());
    };
    *slot = lineage;
    recheck.binding = Some(Box::new(binding));
    Ok((node, obligation, certificate))
}

#[cfg(not(feature = "clean-tv-anchor"))]
pub fn certify_identity_lineage_rung_island_bound(
    _module: &Module,
    _node_id: trust_ir::proof::ProofLineageId,
    _obligation_id: trust_ir::value::ProofId,
    _transform: trust_ir::proof::ProofTransform,
    _function: FuncId,
    _island: &trust_ir::proof::IslandEnvironment,
    _source: trust_ir::proof::SourceDefinitionRef,
) -> Result<
    (
        trust_ir::proof::ProofLineageNode,
        trust_ir::proof::ProofObligation,
        trust_ir::proof::ProofCertificate,
    ),
    String,
> {
    Err("identity lineage certification requires the clean-tv-anchor feature".to_string())
}

/// Mint a `lean.theorem` row and its `clean_island` certificate (roadmap
/// WS1.13, finding F-012): `theorem` is an island theorem whose statement
/// `formula` states in the slice-1 grammar
/// (`trust_ir::clean_expr_lowering::island`).
///
/// The certificate's `term` is the reference to the island theorem, its
/// `context` is empty (the statement is DERIVED from `formula`, never
/// carried), and its binding names the environment digest (the anchor
/// environment with the island installed), the statement digest (of the
/// grounded goal) and the island itself; the lineage is v8. The minter runs
/// the validator's own island re-check on what it minted before returning,
/// so an island whose theorem does not state `formula` is refused here.
///
/// What it cannot check alone is the SYMBOL BRIDGE: every island constant the
/// statement cites must also be the source declaration of a function whose
/// `clean_backend_tv` certificate is bound to the same island
/// ([`certify_identity_lineage_rung_island_bound`]); `validate_module`
/// checks that over the whole module.
#[cfg(feature = "clean-tv-anchor")]
pub fn certify_island_theorem(
    obligation_id: trust_ir::value::ProofId,
    theorem: &str,
    formula: trust_ir::proof::ProofFormula,
    island: &trust_ir::proof::IslandEnvironment,
) -> Result<
    (
        trust_ir::proof::ProofObligation,
        trust_ir::proof::ProofCertificate,
    ),
    String,
> {
    use trust_ir::clean_expr_lowering::island::island_statement_goal;
    use trust_ir::proof::{
        CertificateBinding, CleanCicKernelRecheck, KERNEL_ANCHOR_CLEAN_ISLAND,
        KERNEL_ANCHOR_CLEAN_ISLAND_MODULE, LEAN_THEOREM_OBLIGATION_NAMESPACE, ObligationKind,
        ProofCertificate, ProofEvidence, ProofObligation, ProofStatus, clean_cic_lineage_digest_v8,
        clean_cic_statement_digest, encode_clean_expr_v1, kernel_environment_digest,
    };
    let obligation = ProofObligation::new(
        obligation_id,
        ObligationKind::Custom {
            namespace: LEAN_THEOREM_OBLIGATION_NAMESPACE.to_string(),
            name: theorem.to_string(),
        },
        ProofStatus::Certified,
        format!("Lean theorem {theorem}"),
    )
    .with_formula(formula);
    let mut environment = clean_backend_tv::anchor_environment()?;
    let names = clean_island::install(&mut environment, island)?;
    let statement = island_statement_goal(&obligation, &environment, &names)
        .map_err(|error| error.to_string())?;
    let mut binding = CertificateBinding::new(
        kernel_environment_digest(&environment)?,
        clean_cic_statement_digest(&statement.goal)?,
    );
    binding.environment = Some(island.clone());
    let lineage = clean_cic_lineage_digest_v8(&obligation, &|_| None, Some(&binding))
        .ok_or_else(|| "a closed lean.theorem row is always keyable".to_string())?;
    let reference = names
        .iter()
        .find(|name| name.to_string() == theorem)
        .cloned()
        .ok_or_else(|| format!("the island does not declare `{theorem}`"))?;
    let term = encode_clean_expr_v1(&clean_kernel::Expr::const_(reference, vec![]))?;
    let directive = CleanCicKernelRecheck {
        module: KERNEL_ANCHOR_CLEAN_ISLAND_MODULE.to_string(),
        theorems: vec![theorem.to_string()],
        anchor: KERNEL_ANCHOR_CLEAN_ISLAND.to_string(),
        allowed_axioms: vec![],
        binding: Some(Box::new(binding)),
    };
    let certificate = ProofCertificate {
        obligation: obligation_id,
        prover: "clean-kernel.island".to_string(),
        evidence: ProofEvidence::CleanCic {
            term,
            context: Vec::new(),
            lineage,
            kernel_recheck: Some(directive.clone()),
        },
        assurance: None,
    };
    clean_island::recheck_theorem(&obligation, &certificate.evidence, &directive)?;
    Ok((obligation, certificate))
}

#[cfg(not(feature = "clean-tv-anchor"))]
