    #[test]
    fn contract_only_declaration_validates_and_arity_is_checked() {
        use trust_ir::{FunctionSummary, ProofFormula};
        let mut module = Module::new("prelude");
        // fn(i32) -> i32
        let ft = module
            .add_func_type(FuncTy {
                params: vec![Ty::I32],
                returns: vec![Ty::I32],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");

        // A well-formed contract-only declaration validates cleanly. It is a
        // bodyless External declaration — an FFI boundary — so the module must
        // pin a target (ABI pinning: TargetInfoRequired otherwise).
        module.target_info = Some(TargetInfo {
            triple: "aarch64-apple-darwin".into(),
            pointer_size: 8,
            endianness: Endianness::Little,
            abi: None,
            struct_passing: Default::default(),
        });
        // G5: `proved` is now CHECKED. A contract-only declaration holds no
        // body and therefore no local obligations, so the only thing that can
        // authenticate its `proved` bit is the v41 `backed_by` citation into a
        // declared import — which is exactly what that field was added to
        // spell. Before G5 this declaration asserted `proved` with nothing
        // behind it anywhere and still validated.
        module.imports.push(trust_ir::ModuleImport::new(
            "upstream",
            trust_ir::proof::ProofDigest::zero(),
        ));
        let good = FunctionSummary::new()
            .with_params(vec!["x".to_string()])
            .ensuring(ProofFormula::smtlib2("(> result 0)", "Bool"))
            .proved()
            .backed_by(
                trust_ir::ExternRef::new(trust_ir::value::ImportId::new(0), "ok")
                    .relying_on(trust_ir::value::ProofId::new(0)),
            );
        module
            .try_add_function(Function::declaration(FuncId::new(0), "ok", ft, good))
            .expect("Module::try_add_function: test fixture");
        assert!(
            validate_module(&module).is_empty(),
            "a well-formed contract-only declaration must validate: {:?}",
            validate_module(&module)
        );

        // audit F4: a body-less summary-bearing declaration with NON-External
        // linkage is still a valid declaration (no spurious EmptyFunction).
        let mut internal = Function::declaration(
            FuncId::new(3),
            "internal_contract",
            ft,
            FunctionSummary::new()
                .with_params(vec!["x".to_string()])
                .ensuring(ProofFormula::smtlib2("(> result 0)", "Bool")),
        );
        internal.linkage = Linkage::Internal;
        let mut m_internal = Module::new("internal_prelude");
        let ft2 = m_internal
            .add_func_type(FuncTy {
                params: vec![Ty::I32],
                returns: vec![Ty::I32],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        internal.ty = ft2;
        m_internal
            .try_add_function(internal)
            .expect("Module::try_add_function: test fixture");
        assert!(
            !validate_module(&m_internal)
                .iter()
                .any(|e| matches!(e, ValidationError::EmptyFunction)),
            "an Internal-linkage contract-only declaration must not be EmptyFunction: {:?}",
            validate_module(&m_internal)
        );

        // A param-arity mismatch is rejected.
        let bad = FunctionSummary::new()
            .with_params(vec!["x".to_string(), "y".to_string()]) // signature has 1 param
            .proved();
        module
            .try_add_function(Function::declaration(FuncId::new(1), "bad", ft, bad))
            .expect("Module::try_add_function: test fixture");
        let errors = validate_module(&module);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidFunctionSummary { function: 1, .. }
            )),
            "arity mismatch must be reported: {errors:?}"
        );

        // An empty clause schema is rejected.
        let mut empty_schema = FunctionSummary::new().with_params(vec!["x".to_string()]);
        empty_schema
            .ensures
            .push(ProofFormula::new("", "(> result 0)"));
        let mut m2 = Module::new("p2");
        let ft2 = m2
            .add_func_type(FuncTy {
                params: vec![Ty::I32],
                returns: vec![Ty::I32],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        m2.try_add_function(Function::declaration(
            FuncId::new(0),
            "es",
            ft2,
            empty_schema,
        ))
        .expect("Module::try_add_function: test fixture");
        assert!(
            validate_module(&m2)
                .iter()
                .any(|e| matches!(e, ValidationError::InvalidFunctionSummary { .. })),
            "empty clause schema must be reported"
        );

        // audit R2 #8: a clause-bearing summary with EMPTY params (but the signature
        // has params) is uninstantiable and must be flagged.
        let mut m3 = Module::new("p3");
        let ft3 = m3
            .add_func_type(FuncTy {
                params: vec![Ty::I32],
                returns: vec![Ty::I32],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let paramless = FunctionSummary::new() // no params, but carries a clause
            .ensuring(ProofFormula::smtlib2("(> result 0)", "Bool"))
            .proved();
        m3.try_add_function(Function::declaration(
            FuncId::new(0),
            "noparams",
            ft3,
            paramless,
        ))
        .expect("Module::try_add_function: test fixture");
        assert!(
            m3.func_types[0].params.len() == 1
                && validate_module(&m3)
                    .iter()
                    .any(|e| matches!(e, ValidationError::InvalidFunctionSummary { .. })),
            "a clause-bearing summary with empty params must be flagged: {:?}",
            validate_module(&m3)
        );
    }

