    #[test]
    fn many_blocks_some_invalid() {
        let mut func = Function::new(FuncId::new(0), "mixed", FuncTyId::new(0), BlockId::new(0));

        // bb0: valid (has br terminator)
        let mut b0 = Block::new(BlockId::new(0));
        b0.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(1),
            args: vec![],
        }));
        func.blocks.push(b0);

        // bb1: INVALID (no terminator, only a binop)
        let mut b1 = Block::new(BlockId::new(1));
        b1.params.push((ValueId::new(0), Ty::I32));
        b1.params.push((ValueId::new(1), Ty::I32));
        b1.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::I32,
                lhs: ValueId::new(0),
                rhs: ValueId::new(1),
            })
            .with_result(ValueId::new(2)),
        );
        func.blocks.push(b1);

        // bb2: valid (has return) - but unreachable
        let mut b2 = Block::new(BlockId::new(2));
        b2.body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(b2);

        // bb3: INVALID (empty, no instructions at all) - also unreachable
        func.blocks.push(Block::new(BlockId::new(3)));

        let errors = validate_function(&func);
        // Should find bb1 and bb3 missing terminators
        let missing: Vec<_> = errors
            .iter()
            .filter_map(|e| match e {
                ValidationError::BlockMissingTerminator(id) => Some(*id),
                _ => None,
            })
            .collect();
        assert_eq!(missing.len(), 2);
        assert!(missing.contains(&1));
        assert!(missing.contains(&3));
    }

    #[test]
    fn terminator_not_last_is_rejected() {
        // A `Return` at index 0 followed by a non-terminator BinOp: the block
        // does NOT end in a terminator. The old name ("..._still_valid") was
        // self-contradicting — this module is invalid. Assert BOTH the
        // mid-block-terminator placement error AND the end-of-block check.
        let mut func = Function::new(
            FuncId::new(0),
            "mid_term",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut block = Block::new(BlockId::new(0));
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        block.params.push((ValueId::new(0), Ty::I32));
        block.params.push((ValueId::new(1), Ty::I32));
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::I32,
                lhs: ValueId::new(0),
                rhs: ValueId::new(1),
            })
            .with_result(ValueId::new(2)),
        );
        func.blocks.push(block);

        let errors = validate_function(&func);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::MidBlockTerminator {
                    block: 0,
                    index: 0,
                    ..
                }
            )),
            "expected mid-block terminator error (Return at index 0 is not last): {errors:?}"
        );
        assert!(
            errors.contains(&ValidationError::BlockMissingTerminator(0)),
            "expected missing-terminator error when the last node is not a terminator: {errors:?}"
        );
    }

    #[test]
    fn multiple_duplicate_block_ids() {
        let mut func = Function::new(
            FuncId::new(0),
            "multi_dup",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        for _ in 0..3 {
            let mut block = Block::new(BlockId::new(0));
            block
                .body
                .push(InstrNode::new(Inst::Return { values: vec![] }));
            func.blocks.push(block);
        }

        let errors = validate_function(&func);
        let dup_count = errors
            .iter()
            .filter(|e| matches!(e, ValidationError::DuplicateBlockId(0)))
            .count();
        // First insert succeeds, second and third are duplicates
        assert_eq!(dup_count, 2);
    }

    #[test]
    fn validation_error_equality() {
        assert_eq!(
            ValidationError::EmptyFunction,
            ValidationError::EmptyFunction
        );
        assert_ne!(
            ValidationError::EmptyFunction,
            ValidationError::BlockMissingTerminator(0)
        );
        assert_eq!(
            ValidationError::BlockMissingTerminator(5),
            ValidationError::BlockMissingTerminator(5)
        );
        assert_ne!(
            ValidationError::BlockMissingTerminator(5),
            ValidationError::BlockMissingTerminator(6)
        );
    }

    // --- SSA Verification Tests ---

    fn invoke_ssa_fixture(pass_result: bool, unwind_use: bool) -> Function {
        let mut function = Function::new(
            FuncId::new(0),
            "invoke_ssa",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut entry = Block::new(BlockId::new(0));
        entry.body.push(
            InstrNode::new(Inst::Invoke {
                callee: FuncId::new(1),
                args: vec![],
                normal_dest: BlockId::new(1),
                normal_args: if pass_result {
                    vec![ValueId::new(0)]
                } else {
                    vec![]
                },
                unwind_dest: BlockId::new(2),
            })
            .with_result(ValueId::new(0)),
        );
        let mut normal = Block::new(BlockId::new(1));
        if pass_result {
            normal.params.push((ValueId::new(1), Ty::I32));
        }
        normal.body.push(InstrNode::new(Inst::Return {
            values: vec![ValueId::new(if pass_result { 1 } else { 0 })],
        }));
        let mut unwind = Block::new(BlockId::new(2));
        unwind.body.push(
            InstrNode::new(Inst::LandingPad {
                is_cleanup: true,
                catch_type_indices: vec![],
            })
            .with_result(ValueId::new(2))
            .with_result(ValueId::new(3)),
        );
        if unwind_use {
            unwind.body.push(
                InstrNode::new(Inst::Copy {
                    ty: Ty::I32,
                    operand: ValueId::new(0),
                })
                .with_result(ValueId::new(4)),
            );
        }
        unwind.body.push(InstrNode::new(Inst::Resume {
            exn: ValueId::new(2),
        }));
        function.blocks = vec![entry, normal, unwind];
        function
    }

    #[test]
    fn ssa_invoke_result_normal_edge_args_admitted() {
        let function = invoke_ssa_fixture(true, false);
        assert_eq!(
            validate_ssa(&function, &StaticFunctionPointerAnalysis::new(&function)),
            []
        );
    }

    #[test]
    fn ssa_invoke_result_rejected_on_unwind() {
        let function = invoke_ssa_fixture(false, true);
        assert_eq!(
            validate_ssa(&function, &StaticFunctionPointerAnalysis::new(&function)),
            [ValidationError::UseBeforeDefInBlock { value: 0, block: 2 }],
        );
    }

    #[test]
    fn ssa_fused_operand_walk_preserves_diagnostic_grouping() {
        let mut function = Function::new(
            FuncId::new(0),
            "ssa_diagnostic_order",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut block = Block::new(BlockId::new(0));
        block.body.push(
            InstrNode::new(Inst::Copy {
                ty: Ty::I32,
                operand: ValueId::new(99),
            })
            .with_result(ValueId::new(0)),
        );
        block.body.push(
            InstrNode::new(Inst::Copy {
                ty: Ty::I32,
                operand: ValueId::new(2),
            })
            .with_result(ValueId::new(1)),
        );
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(0),
            })
            .with_result(ValueId::new(2)),
        );
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(1),
            })
            .with_result(ValueId::new(0)),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        function.blocks.push(block);

        let analysis = StaticFunctionPointerAnalysis::new(&function);
        assert_eq!(
            validate_ssa(&function, &analysis),
            vec![
                ValidationError::DuplicateValueDef { value: 0, block: 0 },
                ValidationError::UseBeforeDef {
                    value: 99,
                    block: 0,
                },
                ValidationError::UseBeforeDefInBlock { value: 2, block: 0 },
            ]
        );
    }

