    #[test]
    fn type_check_integer_binop_with_float_type() {
        let mut func = Function::new(FuncId::new(0), "bad_add", FuncTyId::new(0), BlockId::new(0));
        let mut block = Block::new(BlockId::new(0));
        block.params.push((ValueId::new(0), Ty::F64));
        block.params.push((ValueId::new(1), Ty::F64));
        // Add requires integer, but we gave it F64
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::F64, // wrong: Add needs integer
                lhs: ValueId::new(0),
                rhs: ValueId::new(1),
            })
            .with_result(ValueId::new(2)),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);

        let errors = validate_function(&func);
        assert!(
            errors
                .iter()
                .any(|e| matches!(e, ValidationError::BinOpRequiresInteger { .. })),
            "expected integer-required error, got: {:?}",
            errors
        );
    }

    #[test]
    fn standalone_refined_binop_fails_closed_without_module_type_table() {
        let refined = Ty::Refine(TyId::new(0), PredId::new(0));
        let mut func = Function::new(
            FuncId::new(0),
            "standalone_refined_add",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut block = Block::new(BlockId::new(0));
        block.params.push((ValueId::new(0), refined.clone()));
        block.params.push((ValueId::new(1), refined.clone()));
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: refined,
                lhs: ValueId::new(0),
                rhs: ValueId::new(1),
            })
            .with_result(ValueId::new(2)),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);

        let errors = validate_function(&func);
        assert!(
            errors.iter().any(|error| matches!(
                error,
                ValidationError::RefinementTypeInvalid { detail, .. }
                    if detail.contains("no module type table")
            )),
            "standalone validation must fail closed, got: {errors:?}"
        );
    }

