    #[test]
    fn module_checks_refinement_on_every_instruction_type_surface() {
        let mut module = Module::new("instruction_refinement_surface");
        let func_ty = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let mut func = Function::new(
            FuncId::new(0),
            "dangling_refined_result",
            func_ty,
            BlockId::new(0),
        );
        let mut block = Block::new(BlockId::new(0));
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I8,
                value: Constant::Int(1),
            })
            .with_result(ValueId::new(0)),
        );
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::Refine(TyId::new(99), PredId::new(0)),
                lhs: ValueId::new(0),
                rhs: ValueId::new(0),
            })
            .with_result(ValueId::new(1)),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);
        module
            .try_add_function(func)
            .expect("Module::try_add_function: test fixture");

        let errors = validate_module(&module);
        assert!(
            errors.iter().any(|error| matches!(
                error,
                ValidationError::RefinementTypeInvalid { location, detail }
                    if location.contains("instruction 1")
                        && detail.contains("base ty.99 is out of range")
            )),
            "a dangling refinement on an unused non-Const result must fail: {errors:?}"
        );
    }

