    #[test]
    fn branch_target_not_found() {
        let mut func = Function::new(FuncId::new(0), "bad_br", FuncTyId::new(0), BlockId::new(0));
        let mut block = Block::new(BlockId::new(0));
        block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(99), // doesn't exist
            args: vec![],
        }));
        func.blocks.push(block);

        let errors = validate_function(&func);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::BranchTargetNotFound {
                    block: 0,
                    target: 99
                }
            )),
            "expected branch target not found error, got: {:?}",
            errors
        );
    }

    #[test]
    fn condbr_targets_not_found() {
        let mut func = Function::new(
            FuncId::new(0),
            "bad_condbr_targets",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut block = Block::new(BlockId::new(0));
        block.params.push((ValueId::new(0), Ty::Bool));
        block.body.push(InstrNode::new(Inst::CondBr {
            cond: ValueId::new(0),
            then_target: BlockId::new(77), // doesn't exist
            then_args: vec![],
            else_target: BlockId::new(88), // doesn't exist
            else_args: vec![],
        }));
        func.blocks.push(block);

        let errors = validate_function(&func);
        assert!(errors.iter().any(|e| matches!(
            e,
            ValidationError::BranchTargetNotFound {
                block: 0,
                target: 77
            }
        )));
        assert!(errors.iter().any(|e| matches!(
            e,
            ValidationError::BranchTargetNotFound {
                block: 0,
                target: 88
            }
        )));
    }

