    #[test]
    fn comprehensive_valid_function() {
        // A well-formed function with block params, binops, icmp, condbr, multiple blocks
        let mut func = Function::new(FuncId::new(0), "abs", FuncTyId::new(0), BlockId::new(0));

        // bb0(x: i32): icmp slt x, 0 -> condbr
        let mut b0 = Block::new(BlockId::new(0));
        b0.params.push((ValueId::new(0), Ty::I32));
        b0.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(0),
            })
            .with_result(ValueId::new(1)),
        );
        b0.body.push(
            InstrNode::new(Inst::ICmp {
                op: ICmpOp::Slt,
                ty: Ty::I32,
                lhs: ValueId::new(0),
                rhs: ValueId::new(1),
            })
            .with_result(ValueId::new(2)),
        );
        b0.body.push(InstrNode::new(Inst::CondBr {
            cond: ValueId::new(2),
            then_target: BlockId::new(1),
            then_args: vec![],
            else_target: BlockId::new(2),
            else_args: vec![],
        }));
        func.blocks.push(b0);

        // bb1: neg x -> br bb2
        let mut b1 = Block::new(BlockId::new(1));
        b1.body.push(
            InstrNode::new(Inst::UnOp {
                op: trust_ir::inst::UnOp::Neg,
                ty: Ty::I32,
                operand: ValueId::new(0),
            })
            .with_result(ValueId::new(3)),
        );
        b1.body.push(InstrNode::new(Inst::Return {
            values: vec![ValueId::new(3)],
        }));
        func.blocks.push(b1);

        // bb2: return x
        let mut b2 = Block::new(BlockId::new(2));
        b2.body.push(InstrNode::new(Inst::Return {
            values: vec![ValueId::new(0)],
        }));
        func.blocks.push(b2);

        let errors = validate_function(&func);
        assert!(errors.is_empty(), "expected no errors, got: {:?}", errors);
    }

    #[test]
    fn new_error_variant_display_formats() {
        // Test Display for all new error variants
        let err = ValidationError::DuplicateValueDef { value: 5, block: 2 };
        assert!(format!("{err}").contains("%5"));
        assert!(format!("{err}").contains("bb2"));

        let err = ValidationError::UseBeforeDef {
            value: 10,
            block: 0,
        };
        assert!(format!("{err}").contains("%10"));

        let err = ValidationError::BinOpRequiresInteger {
            block: 0,
            op: "add".to_string(),
            ty: "f64".to_string(),
        };
        assert!(format!("{err}").contains("add"));
        assert!(format!("{err}").contains("f64"));

        let err = ValidationError::BranchTargetNotFound {
            block: 1,
            target: 99,
        };
        assert!(format!("{err}").contains("bb99"));

        let err = ValidationError::UnreachableBlock(3);
        assert!(format!("{err}").contains("bb3"));
    }

