    #[test]
    fn valid_cast_variants() {
        // Test that valid cast combinations don't produce errors
        let cast_tests: Vec<(CastOp, Ty, Ty)> = vec![
            (CastOp::Trunc, Ty::I64, Ty::I32),
            (CastOp::Trunc, Ty::I8, Ty::Bool),
            (CastOp::ZExt, Ty::Bool, Ty::I8),
            (CastOp::ZExt, Ty::Bool, Ty::I64),
            (CastOp::SExt, Ty::Bool, Ty::I32),
            (CastOp::ZExt, Ty::I32, Ty::I64),
            (CastOp::SExt, Ty::I16, Ty::I64),
            (CastOp::FPTrunc, Ty::F32, Ty::F16),
            (CastOp::FPTrunc, Ty::F64, Ty::F32),
            (CastOp::FPExt, Ty::F16, Ty::F32),
            (CastOp::FPExt, Ty::F32, Ty::F64),
            (CastOp::FPToUI, Ty::F16, Ty::U16),
            (CastOp::FPToUI, Ty::F64, Ty::I32),
            (CastOp::FPToSI, Ty::F16, Ty::I16),
            (CastOp::FPToSI, Ty::F64, Ty::I64),
            (CastOp::UIToFP, Ty::U16, Ty::F16),
            (CastOp::UIToFP, Ty::I32, Ty::F64),
            (CastOp::SIToFP, Ty::I16, Ty::F16),
            (CastOp::SIToFP, Ty::I64, Ty::F32),
            (CastOp::PtrToInt, Ty::Ptr, Ty::I64),
            (CastOp::IntToPtr, Ty::I64, Ty::Ptr),
            (CastOp::Bitcast, Ty::I16, Ty::F16),
            (CastOp::Bitcast, Ty::I32, Ty::F32), // same bit width
        ];

        for (op, src, dst) in cast_tests {
            let mut func = Function::new(
                FuncId::new(0),
                "cast_test",
                FuncTyId::new(0),
                BlockId::new(0),
            );
            let mut block = Block::new(BlockId::new(0));
            block.params.push((ValueId::new(0), src.clone()));
            block.body.push(
                InstrNode::new(Inst::Cast {
                    op,
                    src_ty: src.clone(),
                    dst_ty: dst.clone(),
                    operand: ValueId::new(0),
                })
                .with_result(ValueId::new(1)),
            );
            block
                .body
                .push(InstrNode::new(Inst::Return { values: vec![] }));
            func.blocks.push(block);

            let errors = validate_function(&func);
            let cast_errors: Vec<_> = errors
                .iter()
                .filter(|e| matches!(e, ValidationError::CastIncompatible { .. }))
                .collect();
            assert!(
                cast_errors.is_empty(),
                "unexpected cast error for {op} {} -> {}: {:?}",
                src,
                dst,
                cast_errors
            );
        }
    }

