    /// WS3.19 review: the Rust half of the Lean container-tail lane fixtures
    /// (`ptr_metadata_container_len_rejects_ptr_decl_stable` and its twins in
    /// `Semantics/ExecutableFixtures.lean`). On a 64-bit target `ContainerLen`
    /// is on the `u64` length lane and `ContainerVtable` on the `ptr` vtable
    /// lane, for BOTH `PtrMetadata` and `PtrFromParts`; each lane-swapped
    /// spelling is refused as `PointerMetadataTypeMismatch` naming the exact
    /// expected / actual lanes, and so is the pointer-width-generic `usize`.
    #[test]
    fn container_tail_pointer_metadata_lanes_are_exact() {
        use trust_ir::FatPtrKind;

        fn module_for(ptr_ty: &Ty, metadata_ty: &Ty, from_parts: bool) -> Module {
            let mut module = Module::new("container_tail_meta");
            module.target_info = Some(TargetInfo {
                triple: "x86_64-unknown-linux-gnu".into(),
                pointer_size: 8,
                endianness: Endianness::Little,
                abi: None,
                struct_passing: Default::default(),
            });
            module
                .add_func_type(FuncTy {
                    params: vec![],
                    returns: vec![],
                    abi: None,
                    is_vararg: false,
                })
                .expect("Module::add_func_type: test fixture");
            let mut func = Function::new(
                FuncId::new(0),
                "container_tail_meta",
                FuncTyId::new(0),
                BlockId::new(0),
            );
            let mut block = Block::new(BlockId::new(0));
            let inst = if from_parts {
                block.params.push((ValueId::new(0), Ty::Ptr));
                block.params.push((ValueId::new(1), metadata_ty.clone()));
                Inst::PtrFromParts {
                    ptr_ty: ptr_ty.clone(),
                    metadata_ty: metadata_ty.clone(),
                    data: ValueId::new(0),
                    metadata: ValueId::new(1),
                }
            } else {
                block.params.push((ValueId::new(0), ptr_ty.clone()));
                block.params.push((ValueId::new(1), Ty::Unit));
                Inst::PtrMetadata {
                    ptr_ty: ptr_ty.clone(),
                    metadata_ty: metadata_ty.clone(),
                    ptr: ValueId::new(0),
                }
            };
            block
                .body
                .push(InstrNode::new(inst).with_result(ValueId::new(2)));
            block
                .body
                .push(InstrNode::new(Inst::Return { values: vec![] }));
            func.blocks.push(block);
            module
                .try_add_function(func)
                .expect("Module::try_add_function: test fixture");
            module
        }

        let clen = Ty::FatPtr(FatPtrKind::ContainerLen);
        let cvt = Ty::FatPtr(FatPtrKind::ContainerVtable);
        for from_parts in [false, true] {
            let op = if from_parts {
                "ptr_from_parts"
            } else {
                "ptr_metadata"
            };
            for (ptr_ty, good) in [(&clen, Ty::U64), (&cvt, Ty::Ptr)] {
                let errors = validate_module(&module_for(ptr_ty, &good, from_parts));
                assert!(
                    !errors
                        .iter()
                        .any(|e| matches!(e, ValidationError::PointerMetadataTypeMismatch { .. })),
                    "{op} {ptr_ty} on its own `{good}` lane must validate: {errors:?}"
                );
            }
            for (ptr_ty, bad, want_expected, want_actual) in [
                (&clen, Ty::Ptr, "u64", "ptr"),
                (&clen, Ty::Usize, "u64", "usize"),
                (&cvt, Ty::U64, "ptr", "u64"),
            ] {
                let errors = validate_module(&module_for(ptr_ty, &bad, from_parts));
                assert!(
                    errors.iter().any(|e| matches!(
                        e,
                        ValidationError::PointerMetadataTypeMismatch { op: o, expected, actual, .. }
                            if o == op && expected == want_expected && actual == want_actual
                    )),
                    "{op} {ptr_ty} declared `{bad}` must be refused as a {want_expected}/{want_actual} \
                     PointerMetadataTypeMismatch, got {errors:?}"
                );
            }
        }
    }

    #[test]
    fn multiple_validation_passes_report_all_errors() {
        // Function with errors from multiple passes simultaneously
        let mut func = Function::new(
            FuncId::new(0),
            "multi_pass_errors",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut block = Block::new(BlockId::new(0));
        block.params.push((ValueId::new(0), Ty::F64));
        block.params.push((ValueId::new(1), Ty::F64));
        // Type error: Add on floats
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::F64,
                lhs: ValueId::new(0),
                rhs: ValueId::new(1),
            })
            .with_result(ValueId::new(2)),
        );
        // SSA error: duplicate def of %2
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(0),
            })
            .with_result(ValueId::new(2)), // duplicate!
        );
        // Control flow error: bad branch target
        block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(99),
            args: vec![],
        }));
        func.blocks.push(block);

        let errors = validate_function(&func);
        // Should have at least: BinOpRequiresInteger, DuplicateValueDef, BranchTargetNotFound
        assert!(
            errors
                .iter()
                .any(|e| matches!(e, ValidationError::BinOpRequiresInteger { .. }))
        );
        assert!(
            errors
                .iter()
                .any(|e| matches!(e, ValidationError::DuplicateValueDef { .. }))
        );
        assert!(
            errors
                .iter()
                .any(|e| matches!(e, ValidationError::BranchTargetNotFound { .. }))
        );
    }

