    /// WS3 cross-producer diagnostics: when caller and callee carry v23
    /// producer tags, the call-signature mismatch errors carry and render
    /// both; an untagged side renders as `untagged`; a fully untagged edge
    /// keeps the exact historical message (no suffix) — pinned by the two
    /// tests above whose fixtures never tag anything.
    #[test]
    fn call_signature_mismatch_attributes_producers_when_tagged() {
        use trust_ir::Producer;

        let mut module = Module::new("call_type_producers");
        let callee_ty = module
            .add_func_type(FuncTy {
                params: vec![Ty::I64],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let caller_ty = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");

        let mut callee = Function::new(FuncId::new(1), "callee", callee_ty, BlockId::new(0));
        callee.producer = Some(Producer::Clean);
        let mut callee_block = Block::new(BlockId::new(0));
        callee_block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        callee.blocks.push(callee_block);
        module
            .try_add_function(callee)
            .expect("Module::try_add_function: test fixture");

        let mut caller = Function::new(FuncId::new(0), "caller", caller_ty, BlockId::new(0));
        caller.producer = Some(Producer::TRust);
        let mut caller_block = Block::new(BlockId::new(0));
        caller_block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(1),
            })
            .with_result(ValueId::new(0)),
        );
        caller_block.body.push(InstrNode::new(Inst::Call {
            callee: FuncId::new(1),
            args: vec![ValueId::new(0)], // I32 instead of I64
        }));
        caller_block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        caller.blocks.push(caller_block);
        module
            .try_add_function(caller)
            .expect("Module::try_add_function: test fixture");

        let expected = ValidationError::CallArgTypeMismatch {
            block: 0,
            callee: "callee".to_string(),
            arg_index: 0,
            expected: "i64".to_string(),
            actual: "i32".to_string(),
            caller_producer: Some("trust".to_string()),
            callee_producer: Some("clean".to_string()),
        };
        let errors = validate_module(&module);
        assert!(errors.contains(&expected), "got: {errors:?}");
        assert_eq!(
            expected.to_string(),
            "bb0: call to callee arg 0 type mismatch: expected i64, got i32 \
             (caller producer: trust, callee producer: clean)"
        );

        // One-sided tagging: the bare side renders as `untagged` (the suffix
        // appears as soon as EITHER side carries provenance).
        let one_sided = ValidationError::CallArgCountMismatch {
            block: 0,
            callee: "callee".to_string(),
            expected: 1,
            actual: 0,
            caller_producer: None,
            callee_producer: Some("clean".to_string()),
        };
        assert_eq!(
            one_sided.to_string(),
            "bb0: call to callee has 0 args, expected 1 \
             (caller producer: untagged, callee producer: clean)"
        );
    }

