    #[test]
    fn closure_returning_indirect_call_result_arity_mismatch_error() {
        let mut module = Module::new("closure_call_result_arity");
        let closure_body_ty = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let closure_id = module
            .add_closure_type(trust_ir::ty::ClosureTy {
                func: closure_body_ty,
                captures: vec![Ty::I32],
            })
            .expect("Module::add_closure_type: test fixture");
        let factory_sig = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![Ty::Closure(closure_id)],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let caller_ty = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");

        let mut caller = Function::new(FuncId::new(0), "caller", caller_ty, BlockId::new(0));
        let mut block = Block::new(BlockId::new(0));
        block.params.push((ValueId::new(0), Ty::Func(factory_sig)));
        block.body.push(
            InstrNode::new(Inst::CallIndirect {
                callee: ValueId::new(0),
                sig: factory_sig,
                args: vec![],

                calling_conv: trust_ir::CallingConv::C,
            })
            .with_results([ValueId::new(1), ValueId::new(2)]),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        caller.blocks.push(block);
        module
            .try_add_function(caller)
            .expect("Module::try_add_function: test fixture");

        let errors = validate_module(&module);
        assert!(errors.contains(&ValidationError::InstrResultArityMismatch {
            block: 0,
            op: "call_indirect".to_string(),
            expected: 1,
            actual: 2,
        }));
    }

