    #[test]
    fn tuple_struct_and_record_constants_are_recursively_checked() {
        let mut module = Module::new("aggregate_consts");
        let struct_id = module.add_struct(StructDef {
            id: StructId::new(0),
            name: "Pair".to_string(),
            fields: vec![
                FieldDef {
                    name: "byte".to_string(),
                    ty: Ty::U8,
                    offset: Some(0),
                },
                FieldDef {
                    name: "enabled".to_string(),
                    ty: Ty::Bool,
                    offset: Some(1),
                },
            ],
            size: Some(2),
            align: Some(1),

            repr: Default::default(),
            origin: None,
        });
        let record_id = module.add_record(RecordDef {
            id: RecordId::new(0),
            name: "LogicalPair".to_string(),
            fields: vec![
                FieldDef {
                    name: "byte".to_string(),
                    ty: Ty::U8,
                    offset: None,
                },
                FieldDef {
                    name: "enabled".to_string(),
                    ty: Ty::Bool,
                    offset: None,
                },
            ],
        });
        module.globals.push(trust_ir::Global {
            name: "GOOD_TUPLE".to_string(),
            ty: Ty::Tuple(vec![Ty::U8, Ty::Bool]),
            mutable: false,
            initializer: Some(Constant::Aggregate(vec![
                Constant::Int(42),
                Constant::Bool(true),
            ])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,

            section: None,
            visibility: Default::default(),
            retained: false,
        });
        module.globals.push(trust_ir::Global {
            name: "BAD_STRUCT".to_string(),
            ty: Ty::Struct(struct_id),
            mutable: false,
            initializer: Some(Constant::Aggregate(vec![
                Constant::Int(300),
                Constant::Bool(true),
            ])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,

            section: None,
            visibility: Default::default(),
            retained: false,
        });
        module.globals.push(trust_ir::Global {
            name: "BAD_RECORD".to_string(),
            ty: Ty::Record(record_id),
            mutable: false,
            initializer: Some(Constant::Record(vec![
                ("byte".to_string(), Constant::Int(7)),
                ("enabled".to_string(), Constant::Int(1)),
            ])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,

            section: None,
            visibility: Default::default(),
            retained: false,
        });

        let errors = validate_module(&module);
        assert!(
            !errors.iter().any(|e| {
                matches!(
                    e,
                    ValidationError::ConstTypeMismatch { location, .. }
                        if location.starts_with("global 'GOOD_TUPLE'")
                )
            }),
            "valid tuple aggregate should not be rejected, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'BAD_STRUCT'[0]"
                        && expected == "u8"
                        && actual == "int"
            )),
            "expected struct field range rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'BAD_RECORD'.enabled"
                        && expected == "bool"
                        && actual == "int"
            )),
            "expected record field type rejection, got {errors:?}"
        );
    }

    #[test]
