    #[test]
    fn vector_bool_mask_cannot_drive_control_or_proof_predicates() {
        let v4bool = Ty::Vector(Box::new(Ty::Bool), 4);
        let mut func = Function::new(
            FuncId::new(0),
            "bad_vector_predicates",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut b0 = Block::new(BlockId::new(0));
        b0.params.push((ValueId::new(0), v4bool));
        b0.body.push(InstrNode::new(Inst::Assume {
            cond: ValueId::new(0),
        }));
        b0.body.push(InstrNode::new(Inst::Assert {
            cond: ValueId::new(0),
            kind: trust_ir::AssertKind::Unspecified,
            site: None,
        }));
        b0.body.push(InstrNode::new(Inst::CondBr {
            cond: ValueId::new(0),
            then_target: BlockId::new(1),
            then_args: vec![],
            else_target: BlockId::new(2),
            else_args: vec![],
        }));
        func.blocks.push(b0);

        let mut b1 = Block::new(BlockId::new(1));
        b1.body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(b1);

        let mut b2 = Block::new(BlockId::new(2));
        b2.body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(b2);

        let errors = validate_function(&func);
        assert!(
            errors
                .iter()
                .any(|e| matches!(e, ValidationError::CondBrRequiresBool { cond_ty, .. } if cond_ty == "<4 x bool>")),
            "expected vector condbr rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::PredicateRequiresBool { op, cond_ty, .. }
                    if op == "assume" && cond_ty == "<4 x bool>"
            )),
            "expected vector assume rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::PredicateRequiresBool { op, cond_ty, .. }
                    if op == "assert" && cond_ty == "<4 x bool>"
            )),
            "expected vector assert rejection, got {errors:?}"
        );
    }

    #[test]
    fn vector_select_requires_lane_mask_and_rejects_mismatches() {
        let v4i32 = Ty::v4_i32();
        let v4bool = Ty::v4_bool();
        let v2bool = Ty::Vector(Box::new(Ty::Bool), 2);
        let mut func = Function::new(
            FuncId::new(0),
            "vector_select_masks",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut block = Block::new(BlockId::new(0));
        block.params.push((ValueId::new(0), v4bool));
        block.params.push((ValueId::new(1), v2bool));
        block.params.push((ValueId::new(2), Ty::Bool));
        block.params.push((ValueId::new(3), v4i32.clone()));
        block.params.push((ValueId::new(4), v4i32.clone()));
        block.params.push((ValueId::new(5), Ty::I32));

        block.body.push(
            InstrNode::new(Inst::Select {
                ty: v4i32.clone(),
                cond: ValueId::new(0),
                then_val: ValueId::new(3),
                else_val: ValueId::new(4),
            })
            .with_result(ValueId::new(6)),
        );
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: v4i32.clone(),
                cond: ValueId::new(2),
                then_val: ValueId::new(3),
                else_val: ValueId::new(4),
            })
            .with_result(ValueId::new(7)),
        );
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: v4i32.clone(),
                cond: ValueId::new(1),
                then_val: ValueId::new(3),
                else_val: ValueId::new(4),
            })
            .with_result(ValueId::new(8)),
        );
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: v4i32.clone(),
                cond: ValueId::new(0),
                then_val: ValueId::new(5),
                else_val: ValueId::new(4),
            })
            .with_result(ValueId::new(9)),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);

        let errors = validate_function(&func);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::SelectConditionTypeMismatch {
                    expected,
                    actual,
                    ..
                } if expected == "<4 x bool>" && actual == "bool"
            )),
            "expected scalar bool select condition rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::SelectConditionTypeMismatch {
                    expected,
                    actual,
                    ..
                } if expected == "<4 x bool>" && actual == "<2 x bool>"
            )),
            "expected lane-mask select condition rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::OperandTypeMismatch { op, expected, actual, .. }
                    if op == "select" && actual == "i32" && expected == "<4 x i32>"
            )),
            "expected select payload type rejection, got {errors:?}"
        );
        assert_eq!(
            errors
                .iter()
                .filter(|e| matches!(e, ValidationError::SelectConditionTypeMismatch { .. }))
                .count(),
            2,
            "only the scalar bool and wrong-lane mask should fail condition validation: {errors:?}"
        );
    }

