    #[test]
    fn vector_constant_kind_lane_count_and_element_shapes_must_match() {
        let mut valid = Module::new("good_vector_consts");
        let valid_func_ty = valid
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        valid.globals.push(trust_ir::Global {
            name: "ZEROS".to_string(),
            ty: Ty::Vector(Box::new(Ty::I32), 4),
            mutable: false,
            initializer: Some(Constant::zero_i32_vector(4)),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,

            section: None,
            visibility: Default::default(),
            retained: false,
        });
        let mut valid_func = Function::new(FuncId::new(0), "f", valid_func_ty, BlockId::new(0));
        let mut valid_block = Block::new(BlockId::new(0));
        valid_block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::Vector(Box::new(Ty::Bool), 4),
                value: Constant::vector_bool([true, false, true, false]),
            })
            .with_result(ValueId::new(0)),
        );
        valid_block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        valid_func.blocks.push(valid_block);
        valid
            .try_add_function(valid_func)
            .expect("Module::try_add_function: test fixture");
        assert!(
            validate_module(&valid).is_empty(),
            "canonical vector constants should validate"
        );

        let mut module = Module::new("bad_vector_consts");
        let func_ty = module
            .add_func_type(FuncTy {
                params: vec![],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        module.globals.push(trust_ir::Global {
            name: "MASK".to_string(),
            ty: Ty::Vector(Box::new(Ty::Bool), 2),
            mutable: false,
            initializer: Some(Constant::Vector(vec![
                Constant::Bool(true),
                Constant::Int(1),
            ])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,

            section: None,
            visibility: Default::default(),
            retained: false,
        });
        module.globals.push(trust_ir::Global {
            name: "OLD_ARRAY".to_string(),
            ty: Ty::Vector(Box::new(Ty::I32), 4),
            mutable: false,
            initializer: Some(Constant::Array(vec![
                Constant::Int(1),
                Constant::Int(2),
                Constant::Int(3),
                Constant::Int(4),
            ])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,

            section: None,
            visibility: Default::default(),
            retained: false,
        });

        let mut func = Function::new(FuncId::new(0), "f", func_ty, BlockId::new(0));
        let mut block = Block::new(BlockId::new(0));
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::Vector(Box::new(Ty::I32), 4),
                value: Constant::Vector(vec![Constant::Int(1), Constant::Int(2)]),
            })
            .with_result(ValueId::new(0)),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);
        module
            .try_add_function(func)
            .expect("Module::try_add_function: test fixture");

        let errors = validate_module(&module);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'MASK'[1]"
                        && expected == "bool"
                        && actual == "int"
            )),
            "expected vector element-shape mismatch, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'OLD_ARRAY'"
                        && expected == "<4 x i32>"
                        && actual == "array[4]"
            )),
            "expected array constants to be rejected for vector declarations, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "function 'f' bb0"
                        && expected == "<4 x i32>"
                        && actual == "vector[2]"
            )),
            "expected vector lane-count mismatch, got {errors:?}"
        );
    }

