    #[test]
    fn nested_frames_validate_clean() {
        // Simulates nested `\E i : \E j : P(i,j)` — two distinct frame ids,
        // opened and closed in LIFO order within a single block.
        let mut func = Function::new(FuncId::new(0), "nested", FuncTyId::new(0), BlockId::new(0));
        let v = ValueId::new;
        let bb = BlockId::new;
        let mut b0 = Block::new(bb(0));
        b0.body.push(
            InstrNode::new(Inst::OpenFrame {
                def: BindingFrameDef::new(
                    BindingFrameId::new(0),
                    "outer_i",
                    vec![BindingSlot::new("i", Ty::I64)],
                ),
            })
            .with_result(v(10)),
        );
        b0.body.push(
            InstrNode::new(Inst::OpenFrame {
                def: BindingFrameDef::new(
                    BindingFrameId::new(1),
                    "inner_j",
                    vec![BindingSlot::new("j", Ty::I32)],
                ),
            })
            .with_result(v(11)),
        );
        // Close inner first (LIFO), then outer
        b0.body
            .push(InstrNode::new(Inst::CloseFrame { frame: v(11) }));
        b0.body
            .push(InstrNode::new(Inst::CloseFrame { frame: v(10) }));
        b0.body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(b0);

        let errors = validate_function(&func);
        assert!(
            errors.is_empty(),
            "expected clean nested frames, got {:?}",
            errors
        );
    }

    #[test]
    fn display_strings_are_sensible() {
        // Minimal check that Display output for each new ValidationError
        // variant compiles and is non-empty.
        let errs = [
            ValidationError::BindingFrameIdReused {
                block: 0,
                frame_id: 0,
            },
            ValidationError::BindingFrameNotOpen {
                block: 1,
                frame_value: 9,
            },
            ValidationError::BindingSlotOutOfRange {
                block: 2,
                frame_id: 0,
                slot: 3,
                arity: 1,
            },
            ValidationError::BindingSlotTypeMismatch {
                block: 3,
                frame_id: 0,
                slot: 0,
                expected: "I64".into(),
                actual: "Bool".into(),
            },
            ValidationError::BindingBindTypeMismatch {
                block: 4,
                frame_id: 0,
                slot: 0,
                expected: "I64".into(),
                actual: "Bool".into(),
            },
            ValidationError::BindingUseAfterClose {
                block: 5,
                frame_value: 10,
            },
            ValidationError::BindingFrameUnclosed {
                block: 6,
                frame_id: 0,
            },
            ValidationError::BindingFrameUnopened {
                block: 7,
                frame_value: 11,
            },
        ];
        for err in &errs {
            let s = format!("{err}");
            assert!(!s.is_empty(), "empty Display for {:?}", err);
        }
    }

    // ---------------------------------------------------------------------
    // Memory-role mutual exclusion (issue #40)
    // ---------------------------------------------------------------------

    /// Build a single-block function terminated by `return` whose entry
    /// block contains `body` before the `return`. Used to host instruction
    /// nodes that carry proof annotations we want to stress.
    fn func_with_body(name: &str, body: Vec<InstrNode>) -> Function {
        let mut func = Function::new(FuncId::new(0), name, FuncTyId::new(0), BlockId::new(0));
        let mut block = Block::new(BlockId::new(0));
        for node in body {
            block.body.push(node);
        }
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);
        func
    }

    #[test]
    fn memory_roles_single_role_accepted() {
        // An alloca annotated with a single memory-role is fine.
        let node = InstrNode::new(Inst::Alloca {
            ty: Ty::I32,
            count: None,
            align: None,
        })
        .with_result(ValueId::new(0))
        .with_proof(trust_ir::proof::ProofAnnotation::ReadonlyTable);
        let func = func_with_body("role_ok", vec![node]);
        let errors = validate_function(&func);
        let role_errors: Vec<_> = errors
            .iter()
            .filter(|e| {
                matches!(
                    e,
                    ValidationError::ConflictingMemoryRoles { .. }
                        | ValidationError::ConflictingFunctionMemoryRoles { .. }
                )
            })
            .collect();
        assert!(
            role_errors.is_empty(),
            "single memory-role should validate, got {:?}",
            errors
        );
    }

    #[test]
    fn memory_roles_no_role_accepted() {
        // No memory-role annotations at all — trivially fine.
        let node = InstrNode::new(Inst::Alloca {
            ty: Ty::I32,
            count: None,
            align: None,
        })
        .with_result(ValueId::new(0));
        let func = func_with_body("role_none", vec![node]);
        let errors = validate_function(&func);
        let role_errors: Vec<_> = errors
            .iter()
            .filter(|e| {
                matches!(
                    e,
                    ValidationError::ConflictingMemoryRoles { .. }
                        | ValidationError::ConflictingFunctionMemoryRoles { .. }
                )
            })
            .collect();
        assert!(
            role_errors.is_empty(),
            "no memory-role expected to validate"
        );
    }

    #[test]
    fn memory_roles_two_roles_rejected() {
        // ReadonlyTable + AppendOnlyBuffer: the exact contradiction R1 flagged.
        let node = InstrNode::new(Inst::Alloca {
            ty: Ty::I32,
            count: None,
            align: None,
        })
        .with_result(ValueId::new(7))
        .with_proof(trust_ir::proof::ProofAnnotation::ReadonlyTable)
        .with_proof(trust_ir::proof::ProofAnnotation::AppendOnlyBuffer);
        let func = func_with_body("role_two", vec![node]);
        let errors = validate_function(&func);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConflictingMemoryRoles {
                    block: 0,
                    value: Some(7),
                    roles,
                } if roles.len() == 2
                    && roles.iter().any(|r| r == "readonly_table")
                    && roles.iter().any(|r| r == "append_only_buffer")
            )),
            "expected ConflictingMemoryRoles for two roles, got {:?}",
            errors
        );
    }

    #[test]
    fn information_flow_tainted_reaches_trusted_sink_rejected() {
        // v1 is produced Tainted; a TrustedSink Return consumes it -> violation.
        let producer = InstrNode::new(Inst::Alloca {
            ty: Ty::I32,
            count: None,
            align: None,
        })
        .with_result(ValueId::new(1))
        .with_proof(trust_ir::proof::ProofAnnotation::Tainted);
        let sink = InstrNode::new(Inst::Return {
            values: vec![ValueId::new(1)],
        })
        .with_proof(trust_ir::proof::ProofAnnotation::TrustedSink);
        let func = func_with_body("ifc_violation", vec![producer, sink]);
        let errors = validate_function(&func);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::TaintedValueReachesTrustedSink { value: 1, .. }
            )),
            "expected TaintedValueReachesTrustedSink for v1, got {:?}",
            errors
        );
    }

    #[test]
    fn information_flow_untainted_to_trusted_sink_accepted() {
        // Same shape but v1 is NOT Tainted -> the sink is clean, no violation.
        let producer = InstrNode::new(Inst::Alloca {
            ty: Ty::I32,
            count: None,
            align: None,
        })
        .with_result(ValueId::new(1));
        let sink = InstrNode::new(Inst::Return {
            values: vec![ValueId::new(1)],
        })
        .with_proof(trust_ir::proof::ProofAnnotation::TrustedSink);
        let func = func_with_body("ifc_clean", vec![producer, sink]);
        let errors = validate_function(&func);
        assert!(
            !errors
                .iter()
                .any(|e| matches!(e, ValidationError::TaintedValueReachesTrustedSink { .. })),
            "untainted value into a trusted sink must be accepted, got {:?}",
            errors
        );
    }

