    /// A fixed-width increment is synthesized, but the Nat law-library bridge is
    /// not a proof of wrapping `i32` semantics. Directive synthesis therefore
    /// fails closed before any producer can mint `Certified`.
    #[cfg(feature = "giveback-anchor")]
    #[test]
    fn synthesized_fixed_width_incr_giveback_remains_non_authoritative() {
        use trust_ir::{
            BinOp, Block, BlockId, Constant, FuncId, FuncTyId, Function, Inst, InstrNode, Ty,
            ValueId,
        };
        use trust_ir_giveback::{
            GiveBackOutcome, elaborate_give_back, give_back_recheck_directive,
        };

        let v = ValueId::new;
        // Build incr(x: &mut i32) { *x += 1 }.
        let entry = BlockId::new(0);
        let mut func = Function::new(FuncId::new(11), "incr", FuncTyId::new(0), entry);
        let mut block = Block::new(entry);
        block.params.push((v(0), Ty::RefMut(Box::new(Ty::I32))));
        block
            .body
            .push(InstrNode::new(Inst::BorrowMut { ptr: v(0) }).with_result(v(1)));
        block.body.push(
            InstrNode::new(Inst::Load {
                ty: Ty::I32,
                ptr: v(1),
                volatile: false,
                align: None,
            })
            .with_result(v(2)),
        );
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(1),
            })
            .with_result(v(3)),
        );
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::I32,
                lhs: v(2),
                rhs: v(3),
            })
            .with_result(v(4)),
        );
        block.body.push(InstrNode::new(Inst::Store {
            ty: Ty::I32,
            ptr: v(1),
            value: v(4),
            volatile: false,
            align: None,
        }));
        block
            .body
            .push(InstrNode::new(Inst::EndBorrow { borrow_ptr: v(1) }));
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);

        // (1) UNTRUSTED elaborator synthesizes the give-back view.
        let view = match elaborate_give_back(&func) {
            GiveBackOutcome::Accepted(view) => view,
            other => panic!("incr must be in the give-back decidable subset, got {other:?}"),
        };
        assert!(
            give_back_recheck_directive(&view).is_none(),
            "a Nat increment theorem must not authorize wrapping i32 give-back semantics"
        );
    }

    /// Aggregate synthesis must not launder fixed-width field arithmetic through
    /// structural lens laws. The recursive arithmetic guard keeps this candidate
    /// non-authoritative.
    #[cfg(feature = "giveback-anchor")]
    #[test]
    fn synthesized_fixed_width_aggregate_giveback_remains_non_authoritative() {
        use trust_ir::{
            BinOp, Block, BlockId, Constant, FuncId, FuncTyId, Function, Inst, InstrNode, Ty,
            ValueId,
        };
        use trust_ir_giveback::{
            GiveBackOutcome, elaborate_give_back, give_back_recheck_directive,
        };

        let v = ValueId::new;
        // fn agg_fst_incr(p: &mut (i32, i32)) { p.0 += 1 }
        let entry = BlockId::new(0);
        let pair = Ty::Tuple(vec![Ty::I32, Ty::I32]);
        let mut func = Function::new(FuncId::new(12), "agg_fst_incr", FuncTyId::new(0), entry);
        let mut block = Block::new(entry);
        block
            .params
            .push((v(0), Ty::RefMut(Box::new(pair.clone()))));
        block
            .body
            .push(InstrNode::new(Inst::BorrowMut { ptr: v(0) }).with_result(v(1)));
        block.body.push(
            InstrNode::new(Inst::Load {
                ty: pair.clone(),
                ptr: v(1),
                volatile: false,
                align: None,
            })
            .with_result(v(2)),
        );
        block.body.push(
            InstrNode::new(Inst::ExtractField {
                ty: Ty::I32,
                aggregate: v(2),
                field: 0,
            })
            .with_result(v(3)),
        );
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(1),
            })
            .with_result(v(4)),
        );
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::I32,
                lhs: v(3),
                rhs: v(4),
            })
            .with_result(v(5)),
        );
        block.body.push(
            InstrNode::new(Inst::InsertField {
                ty: pair.clone(),
                aggregate: v(2),
                field: 0,
                value: v(5),
            })
            .with_result(v(6)),
        );
        block.body.push(InstrNode::new(Inst::Store {
            ty: pair,
            ptr: v(1),
            value: v(6),
            volatile: false,
            align: None,
        }));
        block
            .body
            .push(InstrNode::new(Inst::EndBorrow { borrow_ptr: v(1) }));
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);

        // (1) UNTRUSTED elaborator synthesizes the NON-scalar give-back view.
        let view = match elaborate_give_back(&func) {
            GiveBackOutcome::Accepted(view) => view,
            other => {
                panic!(
                    "aggregate field incr must be in the give-back decidable subset, got {other:?}"
                )
            }
        };
        assert!(
            give_back_recheck_directive(&view).is_none(),
            "Nat aggregate laws must not authorize wrapping i32 field arithmetic"
        );
    }

    /// A polymorphic field-set directive is relevant and its fixed law library
    /// rechecks, but neither fact supplies an obligation-bound ground proof.
    /// The candidate must therefore remain non-authoritative.
    #[cfg(feature = "giveback-anchor")]
    #[test]
    fn synthesized_field0_set_laws_recheck_but_do_not_mint_certified() {
        use trust_ir::{Block, BlockId, FuncId, FuncTyId, Function, Inst, InstrNode, Ty, ValueId};
        use trust_ir_giveback::{
            GiveBackOutcome, elaborate_give_back, give_back_recheck_directive,
        };

        let v = ValueId::new;
        // fn set0(p: &mut (bool, i32), a: bool) { p.0 = a }
        let entry = BlockId::new(0);
        let pair = Ty::Tuple(vec![Ty::Bool, Ty::I32]);
        let mut func = Function::new(FuncId::new(22), "set0", FuncTyId::new(0), entry);
        let mut block = Block::new(entry);
        block
            .params
            .push((v(0), Ty::RefMut(Box::new(pair.clone()))));
        block.params.push((v(1), Ty::Bool));
        block
            .body
            .push(InstrNode::new(Inst::BorrowMut { ptr: v(0) }).with_result(v(2)));
        block.body.push(
            InstrNode::new(Inst::Load {
                ty: pair.clone(),
                ptr: v(2),
                volatile: false,
                align: None,
            })
            .with_result(v(3)),
        );
        block.body.push(
            InstrNode::new(Inst::InsertField {
                ty: pair.clone(),
                aggregate: v(3),
                field: 0,
                value: v(1),
            })
            .with_result(v(4)),
        );
        block.body.push(InstrNode::new(Inst::Store {
            ty: pair,
            ptr: v(2),
            value: v(4),
            volatile: false,
            align: None,
        }));
        block
            .body
            .push(InstrNode::new(Inst::EndBorrow { borrow_ptr: v(2) }));
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);

        let view = match elaborate_give_back(&func) {
            GiveBackOutcome::Accepted(view) => view,
            other => panic!("the field-0 set must be accepted, got {other:?}"),
        };
        let recheck = give_back_recheck_directive(&view)
            .expect("the synthesized field-0 set must map to an anchor");
        assert_eq!(recheck.anchor, "rust_giveback_aggregate");
        assert!(
            recheck
                .theorems
                .iter()
                .any(|t| t == "RustSem.GiveBack.fstLensP_putGet")
        );
        assert_giveback_law_library_rechecks(&recheck);

        let fid = func.id;
        let oblig = certified_giveback_obligation(0).with_function(fid);
        let lineage = clean_cic_lineage_digest(&oblig);
        let mut m = Module::new("giveback-field0-set-end-to-end");
        m.functions.push(func);
        m.proof_obligations.push(oblig);
        m.proof_certificates
            .push(clean_cic_cert_with_recheck(0, lineage, Some(recheck)));

        let errs = validate_certified_evidence(&m);
        assert_giveback_remains_non_authoritative(&errs);
    }

    /// Path-sensitive conditional synthesis does not erase the fixed-width
    /// arithmetic inside its taken branch. The recursive guard must decline a
    /// certifying directive for `i32` increment.
    #[cfg(feature = "giveback-anchor")]
