        let v = ValueId::new;
        // fn cond_incr(x: &mut i32, c: bool) { if c { *x += 1 } }
        let entry = BlockId::new(0);
        let mut func = Function::new(FuncId::new(13), "cond_incr", FuncTyId::new(0), entry);
        let mut b0 = Block::new(BlockId::new(0));
        b0.params.push((v(0), Ty::RefMut(Box::new(Ty::I32))));
        b0.params.push((v(9), Ty::Bool));
        b0.body
            .push(InstrNode::new(Inst::BorrowMut { ptr: v(0) }).with_result(v(1)));
        b0.body.push(InstrNode::new(Inst::CondBr {
            cond: v(9),
            then_target: BlockId::new(1),
            then_args: vec![],
            else_target: BlockId::new(2),
            else_args: vec![],
        }));
        let mut b1 = Block::new(BlockId::new(1));
        b1.body.push(
            InstrNode::new(Inst::Load {
                ty: Ty::I32,
                ptr: v(1),
                volatile: false,
                align: None,
            })
            .with_result(v(3)),
        );
        b1.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(1),
            })
            .with_result(v(4)),
        );
        b1.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::I32,
                lhs: v(3),
                rhs: v(4),
            })
            .with_result(v(5)),
        );
        b1.body.push(InstrNode::new(Inst::Store {
            ty: Ty::I32,
            ptr: v(1),
            value: v(5),
            volatile: false,
            align: None,
        }));
        b1.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(2),
            args: vec![],
        }));
        let mut b2 = Block::new(BlockId::new(2));
        b2.body
            .push(InstrNode::new(Inst::EndBorrow { borrow_ptr: v(1) }));
        b2.body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(b0);
