    /// (b'') ADVERSARIAL: an anchor without a dedicated obligation-binding path
    /// is rejected before generic theorem recheck. This also makes future anchor
    /// additions fail closed until their relevance binding is wired explicitly.
    #[test]
    fn certified_with_unknown_anchor_is_rejected() {
        let mut m = Module::new("certified");
        let oblig = certified_obligation(0);
        let lineage = clean_cic_lineage_digest(&oblig);
        m.proof_obligations.push(oblig);
        let recheck = CleanCicKernelRecheck {
            module: "Crownproof.SlackCertZ".to_string(),
            theorems: vec![FARKAS_THM.to_string()],
            anchor: "no_such_anchor".to_string(),
            allowed_axioms: standard_axioms(),
            binding: None,
        };
        m.proof_certificates
            .push(clean_cic_cert_with_recheck(0, lineage, Some(recheck)));

        let errs = validate_certified_evidence(&m);
        assert!(
            errs.iter().any(|e| matches!(
                e,
                ValidationError::CertifiedCleanCicKernelRecheckFailed { obligation: 0, reason }
                    if reason.contains("no obligation-bound Certified validation path")
            )),
            "expected unknown-anchor cert to be REJECTED, got: {errs:?}"
        );
    }

    /// (d') A cited theorem with an empty allow-list passes iff it is genuinely
