    /// A CleanCic certificate whose lineage is bound to a DIFFERENT obligation
    /// does not certify this one (guards against certificate replay).
    #[test]
    fn certified_with_mismatched_clean_cic_lineage_is_rejected() {
        let mut m = Module::new("certified");
        m.proof_obligations.push(certified_obligation(0));
        // Lineage minted for a different obligation id → not bound to #0.
        let other = certified_obligation(7);
        let wrong_lineage = clean_cic_lineage_digest(&other);
        m.proof_certificates.push(clean_cic_cert(0, wrong_lineage));

        let errs = validate_certified_evidence(&m);
        assert!(
            errs.contains(&ValidationError::CertifiedCleanCicLineageMismatch { obligation: 0 }),
            "expected CertifiedCleanCicLineageMismatch, got: {errs:?}"
        );
    }

    /// (d) A lineage-mismatched cert is REJECTED before the kernel even runs —
    /// even when it carries a (valid) kernel-recheck directive.
    #[test]
    fn certified_with_mismatched_lineage_and_recheck_is_rejected() {
        let mut m = Module::new("certified");
        m.proof_obligations.push(certified_obligation(0));
        let other = certified_obligation(7);
        let wrong_lineage = clean_cic_lineage_digest(&other);
        let recheck = CleanCicKernelRecheck {
            module: "Crownproof.SlackCertZ".to_string(),
            theorems: vec![FARKAS_THM.to_string()],
            anchor: farkas_anchor(),
            allowed_axioms: standard_axioms(),
            binding: None,
        };
        m.proof_certificates
            .push(clean_cic_cert_with_recheck(0, wrong_lineage, Some(recheck)));

        let errs = validate_certified_evidence(&m);
        assert!(
            errs.contains(&ValidationError::CertifiedCleanCicLineageMismatch { obligation: 0 }),
            "expected CertifiedCleanCicLineageMismatch, got: {errs:?}"
        );
    }

    /// `Discharged`/`Trusted` obligations carry no CleanCic requirement.
    #[test]
    fn non_certified_obligation_needs_no_clean_cic() {
        let mut m = Module::new("discharged");
        m.proof_obligations.push(ProofObligation {
            id: ProofId::new(0),
            kind: ObligationKind::Postcondition,
            status: ProofStatus::Discharged,
            description: "ok".to_string(),
            formula: None,
            function: None,
            source: None,
            site: None,
            spec: None,
        });
        m.proof_obligations.push(ProofObligation {
            id: ProofId::new(1),
            kind: ObligationKind::Postcondition,
            status: ProofStatus::Trusted,
            description: "manual".to_string(),
            formula: None,
            function: None,
            source: None,
            site: None,
            spec: None,
        });

        let errs = validate_certified_evidence(&m);
        assert!(errs.is_empty(), "expected no errors, got: {errs:?}");
    }

    /// The invariant is wired into the top-level `validate_module` entrypoint.
    #[test]
    fn certified_evidence_rule_is_wired_into_validate_module() {
        let mut m = Module::new("certified");
        m.proof_obligations.push(certified_obligation(0));

        let errs = validate_module(&m);
        assert!(
            errs.iter().any(|e| matches!(
                e,
                ValidationError::CertifiedWithoutCleanCic { obligation: 0 }
            )),
            "expected CertifiedWithoutCleanCic from validate_module, got: {errs:?}"
        );
    }

    // -----------------------------------------------------------------------
    // SlackCertZ (REAL Mathlib-dependent) kernel anchor
    // -----------------------------------------------------------------------

    /// FAST: the new `KERNEL_ANCHOR_SLACKCERTZ` const exists, is a
    /// distinct, stable identifier, a cert citing an UNKNOWN anchor is REJECTED
    /// fail-closed, AND (feature OFF) the LITERAL `KERNEL_ANCHOR_SLACKCERTZ` is
    /// itself rejected fail-closed — directly asserting the off-path so an
    /// accidental un-gating of the arm is caught. The heavy real-theorem load path
    /// remains available through the explicitly opted-in, resource-watched
    /// feature-gated qualification below.
    #[test]
    fn slackcertz_const_exists_and_unknown_anchor_still_rejects() {
        // The const is present, non-empty, and distinct from the constructive one.
        assert_eq!(
            trust_ir::proof::KERNEL_ANCHOR_SLACKCERTZ,
            "crownproof_slackcertz"
        );
        assert_ne!(
            trust_ir::proof::KERNEL_ANCHOR_SLACKCERTZ,
            trust_ir::proof::KERNEL_ANCHOR_FARKAS_CONSTRUCTIVE
        );

        // A cert citing a definitively-unknown anchor is rejected fail-closed.
        let mut m = Module::new("certified");
        let oblig = certified_obligation(0);
        let lineage = clean_cic_lineage_digest(&oblig);
        m.proof_obligations.push(oblig);
        let recheck = CleanCicKernelRecheck {
            module: "Crownproof.SlackCertZ".to_string(),
            theorems: vec!["Crownproof.SlackCertZ.checkSlackEntailmentZ_sound".to_string()],
            anchor: "definitely_not_a_real_anchor".to_string(),
            allowed_axioms: standard_axioms(),
            binding: None,
        };
        m.proof_certificates
            .push(clean_cic_cert_with_recheck(0, lineage, Some(recheck)));

        let errs = validate_certified_evidence(&m);
        assert!(
            errs.iter().any(|e| matches!(
                e,
                ValidationError::CertifiedCleanCicKernelRecheckFailed { obligation: 0, .. }
            )),
            "expected unknown-anchor cert to be REJECTED fail-closed, got: {errs:?}"
        );

        // Directly exercise the OFF-PATH reject of the LITERAL SlackCertZ anchor
        // (audit fix): when the feature is OFF, KERNEL_ANCHOR_SLACKCERTZ itself
        // must fall to the unknown-anchor Err arm. Asserting on the literal const
        // (not an arbitrary string) guards against a future regression that
        // accidentally un-gates the arm. (Skipped when the feature is ON, where the
        // anchor is known and would trigger the heavy ~6GB olean load.)
        #[cfg(not(feature = "slackcertz-anchor"))]
        {
            let recheck2 = CleanCicKernelRecheck {
                module: "Crownproof.SlackCertZ".to_string(),
                theorems: vec!["Crownproof.SlackCertZ.checkSlackEntailmentZ_sound".to_string()],
                anchor: trust_ir::proof::KERNEL_ANCHOR_SLACKCERTZ.to_string(),
                allowed_axioms: standard_axioms(),
                binding: None,
            };
            let result = clean_cic_kernel::recheck(&recheck2);
            assert!(
                result.is_err(),
                "with the slackcertz-anchor feature OFF, the literal SlackCertZ anchor \
                 must be rejected fail-closed, got: {result:?}"
            );
        }
    }

    /// REAL THEOREM re-check qualification (heavy; explicit opt-in).
    ///
    /// Builds the `KERNEL_ANCHOR_SLACKCERTZ` environment by LOADING the vendored
    /// `.olean` closure of `Crownproof.SlackCertZ` (Lean stdlib + full Mathlib +
    /// package deps + the Crownproof library) into the trusted `clean-kernel`,
    /// then `recheck_one_theorem`s the LITERAL Mathlib-dependent theorem
    /// `Crownproof.SlackCertZ.checkSlackEntailmentZ_sound` against the standard
    /// CIC trust base `{propext, Classical.choice, Quot.sound}` and asserts `Ok`.
    ///
    /// The closure load has a one-time ~6GB / ~21min cost (OBSERVED 1258.12s
    /// on 2026-06-28). It has been RUN and OBSERVED GREEN: the in-process
    /// clean-kernel re-check of the literal Mathlib-dependent term succeeded
    /// against `{propext, Classical.choice, Quot.sound}`. (This is the in-tree
    /// demonstration; the separate Mathverse gate independently proved the same
    /// theorem `KernelVerifiedWithProof`.)
    ///
    /// A normal all-features test run executes only the bounded opt-in guard.
    /// The test name and captured diagnostic explicitly say that no replay
    /// occurred, so its passing status is not a fresh SlackCertZ qualification.
    /// Run the real replay explicitly, alone, on Linux with a declared process
    /// RSS ceiling and wall deadline:
    ///
    /// ```text
    /// TRUST_IR_RUN_SLACKCERTZ_QUALIFICATION=1 \
    /// TRUST_IR_SLACKCERTZ_RSS_LIMIT_MIB=8192 \
    /// TRUST_IR_SLACKCERTZ_WALL_SECS=1800 \
    /// targo --unverified test -p trust-ir-build --features slackcertz-anchor \
    ///   slackcertz_runner_replays_only_when_explicitly_qualified -- \
    ///   --nocapture --test-threads=1
    /// ```
    ///
    /// The qualification refuses to start without at least the declared RSS
    /// ceiling plus 2 GiB of available host memory. While it runs, a watchdog
    /// aborts the isolated test process if its RSS exceeds the ceiling, host
    /// headroom falls below 2 GiB, or the wall deadline expires. Only a completed
    /// replay prints `SLACKCERTZ_REAL_THEOREM_RECHECKED`.
    ///
    /// Compiled only under the `slackcertz-anchor` feature (it reaches into
    /// `clean_cic_kernel::{build_anchor_env,recheck_one_theorem}` whose SlackCertZ
    /// arm is feature-gated).
    #[cfg(feature = "slackcertz-anchor")]
    #[test]
    fn slackcertz_runner_replays_only_when_explicitly_qualified() {
        const RUN_ENV: &str = "TRUST_IR_RUN_SLACKCERTZ_QUALIFICATION";
        const RSS_LIMIT_ENV: &str = "TRUST_IR_SLACKCERTZ_RSS_LIMIT_MIB";
        const WALL_SECS_ENV: &str = "TRUST_IR_SLACKCERTZ_WALL_SECS";
        const MIN_RSS_LIMIT_MIB: u64 = 8 * 1024;
        #[cfg(target_os = "linux")]
        const HOST_RESERVE_MIB: u64 = 2 * 1024;
        const MIN_WALL_SECS: u64 = 1_500;
        const MAX_WALL_SECS: u64 = 7_200;
        const THEOREM: &str = "Crownproof.SlackCertZ.checkSlackEntailmentZ_sound";

        let qualification_requested = match std::env::var(RUN_ENV) {
            Ok(value) => {
                assert_eq!(
                    value, "1",
                    "{RUN_ENV} must be exactly 1 when present; refusing an ambiguous \
                     qualification request"
                );
                true
            }
            Err(std::env::VarError::NotPresent) => false,
            Err(error) => panic!("{RUN_ENV} is not valid Unicode: {error}"),
        };
        if !qualification_requested {
            assert!(
                std::env::var_os(RSS_LIMIT_ENV).is_none()
                    && std::env::var_os(WALL_SECS_ENV).is_none(),
                "{RSS_LIMIT_ENV} and {WALL_SECS_ENV} are meaningful only with \
                 {RUN_ENV}=1; refusing an ambiguous non-replay invocation"
            );
            // This is the bounded default invariant. Keep the exact authority
            // identity checked without loading any `.olean` closure, and make
            // the absence of a fresh replay explicit in captured output.
            assert_eq!(
                trust_ir::proof::KERNEL_ANCHOR_SLACKCERTZ,
                "crownproof_slackcertz"
            );
            eprintln!(
                "SlackCertZ qualification NOT RUN: set {RUN_ENV}=1 together with \
                 {RSS_LIMIT_ENV} and {WALL_SECS_ENV}; this passing guard does not \
                 claim that {THEOREM} was replayed"
            );
            return;
        }

        let rss_limit_mib = std::env::var(RSS_LIMIT_ENV)
            .unwrap_or_else(|_| panic!("{RSS_LIMIT_ENV} is required when {RUN_ENV}=1"))
            .parse::<u64>()
            .unwrap_or_else(|error| {
                panic!("{RSS_LIMIT_ENV} must be an integer MiB value: {error}")
            });
        assert!(
            rss_limit_mib >= MIN_RSS_LIMIT_MIB,
            "{RSS_LIMIT_ENV}={rss_limit_mib} is below the {MIN_RSS_LIMIT_MIB} MiB \
             qualification floor"
        );
        let wall_secs = std::env::var(WALL_SECS_ENV)
            .unwrap_or_else(|_| panic!("{WALL_SECS_ENV} is required when {RUN_ENV}=1"))
            .parse::<u64>()
            .unwrap_or_else(|error| panic!("{WALL_SECS_ENV} must be integer seconds: {error}"));
        assert!(
            (MIN_WALL_SECS..=MAX_WALL_SECS).contains(&wall_secs),
            "{WALL_SECS_ENV}={wall_secs} must be within \
             {MIN_WALL_SECS}..={MAX_WALL_SECS} seconds"
        );

        #[cfg(not(target_os = "linux"))]
        panic!(
            "the resource-watched SlackCertZ qualification currently requires Linux /proc; \
             refusing to run the ~6GB replay without enforceable RSS and host-headroom checks"
        );

        #[cfg(target_os = "linux")]
        {
            use std::sync::Arc;
            use std::sync::atomic::{AtomicBool, Ordering};
            use std::time::{Duration, Instant};

            fn proc_kib_field(path: &str, field: &str) -> Option<u64> {
                let contents = std::fs::read_to_string(path).ok()?;
                contents.lines().find_map(|line| {
                    let mut words = line.split_whitespace();
                    if words.next()? != field {
                        return None;
                    }
                    words.next()?.parse::<u64>().ok()
                })
            }

            fn kib_to_mib_ceil(kib: u64) -> u64 {
                kib.div_ceil(1024)
            }

            fn available_memory_mib() -> Option<u64> {
                proc_kib_field("/proc/meminfo", "MemAvailable:").map(kib_to_mib_ceil)
            }

            fn process_rss_mib() -> Option<u64> {
                proc_kib_field("/proc/self/status", "VmRSS:").map(kib_to_mib_ceil)
            }

            let available_before = available_memory_mib()
                .expect("Linux /proc/meminfo must expose MemAvailable for qualification");
            let required_before = rss_limit_mib.saturating_add(HOST_RESERVE_MIB);
            assert!(
                available_before >= required_before,
                "SlackCertZ qualification requires at least {required_before} MiB available \
                 ({rss_limit_mib} MiB RSS ceiling + {HOST_RESERVE_MIB} MiB host reserve), \
                 but /proc/meminfo reports {available_before} MiB"
            );

            let completed = Arc::new(AtomicBool::new(false));
            let watchdog_completed = Arc::clone(&completed);
            let watchdog = std::thread::Builder::new()
                .name("slackcertz-resource-watchdog".to_string())
                .spawn(move || {
                    let deadline = Instant::now() + Duration::from_secs(wall_secs);
                    loop {
                        if watchdog_completed.load(Ordering::Acquire) {
                            return;
                        }
                        let rss = process_rss_mib().unwrap_or_else(|| {
                            eprintln!("SlackCertZ qualification ABORTED: cannot read process RSS");
                            std::process::abort();
                        });
                        let available = available_memory_mib().unwrap_or_else(|| {
                            eprintln!(
                                "SlackCertZ qualification ABORTED: cannot read host memory headroom"
                            );
                            std::process::abort();
                        });
                        if rss > rss_limit_mib {
                            eprintln!(
                                "SlackCertZ qualification ABORTED: RSS {rss} MiB exceeds \
                                 declared {rss_limit_mib} MiB ceiling"
                            );
                            std::process::abort();
                        }
                        if available < HOST_RESERVE_MIB {
                            eprintln!(
                                "SlackCertZ qualification ABORTED: host headroom {available} MiB \
                                 fell below {HOST_RESERVE_MIB} MiB reserve"
                            );
                            std::process::abort();
                        }
                        if Instant::now() >= deadline {
                            eprintln!(
                                "SlackCertZ qualification ABORTED: exceeded declared \
                                 {wall_secs}s wall deadline"
                            );
                            std::process::abort();
                        }
                        std::thread::sleep(Duration::from_secs(1));
                    }
                })
                .expect("spawn SlackCertZ resource watchdog");

            // OBSERVED GREEN 2026-06-28: 1 passed in 1258.12s (~21min). The
            // closure load + in-process kernel recursion is deep enough to
            // overflow libtest's DEFAULT thread stack (observed: SIGABRT stack
            // overflow), so we run the
            // re-check on a thread with a large explicit stack.
            let worker = std::thread::Builder::new()
                .name("slackcertz-kernel-recheck".to_string())
                .stack_size(2 * 1024 * 1024 * 1024) // 2 GiB
                .spawn(|| {
                    let allowed = standard_axioms();
                    // Build the real env via the feature-gated anchor arm, then
                    // re-check the literal theorem's proof TERM in-process
                    // (de Bruijn, no external Lean process).
                    let env = clean_cic_kernel::build_anchor_env(
                        trust_ir::proof::KERNEL_ANCHOR_SLACKCERTZ,
                    )
                    .expect("build SlackCertZ olean-closure anchor env");
                    let result = clean_cic_kernel::recheck_one_theorem(&env, THEOREM, &allowed);
                    assert!(
                        result.is_ok(),
                        "in-process kernel must re-check the LITERAL Mathlib-dependent theorem \
                         {THEOREM}, got: {result:?}"
                    );
                });
            let worker = match worker {
                Ok(worker) => worker,
                Err(error) => {
                    completed.store(true, Ordering::Release);
                    watchdog
                        .join()
                        .expect("SlackCertZ resource watchdog must stop");
                    panic!("spawn big-stack SlackCertZ kernel-recheck thread: {error}");
                }
            };
            let replay = worker.join();
            completed.store(true, Ordering::Release);
            watchdog
                .join()
                .expect("SlackCertZ resource watchdog must stop");
            replay.expect("SlackCertZ in-process kernel re-check thread must succeed");
            eprintln!(
                "SLACKCERTZ_REAL_THEOREM_RECHECKED theorem={THEOREM} \
                 rss_limit_mib={rss_limit_mib} wall_secs={wall_secs}"
            );
        }
    }

    // -----------------------------------------------------------------
    // SeqMap (general element-op loop) well-formedness: the element
    // function must exist and be the single-&mut form `fn(&mut elem)` over
    // the sequence's element type (designs/2026-06-30-general-seqmap-
    // instruction.md).
    // -----------------------------------------------------------------

    /// Build `incr_all(l: Seq<i32>) -> Seq<i32> { %1 = seq_map %0, @incr_elem;
    /// ret %1 }` + `incr_elem(x: &mut i32) { *x += 1 }`.
    fn seq_map_general_module() -> Module {
        use trust_ir::{Block, BlockId, FuncId, FuncTy, Function, Inst, InstrNode, Ty, ValueId};
        let v = ValueId::new;
        let mut m = Module::new("seq-map-general");
        let i32_id = m.add_type(Ty::I32).expect("Module::add_type: test fixture");
        let seq_ty = Ty::Sequence(i32_id);
        let loop_ty = m
            .add_func_type(FuncTy {
                params: vec![seq_ty.clone()],
                returns: vec![seq_ty.clone()],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let elem_fn_ty = m
            .add_func_type(FuncTy {
                params: vec![Ty::RefMut(Box::new(Ty::I32))],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");

        let mut incr_all = Function::new(FuncId::new(0), "incr_all", loop_ty, BlockId::new(0));
        let mut entry = Block::new(BlockId::new(0));
        entry.params.push((v(0), seq_ty.clone()));
        entry.body.push(
            InstrNode::new(Inst::SeqMap {
                ty: seq_ty.clone(),
                seq: v(0),
                fwd: FuncId::new(1),
            })
            .with_result(v(1)),
        );
        entry
            .body
            .push(InstrNode::new(Inst::Return { values: vec![v(1)] }));
        incr_all.blocks.push(entry);

        let mut incr_elem = Function::new(FuncId::new(1), "incr_elem", elem_fn_ty, BlockId::new(0));
        let mut eb = Block::new(BlockId::new(0));
        eb.params.push((v(0), Ty::RefMut(Box::new(Ty::I32))));
        eb.body.push(
            InstrNode::new(Inst::Load {
                ty: Ty::I32,
                ptr: v(0),
                volatile: false,
                align: None,
            })
            .with_result(v(1)),
        );
        eb.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(1),
            })
            .with_result(v(2)),
        );
        eb.body.push(
            InstrNode::new(Inst::BinOp {
                op: trust_ir::BinOp::Add,
                ty: Ty::I32,
                lhs: v(1),
                rhs: v(2),
            })
            .with_result(v(3)),
        );
        eb.body.push(InstrNode::new(Inst::Store {
            ty: Ty::I32,
            ptr: v(0),
            value: v(3),
            volatile: false,
            align: None,
        }));
        eb.body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        incr_elem.blocks.push(eb);

        m.functions.push(incr_all);
        m.functions.push(incr_elem);
        m
    }

    #[test]
    fn seq_map_with_valid_element_function_validates() {
        let m = seq_map_general_module();
        let errs = validate_module(&m);
        assert!(
            errs.iter().all(|e| !matches!(
                e,
                ValidationError::SeqMapFwdNotFound { .. }
                    | ValidationError::SeqMapTypeNotSequence { .. }
                    | ValidationError::SeqMapFwdSignatureMismatch { .. }
            )),
            "a well-formed seq_map must not raise SeqMap errors, got: {errs:?}"
        );
    }

    #[test]
    fn seq_map_missing_element_function_is_rejected() {
        use trust_ir::{FuncId, Inst};
        let mut m = seq_map_general_module();
        let Inst::SeqMap { fwd, .. } = &mut m.functions[0].blocks[0].body[0].inst else {
            panic!("first body inst is the seq_map");
        };
        *fwd = FuncId::new(99);
        let errs = validate_module(&m);
        assert!(
            errs.iter()
                .any(|e| matches!(e, ValidationError::SeqMapFwdNotFound { fwd_id: 99, .. })),
            "a seq_map naming a missing element function must be rejected, got: {errs:?}"
        );
    }

    #[test]
    fn seq_map_by_value_element_function_is_rejected() {
        use trust_ir::{FuncTy, Ty};
        let mut m = seq_map_general_module();
        // Break the element function's signature: by-value fn(i32) -> i32.
        let bad = m
            .add_func_type(FuncTy {
                params: vec![Ty::I32],
                returns: vec![Ty::I32],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        m.functions[1].ty = bad;
        let errs = validate_module(&m);
        assert!(
            errs.iter()
                .any(|e| matches!(e, ValidationError::SeqMapFwdSignatureMismatch { .. })),
            "a by-value element function must be rejected, got: {errs:?}"
        );
    }

    #[test]
    fn seq_map_wrong_pointee_element_function_is_rejected() {
        use trust_ir::{FuncTy, Ty};
        let mut m = seq_map_general_module();
        // fn(&mut bool) against a Seq<i32>: pointee mismatch.
        let bad = m
            .add_func_type(FuncTy {
                params: vec![Ty::RefMut(Box::new(Ty::Bool))],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        m.functions[1].ty = bad;
        let errs = validate_module(&m);
        assert!(
            errs.iter()
                .any(|e| matches!(e, ValidationError::SeqMapFwdSignatureMismatch { .. })),
            "an element function over the wrong pointee must be rejected, got: {errs:?}"
        );
    }

    #[test]
    fn seq_map_non_sequence_type_is_rejected() {
        use trust_ir::{Inst, Ty};
        let mut m = seq_map_general_module();
        let Inst::SeqMap { ty, .. } = &mut m.functions[0].blocks[0].body[0].inst else {
            panic!("first body inst is the seq_map");
        };
        *ty = Ty::I32;
        let errs = validate_module(&m);
        assert!(
            errs.iter()
                .any(|e| matches!(e, ValidationError::SeqMapTypeNotSequence { .. })),
            "a seq_map whose type is not a sequence must be rejected, got: {errs:?}"
        );
    }

    /// Build the general-SeqMap loop module for the e2e cert tests: the loop
    /// `incr_all(l: &mut Seq<i32>)` lowered with `Inst::SeqMap { fwd }` plus
    /// the single-&mut element function `incr_elem(x: &mut i32) { *x += 1 }`,
    /// with the interned element type and both signatures the module-threaded
    /// elaboration resolves.
    #[cfg(feature = "giveback-anchor")]
    fn seq_map_general_giveback_module() -> Module {
        use trust_ir::{Block, BlockId, FuncId, FuncTy, Function, Inst, InstrNode, Ty, ValueId};
        let v = ValueId::new;
        let mut m = Module::new("giveback-seq-map-general");
        let i32_id = m.add_type(Ty::I32).expect("Module::add_type: test fixture");
        let seq_ty = Ty::Sequence(i32_id);
        let _loop_ft = m
            .add_func_type(FuncTy {
                params: vec![Ty::RefMut(Box::new(seq_ty.clone()))],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");
        let _elem_ft = m
            .add_func_type(FuncTy {
                params: vec![Ty::RefMut(Box::new(Ty::I32))],
                returns: vec![],
                abi: None,
                is_vararg: false,
            })
            .expect("Module::add_func_type: test fixture");

        // fn incr_all(l: &mut Seq<i32>) { l' = seq_map l, @incr_elem }
        let mut loop_fn = Function::new(
            FuncId::new(40),
            "incr_all",
            trust_ir::FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut b = Block::new(BlockId::new(0));
        b.params.push((v(0), Ty::RefMut(Box::new(seq_ty.clone()))));
        b.body
            .push(InstrNode::new(Inst::BorrowMut { ptr: v(0) }).with_result(v(1)));
        b.body.push(
            InstrNode::new(Inst::Load {
                ty: seq_ty.clone(),
                ptr: v(1),
                volatile: false,
                align: None,
            })
            .with_result(v(2)),
        );
        b.body.push(
            InstrNode::new(Inst::SeqMap {
                ty: seq_ty.clone(),
                seq: v(2),
                fwd: FuncId::new(41),
            })
            .with_result(v(3)),
        );
        b.body.push(InstrNode::new(Inst::Store {
            ty: seq_ty,
            ptr: v(1),
            value: v(3),
            volatile: false,
            align: None,
        }));
        b.body
            .push(InstrNode::new(Inst::EndBorrow { borrow_ptr: v(1) }));
        b.body.push(InstrNode::new(Inst::Return { values: vec![] }));
        loop_fn.blocks.push(b);
        m.functions.push(loop_fn);

        // fn incr_elem(x: &mut i32) { *x += 1 }
        let mut elem_fn = Function::new(
            FuncId::new(41),
            "incr_elem",
            trust_ir::FuncTyId::new(1),
            BlockId::new(0),
        );
        let mut eb = Block::new(BlockId::new(0));
        eb.params.push((v(0), Ty::RefMut(Box::new(Ty::I32))));
        eb.body
            .push(InstrNode::new(Inst::BorrowMut { ptr: v(0) }).with_result(v(1)));
        eb.body.push(
            InstrNode::new(Inst::Load {
                ty: Ty::I32,
                ptr: v(1),
                volatile: false,
                align: None,
            })
            .with_result(v(2)),
        );
        eb.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(1),
            })
            .with_result(v(3)),
        );
        eb.body.push(
            InstrNode::new(Inst::BinOp {
                op: trust_ir::BinOp::Add,
                ty: Ty::I32,
                lhs: v(2),
                rhs: v(3),
            })
            .with_result(v(4)),
        );
        eb.body.push(InstrNode::new(Inst::Store {
            ty: Ty::I32,
            ptr: v(1),
            value: v(4),
            volatile: false,
            align: None,
        }));
        eb.body
            .push(InstrNode::new(Inst::EndBorrow { borrow_ptr: v(1) }));
        eb.body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        elem_fn.blocks.push(eb);
        m.functions.push(elem_fn);

        m
    }

    /// A general `SeqMap` must recurse into its exact element function before
    /// selecting a directive. Here that function performs wrapping `i32`
    /// arithmetic, so the loop remains non-authoritative.
    #[cfg(feature = "giveback-anchor")]
    #[test]
    fn synthesized_fixed_width_seq_map_general_loop_remains_non_authoritative() {
        use trust_ir_giveback::{
            GiveBackOutcome, elaborate_give_back_in, give_back_recheck_directive_in,
        };

        let m0 = seq_map_general_giveback_module();
        let loop_fn = m0.functions[0].clone();
        let view = match elaborate_give_back_in(&loop_fn, &m0) {
            GiveBackOutcome::Accepted(view) => view,
            other => panic!("the general SeqMap loop must be accepted, got {other:?}"),
        };
        assert!(
            give_back_recheck_directive_in(&view, &m0).is_none(),
            "the Nat element law must not authorize wrapping i32 SeqMap semantics"
        );
    }

    /// 🎯 ADVERSARIAL: the relevance check pins the general loop to its OWN
    /// directive. Citing the SeqMapAddK theorem set (`listMap_roundTrip` +
    /// `loop_roundTrip` + `loopFwd_cons` — true, axiom-clean, SAME anchor) for
    /// a general `SeqMap` loop is REJECTED: the re-derived directive is
    /// exactly `[listMapT_roundTrip]`.
    #[cfg(feature = "giveback-anchor")]
    #[test]
    fn giveback_relevance_rejects_addk_theorems_for_a_general_seq_map_loop() {
        use trust_ir::FuncId;

        let m0 = seq_map_general_giveback_module();
        let mut m = m0;
        let oblig = certified_giveback_obligation(0).with_function(FuncId::new(40));
        let lineage = clean_cic_lineage_digest(&oblig);
        let mis_citation = CleanCicKernelRecheck {
            module: "RustSem.GiveBack".to_string(),
            theorems: vec![
                "RustSem.GiveBack.listMap_roundTrip".to_string(),
                "RustSem.GiveBack.loop_roundTrip".to_string(),
                "RustSem.GiveBack.loopFwd_cons".to_string(),
            ],
            anchor: "rust_giveback_loop".to_string(),
            allowed_axioms: ["propext", "Classical.choice", "Quot.sound", "Eq.refl"]
                .iter()
                .map(|s| (*s).to_string())
                .collect(),
            binding: None,
        };
        m.proof_obligations.push(oblig);
        m.proof_certificates
            .push(clean_cic_cert_with_recheck(0, lineage, Some(mis_citation)));

        let errs = validate_certified_evidence(&m);
        assert!(
            errs.iter().any(|e| matches!(
                e,
                ValidationError::CertifiedCleanCicKernelRecheckFailed { obligation: 0, .. }
            )),
            "citing the SeqMapAddK theorem set for a general SeqMap loop must be REJECTED by \
             the relevance check, got: {errs:?}"
        );
    }

    /// Batteries-included on the general loop: both the loop and element
    /// function become visible Pending candidates, without placeholder certs.
    #[cfg(feature = "giveback-anchor")]
    #[test]
    fn certify_module_give_backs_stages_the_general_seq_map_loop_pending() {
        use trust_ir::FuncId;

        let mut m = seq_map_general_giveback_module();
        let report = certify_module_give_backs(&mut m);
        assert!(
            report.pending.contains(&FuncId::new(40)),
            "the general SeqMap loop must be Pending, got: {report:?}"
        );
        assert!(
            report.pending.contains(&FuncId::new(41)),
            "the element function must be independently Pending, got: {report:?}"
        );
        assert_eq!(report.certified_count(), 0);
        assert!(m.proof_certificates.is_empty());
        let reval = validate_certified_evidence(&m);
        assert!(
            reval.is_empty(),
            "Pending candidates must not create cert errors, got: {reval:?}"
        );
    }

    // ── clean-backend TRANSLATION-VALIDATION anchor (P2) ────────────────────
    //
    // The semantics-preservation certificate for clean's emit_trust_ir
    // backend: a per-decl equation `CleanTV.<fn>.denotes` whose LHS the
    // validator RE-DERIVES from the module's own function and whose proof the
    // in-process kernel re-checks. Accept the honest cert; REFUSE a post-emit
    // miscompile, a tampered/forged payload, an axiom-laundered proof, every
    // cross-domain anchor citation, and everything outside the fragment.

    /// The TV corpus fixture: `fn tv_demo(x: u32) -> u32 { (x + 7) * 3 }` —
    /// exactly what clean's backend emits for the corpus decl.
    fn tv_module() -> (Module, trust_ir::FuncId) {
        use trust_ir::constant::Constant;
        use trust_ir::inst::BinOp;
        use trust_ir::{
            Block, BlockId, FuncId, FuncTy, FuncTyId, Function, Inst, InstrNode, Ty, ValueId,
        };
        let mut m = Module::new("clean-backend-tv-fixture");
        m.func_types.push(FuncTy {
            params: vec![Ty::U32],
            returns: vec![Ty::U32],
            abi: None,
            is_vararg: false,
        });
        let fid = FuncId::new(0);
        let mut f = Function::new(fid, "tv_demo", FuncTyId::new(0), BlockId::new(0));
        let mut b = Block::new(BlockId::new(0));
        b.params.push((ValueId::new(0), Ty::U32));
        b.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::U32,
                value: Constant::Int(7),
            })
            .with_result(ValueId::new(1)),
        );
        b.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::U32,
                lhs: ValueId::new(0),
                rhs: ValueId::new(1),
            })
            .with_result(ValueId::new(2)),
        );
        b.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::U32,
                value: Constant::Int(3),
            })
            .with_result(ValueId::new(3)),
        );
        b.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Mul,
                ty: Ty::U32,
                lhs: ValueId::new(2),
                rhs: ValueId::new(3),
            })
            .with_result(ValueId::new(4)),
        );
        b.body.push(InstrNode::new(Inst::Return {
            values: vec![ValueId::new(4)],
        }));
        f.blocks.push(b);
        m.try_add_function(f)
            .expect("Module::try_add_function: test fixture");
        (m, fid)
    }

