    /// A function-less TV obligation cannot be relevance-checked and is
    /// rejected outright — mandatory `function`, no give-back-style residual
    /// gap for this kind.
    #[cfg(feature = "clean-tv-anchor")]
    #[test]
    fn functionless_tv_obligation_is_rejected() {
        let (mut m, fid) = tv_module();
        let mut oblig = tv_obligation(0, fid);
        oblig.function = None;
        let cert = {
            // Mint against the real function, then drop the obligation's
            // function pointer — the payload is fine, the binding is not.
            let bound = tv_obligation(0, fid);
            let mut c = mint_tv_cert(&m, &bound);
            // Lineage must match the (function-less) obligation actually pushed.
            let ProofEvidence::CleanCic { lineage, .. } = &mut c.evidence else {
                unreachable!()
            };
            *lineage = clean_cic_lineage_digest(&oblig);
            c
        };
        m.proof_obligations.push(oblig);
        m.proof_certificates.push(cert);

        let errs = validate_certified_evidence(&m);
        assert!(
            errs.iter().any(|e| match e {
                ValidationError::CertifiedCleanCicKernelRecheckFailed {
                    obligation: 0,
                    reason,
                } => reason.contains("carries no function"),
                _ => false,
            }),
            "a function-less TV obligation must be REJECTED, got: {errs:?}"
        );
    }

